const editorRole='20000000-0000-4000-8000-000000000001',reviewerRole='20000000-0000-4000-8000-000000000002',publisherRole='20000000-0000-4000-8000-000000000003';
async function actor(id,role='authenticated'){await db.exec('reset role');await db.query("select set_config('request.jwt.claim.sub',$1,false)",[id||'']);await db.exec(`set role ${role}`);}
async function root(){await db.exec('reset role');}
async function save(path,record=null,expected=null,payload={title:'Private forest journey'}){
 return (await db.query('select cms.save_draft($1,$2,$3,$4,$5,$6,$7::jsonb) as value',[site,record,expected,'journey',path,'Journey',JSON.stringify(payload)])).rows[0].value;
}
async function review(record,action){await db.query('select cms.review($1,$2,$3,$4)',[site,record.recordId,record.revisionId,action]);}
async function publish(record){return (await db.query('select cms.publish($1,$2,$3) as job',[site,record.recordId,record.revisionId])).rows[0].job;}
async function receipt(record,version='journey-2',valid=true,findings=[]){return db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[site,record.recordId,record.revisionId,version,valid,JSON.stringify(findings)]);}
async function validate(record){await actor(null,'service_role');await receipt(record);await root();}
