test('actual image worker persists a verified derivative and catalog entry with rights pending',async()=>{
 const bytes=await sharp({create:{width:20,height:10,channels:3,background:'#234638'}}).png().toBuffer();
 await actor(editor);const u=(await db.query("select cms.reserve_upload($1,$2,'forest.png','image/png',$3) as result",[site,randomUUID(),bytes.length])).rows[0].result;
 await assert.rejects(db.query('select cms.claim_upload($1,$2)',[site,u.id]),/permission denied/);
 await actor(null,'service_role');await db.query('select cms.confirm_upload($1,$2,$3,$4)',[site,u.id,createHash('sha256').update(bytes).digest('hex'),bytes.length]);
 const stored=new Map();
 const result=await processUpload({
  claim:async(s,id)=>(await db.query('select cms.claim_upload($1,$2) as value',[s,id])).rows[0].value,
  read:async()=>bytes,scan:async()=> 'clean',
  putVerified:async(key,data,hash)=>{assert.equal(createHash('sha256').update(data).digest('hex'),hash);stored.set(key,data);},
  finish:async(job,data)=>(await db.query('select cms.finish_upload($1,$2,$3,$4::jsonb) as value',[job.site,job.id,job.leaseToken,JSON.stringify(data)])).rows[0].value,
  fail:async()=>assert.fail('Unexpected failure'),
 },site,u.id);
 assert.equal(result.status,'ready');assert.equal(result.assetId,u.id);
 const media=(await db.query('select * from cms.media_objects where website_id=$1 and id=$2',[site,u.id])).rows[0];
 assert.equal(media.rights_status,'pending');assert.equal(media.inspection_status,'ready');assert.ok(stored.has(media.storage_key));
 assert.equal((await sharp(stored.get(media.storage_key)).metadata()).format,'webp');
 await actor(editor);assert.equal((await db.query('select cms.get_upload($1,$2) as result',[site,u.id])).rows[0].result.status,'ready');
});
