test('real stored content validator gates approval-to-publication without browser-supplied results',async()=>{
 await actor(editor);const payload={slug:'validated-flow',title:'Forest journey',description:'Visit the forest.',intro:'A guided forest journey.',region:'India',duration:'5 days',bestMonths:'November'};
 const draft=await save('/journeys/validated-flow',null,null,payload);await review(draft,'submit');await actor(reviewer);await review(draft,'approve');
 const transport=async(name,args)=>{
  if(name==='get_validation_input')return (await db.query('select cms.get_validation_input($1,$2,$3) as value',[args.p_site,args.p_record,args.p_revision])).rows[0].value;
  await db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]);
 };
 await actor(editor);await assert.rejects(db.query('select cms.get_validation_input($1,$2,$3)',[site,draft.recordId,draft.revisionId]),/permission denied/);
 await actor(null,'service_role');const result=await runTrustedValidation(transport,{site,record:draft.recordId,revision:draft.revisionId});assert.equal(result.contentChecksPass,true);
 await actor(publisher);assert.ok(await publish(draft));
 await actor(editor);const bad=await save('/journeys/validated-flow',draft.recordId,draft.revisionId,{...payload,intro:''});await review(bad,'submit');await actor(reviewer);await review(bad,'approve');
 await actor(null,'service_role');assert.equal((await runTrustedValidation(transport,{site,record:bad.recordId,revision:bad.revisionId})).contentChecksPass,false);
 await actor(publisher);await assert.rejects(publish(bad),/validated_revision_required/);
 await actor(null,'anon');assert.equal((await db.query('select cms.get_public_page($1,$2) as result',[site,'/journeys/validated-flow'])).rows[0].result.revisionId,draft.revisionId);
});
