test('reviewed journey manifests persist without losing preserved content',async()=>{
 await actor(editor);
 const first=await save('/journeys/review-integration',null,null,{title:'Original journey',intro:'Preserve this introduction',faqs:[{itemId:'q1',position:'1',question:'Original?',answer:'Keep answer'}]});
 const payload=(await db.query('select payload from cms.revisions where id=$1',[first.revisionId])).rows[0].payload;
 const input={templateVersion:'1.0',pageType:'journey',sheets:{Pages:[{recordId:first.recordId,operation:'update',expectedRevision:first.revisionId,title:'A revised private journey through the forest',intro:''}]}};
 const reviewed=reviewJourneyImport(input,[{id:first.recordId,revision:first.revisionId,slug:'review-integration',path:'/journeys/review-integration',locale:'en',title:'Original journey',payload}]);
 assert.equal(reviewed.valid,true);const saved=await apply(reviewed.manifest);
 const persisted=(await db.query('select payload from cms.revisions where id=$1',[saved[0].revisionId])).rows[0].payload;
 assert.equal(persisted.title,input.sheets.Pages[0].title);assert.equal(persisted.intro,payload.intro);assert.deepEqual(persisted.faqs,payload.faqs);
});
async function publishedFixture(path){
 await root();await db.exec("update cms.delivery_jobs set status='succeeded',lease_until=null,lease_token=null");
 await actor(editor);const draft=await save(path);await review(draft,'submit');await actor(reviewer);await review(draft,'approve');await validate(draft);await actor(publisher);return {...draft,job:await publish(draft)};
}
async function claim(){await actor(null,'service_role');return (await db.query('select cms.claim_delivery(50,60) as jobs')).rows[0].jobs;}
test('unpublish is permission-checked, revision-bound, idempotent and preserves drafts',async()=>{
 const draft=await publishedFixture('/journeys/unpublish');
 await actor(editor);await assert.rejects(db.query('select cms.unpublish($1,$2,$3)',[site,draft.recordId,draft.revisionId]),/forbidden/);
 await actor(publisher);await assert.rejects(db.query('select cms.unpublish($1,$2,$3)',[site,draft.recordId,randomUUID()]),/publication_conflict/);
 const args=[site,draft.recordId,draft.revisionId];const job=(await db.query('select cms.unpublish($1,$2,$3) as id',args)).rows[0].id;
 assert.equal((await db.query('select cms.unpublish($1,$2,$3) as id',args)).rows[0].id,job);
 assert.equal((await db.query('select current_revision_id from cms.records where id=$1',[draft.recordId])).rows[0].current_revision_id,draft.revisionId);
 await actor(null,'anon');assert.equal((await db.query('select cms.get_public_page($1,$2) as value',[site,'/journeys/unpublish'])).rows[0].value,null);
 const jobs=await claim();assert.equal(jobs.length,1);assert.equal(jobs[0].operation,'unpublish');
 await root();assert.equal((await db.query('select status from cms.delivery_jobs where id=$1',[draft.job])).rows[0].status,'superseded');
});
test('delivery leases cannot be claimed twice and old worker acknowledgements are fenced',async()=>{
 const draft=await publishedFixture('/journeys/lease');const [first]=await claim();assert.equal(first.id,draft.job);assert.equal((await claim()).length,0);
 await root();await db.query("update cms.delivery_jobs set lease_until=now()-interval '1 second' where id=$1",[first.id]);
 const [second]=await claim();assert.notEqual(second.leaseToken,first.leaseToken);assert.equal(second.attempt,2);
 await assert.rejects(db.query('select cms.finish_delivery($1,$2,true)',[first.id,first.leaseToken]),/delivery_lease_lost/);
 await db.query('select cms.finish_delivery($1,$2,true)',[second.id,second.leaseToken]);
 await root();assert.equal((await db.query('select status from cms.delivery_jobs where id=$1',[first.id])).rows[0].status,'succeeded');
});
test('delivery failures back off, enforce safe errors, and stop after eight attempts',async()=>{
 await publishedFixture('/journeys/retry');const [job]=await claim();
 await assert.rejects(db.query('select cms.finish_delivery($1,$2,false,$3)',[job.id,job.leaseToken,'raw secret URL https://example.test']),/safe_error_code_required/);
 await db.query('select cms.finish_delivery($1,$2,false,$3)',[job.id,job.leaseToken,'invalidation_failed']);assert.equal((await claim()).length,0);
 await root();await db.query("update cms.delivery_jobs set attempts=7,next_attempt_at=now()-interval '1 second' where id=$1",[job.id]);
 const [last]=await claim();assert.equal(last.attempt,8);
 await root();await db.query("update cms.delivery_jobs set lease_until=now()-interval '1 second' where id=$1",[job.id]);
 await actor(null,'service_role');assert.equal((await db.query('select cms.reap_delivery() as n')).rows[0].n,1);assert.equal((await claim()).length,0);
 await root();const terminal=(await db.query('select * from cms.delivery_jobs where id=$1',[job.id])).rows[0];assert.equal(terminal.status,'failed');assert.ok(terminal.finished_at);
});
