test('nested page images are site-scoped, block publication and withdraw on rights loss',async()=>{
 const image='nested-page-image';
 await actor(null,'service_role');await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Licensed')",[site,image,`${site}/${image}/delivery.webp`,'b'.repeat(64)]);
 await actor(editor);
 const payload={composition:{schemaVersion:1,title:'Nested images',sections:[{id:'hero',kind:'hero',controls:{visible:false},data:{desktop:{assetId:image,alt:'Forest'},mobile:{assetId:image,alt:'Canopy'}}}]}};
 const saved=(await db.query("select cms.save_draft($1,null,null,'page','/nested-page-images','Nested images',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;
 const args=[site,saved.recordId,saved.revisionId];
 assert.deepEqual((await db.query('select cms.get_record_media_status($1,$2,$3) value',args)).rows[0].value,[{assetId:image,available:true}]);
 await actor(outsider);assert.equal((await db.query('select cms.get_record_media_status($1,$2,$3) value',args)).rows[0].value,null);
 await root();
 assert.equal((await db.query("select cms.record_media_available($1,'page',$2::jsonb) value",[otherSite,JSON.stringify(payload)])).rows[0].value,false);
 // Direct root fixture transition exercises the publication trigger; no page validator is enabled.
 await db.query('update cms.records set published_revision_id=$1 where id=$2',[saved.revisionId,saved.recordId]);
 await actor(null,'anon');assert.ok((await db.query("select cms.get_public_page($1,'/nested-page-images') value",[site])).rows[0].value);
 await actor(null,'service_role');await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,image]);
 await actor(editor);assert.deepEqual((await db.query('select cms.get_record_media_status($1,$2,$3) value',args)).rows[0].value,[{assetId:image,available:false}]);
 await actor(null,'anon');assert.equal((await db.query("select cms.get_public_page($1,'/nested-page-images') value",[site])).rows[0].value,null);
 await actor(null,'service_role');const withdrawn=(await db.query('select cms.withdraw_unavailable_media($1) value',[site])).rows[0].value;assert.ok(withdrawn.some(row=>row.recordId===saved.recordId));
 await root();await assert.rejects(db.query('update cms.records set published_revision_id=$1 where id=$2',[saved.revisionId,saved.recordId]),/media_verification_required/);
 for(const assetId of [null,17,'missing'])assert.equal((await db.query("select cms.record_media_available($1,'page',$2::jsonb) value",[site,JSON.stringify({composition:{section:{image:{assetId}}}})])).rows[0].value,false);
 assert.equal((await db.query('select current_revision_id from cms.records where id=$1',[saved.recordId])).rows[0].current_revision_id,saved.revisionId);
});

test('record references preserve selection order and never disclose inaccessible or wrong-type payloads',async()=>{
 await actor(editor);
 const make=async(type,path,title)=>(await db.query('select cms.save_draft($1,null,null,$2,$3,$4,$5::jsonb) value',[site,type,path,title,JSON.stringify({secret:'draft copy never returned'})])).rows[0].value;
 const first=await make('project','/projects/reference-one','Reference Alpha'),second=await make('project','/projects/reference-two','Reference Beta'),wrong=await make('journey','/journeys/reference-wrong','Reference Wrong');
 const list=(await db.query("select cms.list_reference_candidates($1,'project','reference') value",[site])).rows[0].value;
 assert.equal(list.length,2);assert.ok(list.every(row=>!('payload'in row)&&!('currentRevision'in row)));assert.ok(list.every(row=>row.published===false));
 const selected=[second.recordId,wrong.recordId,first.recordId];
 const resolved=(await db.query("select cms.resolve_editor_references($1,'project',$2::uuid[]) value",[site,selected])).rows[0].value;
 assert.deepEqual(resolved.map(row=>row.id),selected);assert.deepEqual(resolved[1],{id:wrong.recordId,available:false});
 const sorted=[first.recordId,second.recordId].sort();assert.equal((await db.query("select cms.list_reference_candidates($1,'project','reference',$2) value",[site,sorted[0]])).rows[0].value.length,1);
 assert.deepEqual((await db.query("select cms.resolve_editor_references($1,'project',$2::uuid[]) value",[otherSite,[first.recordId]])).rows[0].value,[{id:first.recordId,available:false}]);
 await actor(outsider);assert.deepEqual((await db.query("select cms.list_reference_candidates($1,'project') value",[site])).rows[0].value,[]);
 assert.deepEqual((await db.query("select cms.resolve_editor_references($1,'project',$2::uuid[]) value",[site,[first.recordId]])).rows[0].value,[{id:first.recordId,available:false}]);
 await actor(editor);await assert.rejects(db.query("select cms.resolve_editor_references($1,'project',$2::uuid[])",[site,[first.recordId,first.recordId]]),/invalid_reference_list/);
 await actor(null,'anon');await assert.rejects(db.query("select cms.list_reference_candidates($1,'project')",[site]),/permission denied/);
});

test('global settings are singleton per locale and sensitive changes require current configuration authority',async()=>{
 const initial=newGlobalSettings();await actor(editor);
 const settings=(await db.query("select cms.save_draft($1,null,null,'settings',null,'Website settings',$2::jsonb) value",[site,JSON.stringify(initial)])).rows[0].value;
 await assert.rejects(db.query("select cms.save_draft($1,null,null,'settings',null,'Duplicate',$2::jsonb)",[site,JSON.stringify(initial)]),/cms_settings_per_locale/);
 await assert.rejects(db.query("select cms.save_draft($1,null,null,'settings','/settings','Routed settings',$2::jsonb,'fr')",[site,JSON.stringify(initial)]),/cms_settings_no_page_path/);
 const changed=structuredClone(initial);changed.seo.indexing='noindex';
 const update=(revision,payload)=>db.query("select cms.save_draft($1,$2,$3,'settings',null,'Website settings',$4::jsonb) value",[site,settings.recordId,revision,JSON.stringify(payload)]);
 await assert.rejects(update(settings.revisionId,changed),/settings_configuration_permission_required/);
 const maintenance=structuredClone(initial);maintenance.errors.maintenance.enabled=true;await assert.rejects(update(settings.revisionId,maintenance),/settings_configuration_permission_required/);
 const malformed=structuredClone(initial);delete malformed.seo.indexing;await assert.rejects(update(settings.revisionId,malformed),/invalid_sensitive_settings/);
 await root();await db.query("insert into cms.permissions(website_id,role_id,action,content_type,record_id) values($1,$2,'configure','settings',$3)",[site,editorRole,settings.recordId]);
 await actor(editor);const sensitive=(await update(settings.revisionId,changed)).rows[0].value;
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='configure' and content_type='settings'",[site,editorRole]);
 await actor(editor);const harmless=structuredClone(changed);harmless.brand.tagline='New tagline';const pending=(await update(sensitive.revisionId,harmless)).rows[0].value;await review(pending,'submit');
 await actor(reviewer);await assert.rejects(review(pending,'approve'),/settings_configuration_permission_required/);
 await root();await db.query("insert into cms.permissions(website_id,role_id,action,content_type,record_id) values($1,$2,'configure','settings',$3)",[site,reviewerRole,settings.recordId]);
 await actor(reviewer);await review(pending,'approve');
 // Isolate the release trigger: publication validators intentionally remain disabled.
 await root();await db.query("select set_config('request.jwt.claim.sub',$1,false)",[publisher]);await assert.rejects(db.query('update cms.records set published_revision_id=$1 where id=$2',[pending.revisionId,settings.recordId]),/settings_configuration_permission_required/);
 await db.query("insert into cms.permissions(website_id,role_id,action,content_type,record_id) values($1,$2,'configure','settings',$3)",[site,publisherRole,settings.recordId]);
 await db.query('update cms.records set published_revision_id=$1 where id=$2',[pending.revisionId,settings.recordId]);
 await actor(editor);await assert.rejects(db.query('select cms.restore_draft($1,$2,$3,$4)',[site,settings.recordId,settings.revisionId,pending.revisionId]),/settings_configuration_permission_required/);
 await root();await db.query("delete from cms.permissions where website_id=$1 and action='configure' and content_type='settings'",[site]);
});

