test('notification leases fence workers, retry with backoff and retain saved enquiries on failure',async()=>{
 const claim=async()=>(await db.query('select cms.claim_lead_notifications(10,120) as value')).rows[0].value;
 const read=async(job)=>(await db.query('select cms.get_lead_notification_input($1,$2) as value',[job.id,job.leaseToken])).rows[0].value;
 const finish=(job,success=false,error='delivery_failed')=>db.query('select cms.finish_lead_notification($1,$2,$3,$4)',[job.id,job.leaseToken,success,error]);
 await actor(editor);await assert.rejects(claim(),/permission denied/);
 await actor(null,'service_role');const [first]=await claim();assert.ok(first);assert.deepEqual(await claim(),[]);assert.equal((await read(first)).leadId,first.leadId);
 await root();await db.query("update cms.lead_notification_jobs set lease_until=now()-interval '1 second' where id=$1",[first.id]);
 await actor(null,'service_role');assert.equal(await read(first),null);const [second]=await claim();assert.notEqual(first.leaseToken,second.leaseToken);await assert.rejects(finish(first),/notification_lease_lost/);
 await assert.rejects(finish(second,false,'private provider message'),/safe_error_code_required/);await finish(second);assert.deepEqual(await claim(),[]);
 await root();let state=(await db.query('select * from cms.lead_notification_jobs where id=$1',[first.id])).rows[0];assert.equal(state.status,'failed');assert.ok(new Date(state.next_attempt_at)>new Date());assert.equal((await db.query('select count(*)::int as n from cms.leads where id=$1',[first.leadId])).rows[0].n,1);
 await db.query("update cms.lead_notification_jobs set attempts=7,next_attempt_at=now()-interval '1 second' where id=$1",[first.id]);
 await actor(null,'service_role');const [last]=await claim();assert.equal(last.attempt,8);
 await root();await db.query("update cms.lead_notification_jobs set lease_until=now()-interval '1 second' where id=$1",[first.id]);
 await actor(null,'service_role');assert.equal((await db.query('select cms.reap_lead_notifications() as n')).rows[0].n,1);assert.equal((await db.query('select cms.reap_lead_notifications() as n')).rows[0].n,0);assert.deepEqual(await claim(),[]);await assert.rejects(finish(last,true),/notification_lease_lost/);
 await root();state=(await db.query('select * from cms.lead_notification_jobs where id=$1',[first.id])).rows[0];assert.equal(state.last_error_code,'worker_lease_expired');assert.ok(state.finished_at);assert.equal((await db.query("select count(*)::int as n from cms.lead_events where lead_id=$1 and action='notification_failed'",[first.leadId])).rows[0].n,2);
});

