test('HTTP intake through the actual validator and database adapter saves one lead and one notification on retry',async()=>{
 const definition=newForm('guestName');definition.title='Integrated intake fixture';definition.notificationRouteIds=[site];
 await actor(editor);const form=(await db.query("select cms.save_draft($1,null,null,'form',null,'Integrated intake fixture',$2::jsonb) as value",[site,JSON.stringify(definition)])).rows[0].value;
 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[form.revisionId,form.recordId]);
 const cleanupNotificationFixture=await installNotificationFixture(form);
 await actor(null,'service_role');
 const rpc=async(name,args)=>{
  if(name==='consume_enquiry_rate')return (await db.query('select cms.consume_enquiry_rate($1,$2) as value',[args.p_site,args.p_actor_digest])).rows[0].value;
  if(name==='get_enquiry_input')return (await db.query('select cms.get_enquiry_input($1,$2,$3,$4) as value',[args.p_site,args.p_form,args.p_revision,args.p_request])).rows[0].value;
  if(name==='accept_enquiry')return (await db.query('select cms.accept_enquiry($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7::jsonb) as value',[args.p_site,args.p_form,args.p_revision,args.p_request,JSON.stringify(args.p_answers),JSON.stringify(args.p_consents),JSON.stringify(args.p_attribution)])).rows[0].value;
  assert.fail('Unexpected procedure');
 };
 const adapter=createEnquiryIntakeAdapter({site,trustedIdentity:'synthetic-integrated-client',identitySecret:'i'.repeat(32),verifyChallenge:async token=>token==='synthetic-pass',rpc});
 const config={site,origin:'https://example.test',adapterForRequest:async()=>adapter},key=randomUUID();
 const body={formId:form.recordId,revisionId:form.revisionId,requestKey:key,challengeToken:'synthetic-pass',answers:{guestName:' Integrated guest '},sourcePath:'/contact'};
 const request=value=>new Request('https://example.test/api/cms-enquiry',{method:'POST',headers:{Origin:'https://example.test','Content-Type':'application/json'},body:JSON.stringify(value)});
 const first=await handleEnquiryHttp(request(body),config);assert.equal(first.status,200);const receipt=await first.json();
 const retry=await handleEnquiryHttp(request(body),config);assert.equal(retry.status,200);assert.equal((await retry.json()).reference,receipt.reference);
 assert.equal((await handleEnquiryHttp(request({...body,requestKey:randomUUID(),answers:{guestName:''}}),config)).status,422);
 assert.equal((await handleEnquiryHttp(request({...body,requestKey:randomUUID(),challengeToken:'rejected'}),config)).status,422);
 await cleanupNotificationFixture();await actor(null,'service_role');const outageRetry=await handleEnquiryHttp(request(body),config);assert.equal(outageRetry.status,200);assert.equal((await outageRetry.json()).reference,receipt.reference);assert.equal((await handleEnquiryHttp(request({...body,requestKey:randomUUID()}),config)).status,409);
 await root();assert.equal((await db.query('select count(*)::int as n from cms.leads where form_id=$1',[form.recordId])).rows[0].n,1);assert.equal((await db.query('select answers from cms.leads where id=$1',[receipt.reference])).rows[0].answers.guestName,'Integrated guest');assert.equal((await db.query('select count(*)::int as n from cms.lead_notification_jobs where lead_id=$1',[receipt.reference])).rows[0].n,1);
});

