test('trusted destination input resolves only saved same-site typed references and observes publication changes',async()=>{
 const {newDestination}=await import('../lib/cms/destinations.ts');
 await actor(editor);const journey=await save('/journeys/destination-reference',null,null,{slug:'destination-reference',title:'Published journey'});
 const wrong=(await db.query("select cms.save_draft($1,null,null,'testimonial',null,'Wrong type','{}') as value",[site])).rows[0].value;
 const foreign=randomUUID();await root();await db.query("insert into cms.records(id,website_id,content_type,internal_title,owner_id) values($1,$2,'journey','Other website',$3)",[foreign,otherSite,editor]);
 await db.query('update cms.records set published_revision_id=$1 where id=$2',[journey.revisionId,journey.recordId]);
 const payload={...newDestination(),slug:'reference-check',journeys:[{recordId:journey.recordId},{recordId:wrong.recordId},{recordId:foreign}]};
 await actor(editor);const draft=(await db.query("select cms.save_draft($1,null,null,'destination','/destinations/reference-check','Reference check',$2::jsonb) as value",[site,JSON.stringify(payload)])).rows[0].value;
 const read=async(revision=draft.revisionId)=>(await db.query('select cms.get_validation_input($1,$2,$3) as value',[site,draft.recordId,revision])).rows[0].value;
 await assert.rejects(db.query('select cms.get_destination_reference_status($1,$2,$3)',[site,draft.recordId,draft.revisionId]),/permission denied/);
 await actor(null,'service_role');let input=await read();assert.equal(input.locale,'en');assert.deepEqual(input.referenceStatus,[{recordId:journey.recordId,type:'journey',available:true,published:true,locale:'en'},{recordId:wrong.recordId,type:'journey',available:false},{recordId:foreign,type:'journey',available:false}]);
 const {validationInputSchema}=await import('../lib/cms/validation-worker.ts');assert.equal(validationInputSchema.safeParse(input).success,true);
 await root();await db.query("update cms.records set path='/journeys/wrong-route' where id=$1",[journey.recordId]);await actor(null,'service_role');assert.equal((await read()).referenceStatus[0].published,false);
 await root();await db.query("update cms.records set path='/journeys/destination-reference',published_revision_id=null where id=$1",[journey.recordId]);await actor(null,'service_role');assert.equal((await read()).referenceStatus[0].published,false);
 await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'destination','/destinations/reference-check','Changed',$4::jsonb)",[site,draft.recordId,draft.revisionId,JSON.stringify({...payload,journeys:[]})]);await actor(null,'service_role');assert.equal(await read(),null);
 await actor(null,'anon');await assert.rejects(read(),/permission denied/);
});

test('destination publication trigger rechecks related publication, locale, route and media rights atomically',async()=>{
 const {newDestination}=await import('../lib/cms/destinations.ts');const asset='destination-guard-image';
 await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic rights')",[site,asset,`${site}/${asset}/delivery.webp`,'b'.repeat(64)]);
 await actor(editor);const linked=await save('/journeys/guarded-related',null,null,{slug:'guarded-related',title:'Related',media:[{assetId:asset}]});
 const payload={...newDestination(),slug:'publication-reference-guard',journeys:[{recordId:linked.recordId}]};
 const destination=(await db.query("select cms.save_draft($1,null,null,'destination','/destinations/publication-reference-guard','Guard',$2::jsonb) as value",[site,JSON.stringify(payload)])).rows[0].value;
 // Operator-level pointer writes isolate this trigger; no destination validator policy is enabled.
 await root();const publishPointer=()=>db.query('update cms.records set published_revision_id=$1 where id=$2',[destination.revisionId,destination.recordId]);
 await assert.rejects(publishPointer(),/destination_reference_verification_required/);
 await db.query('update cms.records set published_revision_id=$1 where id=$2',[linked.revisionId,linked.recordId]);
 await db.query("update cms.records set locale='fr' where id=$1",[linked.recordId]);await assert.rejects(publishPointer(),/destination_reference_verification_required/);
 await db.query("update cms.records set locale='en',path='/journeys/changed-path' where id=$1",[linked.recordId]);await assert.rejects(publishPointer(),/destination_reference_verification_required/);
 await db.query("update cms.records set path='/journeys/guarded-related' where id=$1",[linked.recordId]);
 await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await assert.rejects(publishPointer(),/destination_reference_verification_required/);
 const unchanged=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[destination.recordId])).rows[0];assert.equal(unchanged.current_revision_id,destination.revisionId);assert.equal(unchanged.published_revision_id,null);
 await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await publishPointer();assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[destination.recordId])).rows[0].published_revision_id,destination.revisionId);
 await db.query('update cms.records set published_revision_id=null where id=$1',[destination.recordId]);
 await actor(editor);const self=(await db.query("select cms.save_draft($1,$2,$3,'destination','/destinations/publication-reference-guard','Self',$4::jsonb) as value",[site,destination.recordId,destination.revisionId,JSON.stringify({...payload,pairings:[{recordId:destination.recordId,title:'Self',reason:''}]})])).rows[0].value;
 await root();await assert.rejects(db.query('update cms.records set published_revision_id=$1 where id=$2',[self.revisionId,self.recordId]),/destination_reference_verification_required/);
});

test('public destination reads published snapshots and fail closed when nested dependencies withdraw',async()=>{
 const {newDestination}=await import('../lib/cms/destinations.ts');const {projectPublishedDestination}=await import('../lib/cms/published-destination.ts');
 const asset='public-destination-hero',image={assetId:asset,alt:'Forest',decorative:false};
 await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'c'.repeat(64)]);
 await actor(editor);const journey=await save('/journeys/public-dest-linked',null,null,{slug:'public-dest-linked',title:'Published related journey'});
 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[journey.revisionId,journey.recordId]);
 const make=async(slug,extra={})=>{const payload={...newDestination(),slug,title:slug,country:'India',description:'Description',intro:'Introduction',bestMonths:'Winter',image,heroImage:image,...extra};await actor(editor);const record=(await db.query("select cms.save_draft($1,null,null,'destination',$2,$3,$4::jsonb) as value",[site,`/destinations/${slug}`,slug,JSON.stringify(payload)])).rows[0].value;await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[record.revisionId,record.recordId]);return {...record,payload};};
 const child=await make('public-child',{journeys:[{recordId:journey.recordId}]});
 const parent=await make('public-parent',{pairings:[{recordId:child.recordId,title:'Child pairing',reason:'Continue exploring'}],internalNotes:'Do not expose'});
 const read=async(target=site,locale='en')=>(await db.query("select cms.get_public_destination($1,'/destinations/public-parent',$2) as value",[target,locale])).rows[0].value;
 await actor(null,'anon');let value=await read();assert.equal(value.page.revisionId,parent.revisionId);assert.equal(value.page.payload.internalNotes,undefined);assert.equal(value.references.length,1);assert.equal(value.references[0].title,'public-child');assert.equal(projectPublishedDestination(value.page,'/destinations/public-parent','en',value.references).pairings[0].path,'/destinations/public-child');assert.equal(await read(otherSite),null);assert.equal(await read(site,'fr'),null);
 await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'destination','/destinations/public-parent','Unpublished edit',$4::jsonb)",[site,parent.recordId,parent.revisionId,JSON.stringify({...parent.payload,title:'Unpublished edit'})]);
 const cycle=(await db.query("select cms.save_draft($1,$2,$3,'destination','/destinations/public-child','Child cycle',$4::jsonb) as value",[site,child.recordId,child.revisionId,JSON.stringify({...child.payload,pairings:[{recordId:parent.recordId,title:'Back to parent',reason:''}]})])).rows[0].value;
 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[cycle.revisionId,cycle.recordId]);await actor(null,'anon');value=await read();assert.equal(value.page.payload.title,'public-parent');assert.ok(value);
 await root();await db.query('update cms.records set published_revision_id=null where id=$1',[journey.recordId]);await actor(null,'anon');assert.equal(await read(),null);
 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[journey.revisionId,journey.recordId]);await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(null,'anon');assert.equal(await read(),null);
 await assert.rejects(db.query('select cms.destination_delivery_references($1,$2,$3)',[site,parent.recordId,'en']),/permission denied/);
});


