test('destination trusted validation gates review publication and rejects incomplete replacement drafts',async()=>{
 const {newDestination}=await import('../lib/cms/destinations.ts');const asset='destination-publication-image';
 await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
 const image={assetId:asset,alt:'Forest',decorative:false},payload={...newDestination(),slug:'destination-publish-flow',title:'Destination publish flow',country:'India',description:'Description',intro:'Introduction',bestMonths:'Winter',image,heroImage:image,seo:{...newDestination().seo,canonical:'https://example.test/original-destination'}};
 const saveDestination=async(previous,value)=>(await db.query("select cms.save_draft($1,$2,$3,'destination','/destinations/destination-publish-flow','Destination publish flow',$4::jsonb) as value",[site,previous?.recordId??null,previous?.revisionId??null,JSON.stringify(value)])).rows[0].value;
 const transport=async(name,args)=>{
  if(name==='get_validation_input')return (await db.query('select cms.get_validation_input($1,$2,$3) as value',[args.p_site,args.p_record,args.p_revision])).rows[0].value;
  await db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]);
 };
 await actor(editor);const draft=await saveDestination(null,payload);await review(draft,'submit');await assert.rejects(review(draft,'approve'),/self_approval_forbidden/);
 await actor(reviewer);await review(draft,'approve');await actor(publisher);await assert.rejects(publish(draft),/validated_revision_required/);
 await actor(null,'service_role');const result=await runTrustedValidation(transport,{site,record:draft.recordId,revision:draft.revisionId});assert.equal(result.validatorVersion,'destination-1');assert.equal(result.contentChecksPass,true);
 await actor(publisher);assert.ok(await publish(draft));
 await actor(null,'anon');assert.equal((await db.query("select cms.get_public_destination($1,'/destinations/destination-publish-flow','en') as value",[site])).rows[0].value.page.revisionId,draft.revisionId);
 await actor(editor);const invalid=await saveDestination(draft,{...payload,intro:''});await review(invalid,'submit');await actor(reviewer);await review(invalid,'approve');
 await actor(null,'service_role');assert.equal((await runTrustedValidation(transport,{site,record:invalid.recordId,revision:invalid.revisionId})).contentChecksPass,false);
 await actor(publisher);await assert.rejects(publish(invalid),/validated_revision_required/);
 await root();assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[draft.recordId])).rows[0].published_revision_id,draft.revisionId);
});

