test('generated destination Excel completes API review save and retry against the database',async()=>{
 const {handleDestinationImportUpload}=await import('../lib/cms/destination-import-api.ts');
 const bytes=await fs.readFile(new URL('./fixtures/destination-v1-filled.xlsx',import.meta.url));
 const rpc=async(_token,name,args)=>{
  if(name==='list_editor_sites')return [{id:site}];
  if(name==='review_destination_import_links')return (await db.query('select cms.review_destination_import_links($1,$2,$3::uuid[],$4::text[],$5::jsonb) as value',[args.p_site,args.p_create,args.p_records,args.p_assets,JSON.stringify(args.p_references)])).rows[0].value;
  if(name==='get_destination_import_receipt')return (await db.query('select cms.get_destination_import_receipt($1,$2) as value',[args.p_site,args.p_request])).rows[0].value;
  if(name==='apply_destination_import')return (await db.query('select cms.apply_destination_import($1,$2,$3,$4,$5::jsonb) as value',[args.p_site,args.p_request,args.p_source,args.p_review,JSON.stringify(args.p_items)])).rows[0].value;
  throw Error(name);
 };
 const request=(action,extra={})=>new Request('https://site.test/api/cms/import/destinations',{method:'POST',headers:{Authorization:'Bearer a.b.c','X-CMS-Site':site,'X-CMS-Format':'xlsx','X-CMS-Action':action,...extra},body:bytes});
 await actor(editor);const reviewed=await handleDestinationImportUpload(request('review'),rpc);assert.equal(reviewed.status,200);const reviewBody=await reviewed.json();assert.equal(reviewBody.applyAvailable,true);
 const headers={'Idempotency-Key':randomUUID(),'X-CMS-Review':reviewBody.reviewDigest};const applied=await handleDestinationImportUpload(request('apply',headers),rpc);assert.equal(applied.status,200);const receipt=await applied.json();assert.equal(receipt.result.length,1);
 const replay=await(await handleDestinationImportUpload(request('apply',headers),rpc)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,receipt.result);
 await root();const record=(await db.query('select published_revision_id,review_status from cms.records where id=$1',[receipt.result[0].recordId])).rows[0];assert.equal(record.published_revision_id,null);assert.equal(record.review_status,'draft');
});

