test('journal publication requires separate approval, trusted revision validation and current processed image rights',async()=>{
 const {newJournalArticle}=await import('../lib/cms/journal.ts');const asset='journal-publication-image',path='/journal/publication-forest';
 await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'c'.repeat(64)]);
 const payload={...newJournalArticle(),slug:'publication-forest',title:'Publication forest',author:'Guide',category:'Wildlife',date:'2026-10-22',description:'Forest notes',image:{assetId:asset,alt:'Forest',decorative:false},body:[{id:'p',kind:'paragraph',text:'Complete article'}]};
 const saveArticle=async(previous,value)=>(await db.query("select cms.save_draft($1,$2,$3,'journalArticle',$4,$5,$6::jsonb)",[site,previous?.recordId??null,previous?.revisionId??null,path,value.title,JSON.stringify(value)])).rows[0].save_draft;
 const transport=async(name,args)=>{if(name==='get_validation_input')return (await db.query('select cms.get_validation_input($1,$2,$3) as value',[args.p_site,args.p_record,args.p_revision])).rows[0].value;await db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]);};
 const validateArticle=async draft=>{await actor(null,'service_role');return runTrustedValidation(transport,{site,record:draft.recordId,revision:draft.revisionId});};
 await actor(editor);const draft=await saveArticle(null,payload);await review(draft,'submit');await assert.rejects(review(draft,'approve'),/self_approval_forbidden/);await actor(reviewer);await review(draft,'approve');await actor(publisher);await assert.rejects(publish(draft),/validated_revision_required/);
 assert.equal((await validateArticle(draft)).contentChecksPass,true);
 await root();await db.query("update cms.media_objects set mime_type='image/jpeg' where website_id=$1 and id=$2",[site,asset]);await actor(publisher);await assert.rejects(publish(draft),/media_verification_required/);
 const invalidMedia=await validateArticle(draft);assert.equal(invalidMedia.contentChecksPass,false);assert.ok(invalidMedia.findings.some(f=>f.code==='asset_verification_required'));
 await root();await db.query("update cms.media_objects set mime_type='image/webp' where website_id=$1 and id=$2",[site,asset]);await validateArticle(draft);
 await actor(publisher);assert.ok(await publish(draft));await actor(null,'anon');assert.equal((await db.query('select cms.get_public_journal_article($1,$2) as value',[site,path])).rows[0].value.revisionId,draft.revisionId);
 await root();await assert.rejects(db.query("update cms.records set locale='fr' where id=$1",[draft.recordId]),/journal_route_not_ready/);await assert.rejects(db.query("update cms.records set path='/journal/changed-url' where id=$1",[draft.recordId]),/journal_route_not_ready/);
 await actor(editor);const invalid=await saveArticle(draft,{...payload,body:[]});await review(invalid,'submit');await actor(reviewer);await review(invalid,'approve');assert.equal((await validateArticle(invalid)).contentChecksPass,false);await actor(publisher);await assert.rejects(publish(invalid),/validated_revision_required/);
 await actor(null,'anon');assert.equal((await db.query('select cms.get_public_journal_article($1,$2) as value',[site,path])).rows[0].value.revisionId,draft.revisionId);
 await actor(editor);const replacement=await saveArticle(invalid,{...payload,title:'Revised forest'});await review(replacement,'submit');await actor(reviewer);await review(replacement,'approve');assert.equal((await validateArticle(replacement)).contentChecksPass,true);
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(publisher);await assert.rejects(publish(replacement),/media_verification_required/);
 await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await actor(publisher);assert.ok(await publish(replacement));
 await actor(null,'anon');assert.equal((await db.query('select cms.get_public_journal_article($1,$2) as value',[site,path])).rows[0].value.payload.title,'Revised forest');
});

