test('journal migration saves drafts atomically, retains hidden mappings and recovers without overwriting edits',async()=>{
 const {newJournalArticle}=await import('../lib/cms/journal.ts');const asset='journal-apply-hidden',request=randomUUID();
 await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
 const items=[{sourceKey:`journal_${'a'.repeat(64)}`,source:{body:['Exact source'],gallery:[{src:'/hidden.jpg'}]},mappings:{images:{'gallery.0':{assetId:asset}}},payload:{...newJournalArticle(),slug:'migration-one',title:'Migration one'},locale:'en'}];
 const apply=async(values=items,key=request,website=site)=>(await db.query('select cms.apply_journal_migration($1,$2,$3,$4,$5::jsonb) as value',[website,key,'a'.repeat(64),'b'.repeat(64),JSON.stringify(values)])).rows[0].value;
 const recover=async(key=request,website=site)=>(await db.query('select cms.get_journal_migration_result($1,$2) as value',[website,key])).rows[0].value;
 await actor(editor);assert.equal(await recover(),null);
 // The later invalid item must roll back the earlier record and batch receipt.
 const invalid={...items[0],sourceKey:`journal_${'b'.repeat(64)}`,payload:{...items[0].payload,slug:'migration-two'},mappings:{images:{hidden:{assetId:'missing'}}}};
 await assert.rejects(apply([...items,invalid]),/media_verification_required/);assert.equal(await recover(),null);
 assert.equal((await db.query("select count(*)::int as n from cms.records where website_id=$1 and path='/journal/migration-one'",[site])).rows[0].n,0);
 const saved=await apply();assert.equal(saved.length,1);assert.deepEqual((await recover()).result,saved);
 const stored=(await db.query('select manifest from cms.journal_migration_batches where request_key=$1',[request])).rows[0].manifest;assert.deepEqual(stored,items);
 const record=(await db.query('select published_revision_id,review_status from cms.records where id=$1',[saved[0].recordId])).rows[0];assert.equal(record.published_revision_id,null);assert.equal(record.review_status,'draft');
 const changed=(await db.query("select cms.save_draft($1,$2,$3,'journalArticle','/journal/migration-one','Edited',$4::jsonb) as value",[site,saved[0].recordId,saved[0].revisionId,JSON.stringify({...items[0].payload,title:'Edited'})])).rows[0].value;
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(editor);
 assert.deepEqual(await apply(),saved);assert.equal((await db.query('select current_revision_id from cms.records where id=$1',[saved[0].recordId])).rows[0].current_revision_id,changed.revisionId);
 await assert.rejects(apply([{...items[0],locale:'fr'}]),/idempotency_key_reused/);await assert.rejects(apply(items,randomUUID()),/import_key_already_exists/);
 await assert.rejects(apply([{...invalid,sourceKey:`journal_${'c'.repeat(64)}`,mappings:items[0].mappings}],randomUUID()),/media_verification_required/);
 await assert.rejects(recover(request,otherSite),/forbidden/);
 await actor(reviewer);await assert.rejects(recover(),/forbidden/);await assert.rejects(apply(),/forbidden/);
 await actor(outsider);assert.equal((await db.query('select count(*)::int as n from cms.journal_migration_batches')).rows[0].n,0);
 await actor(null,'anon');await assert.rejects(recover(),/permission denied/);await assert.rejects(apply(),/permission denied/);
});

test('journal migration API reviews, saves and recovers a committed database transaction after rights change',async()=>{
 const {handleJournalMigrationReview}=await import('../lib/cms/journal-migration-api.ts');const {sourceDigest}=await import('../lib/cms/testimonial-migration.ts');
 const asset='journal-api-apply',source={slug:'api-migration',title:'API migration',category:'Wildlife',author:'Guide',date:'October 22, 2026',readTime:'',description:'Forest',quote:'',body:['Exact article'],image:{src:'/forest.jpg',alt:'Forest',credit:'Archive'},gallery:[]};
 await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
 const body={action:'review',site,locale:'en',source:[source],mappings:{[`snapshot:${sourceDigest(source)}`]:{images:{image:{assetId:asset,alt:'Forest',credit:'Archive',decorative:false}}}}};
 const request=input=>new Request('https://site.test/api/cms/migrations/journal',{method:'POST',headers:{Authorization:'Bearer a.b.c','Content-Type':'application/json'},body:JSON.stringify(input)});
 const rpc=async(_token,name,args)=>{
  if(name==='review_journal_migration_media')return (await db.query('select cms.review_journal_migration_media($1,$2) as value',[args.p_site,args.p_assets])).rows[0].value;
  if(name==='get_journal_migration_result')return (await db.query('select cms.get_journal_migration_result($1,$2) as value',[args.p_site,args.p_request])).rows[0].value;
  if(name==='apply_journal_migration')return (await db.query('select cms.apply_journal_migration($1,$2,$3,$4,$5::jsonb) as value',[args.p_site,args.p_request,args.p_source,args.p_review,JSON.stringify(args.p_items)])).rows[0].value;
  throw Error(name);
 };
 await actor(editor);const reviewed=await handleJournalMigrationReview(request(body),rpc);assert.equal(reviewed.status,200);const preview=await reviewed.json();assert.equal(preview.applyAvailable,true);
 const apply={...body,action:'apply',requestKey:randomUUID(),reviewDigest:preview.reviewDigest};const applied=await handleJournalMigrationReview(request(apply),rpc);assert.equal(applied.status,200);const receipt=await applied.json();assert.equal(receipt.result.length,1);
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(editor);
 const replay=await handleJournalMigrationReview(request(apply),rpc);assert.equal(replay.status,200);const recovered=await replay.json();assert.equal(recovered.replayed,true);assert.deepEqual(recovered.result,receipt.result);
 const status=await handleJournalMigrationReview(request({action:'status',site,requestKey:apply.requestKey}),rpc);assert.equal((await status.json()).status,'complete');
});

