test('journal Office file completes API review, database save and receipt recovery without publishing',async()=>{
 const {handleJournalImportUpload}=await import('../lib/cms/journal-import-api.ts');const {zip}=await import('./office-fixtures.mjs');
 const cell=value=>`<w:tc><w:p><w:r><w:t>${value}</w:t></w:r></w:p></w:tc>`,row=values=>`<w:tr>${values.map(cell).join('')}</w:tr>`;
 const bytes=zip({'[Content_Types].xml':'<Types/>','word/document.xml':`<w:document xmlns:w="urn:w"><w:body><w:tbl>${row(['CMSJournal','1.0','journalArticle'])}</w:tbl><w:tbl>${row(['Pages'])}${row(['recordId','operation','slug','title','locale'])}${row(['office-api','create','office-api','Office API','en'])}</w:tbl></w:body></w:document>`});
 const rpc=async(_token,name,args)=>{
  if(name==='list_editor_sites')return (await db.query('select cms.list_editor_sites() as value')).rows[0].value;
  if(name==='review_journal_import_links')return (await db.query('select cms.review_journal_import_links($1,$2,$3,$4) as value',[args.p_site,args.p_create,args.p_records,args.p_assets])).rows[0].value;
  if(name==='get_journal_import_receipt')return (await db.query('select cms.get_journal_import_receipt($1,$2) as value',[args.p_site,args.p_request])).rows[0].value;
  if(name==='apply_journal_import')return (await db.query('select cms.apply_journal_import($1,$2,$3,$4,$5::jsonb) as value',[args.p_site,args.p_request,args.p_source,args.p_review,JSON.stringify(args.p_items)])).rows[0].value;
  throw Error(name);
 };
 const request=(action,headers={})=>new Request('https://site.test/api/cms/import/journal',{method:'POST',headers:{Authorization:'Bearer a.b.c','X-CMS-Site':site,'X-CMS-Format':'docx','X-CMS-Action':action,...headers},body:action==='status'?undefined:bytes});
 await actor(editor);const reviewed=await handleJournalImportUpload(request('review'),rpc);assert.equal(reviewed.status,200);const review=await reviewed.json();assert.equal(review.applyAvailable,true);
 const headers={'Idempotency-Key':randomUUID(),'X-CMS-Review':review.reviewDigest};const applied=await handleJournalImportUpload(request('apply',headers),rpc);assert.equal(applied.status,200);const result=await applied.json();assert.equal(result.result.length,1);
 assert.equal((await (await handleJournalImportUpload(request('apply',headers),rpc)).json()).replayed,true);
 const recovered=await(await handleJournalImportUpload(request('status',headers),rpc)).json();assert.equal(recovered.status,'complete');assert.deepEqual(recovered.result,result.result);
 assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[result.result[0].recordId])).rows[0].published_revision_id,null);
});

