 let current=rec.current_revision_id;
 const draft=async(payload)=>{await actor(editor);const result=(await db.query("select cms.save_draft($1,$2,$3,'settings',null,'Release checks',$4::jsonb) value",[site,rec.id,current,JSON.stringify(payload)])).rows[0].value;current=result.revisionId;return result;};
 const publish=async()=>{await root();return db.query('update cms.records set published_revision_id=$1 where id=$2',[current,rec.id]);};
 const payload=newGlobalSettings();payload.header.mainMenu={recordId:menuId};
 await draft(payload);const evidence=(await db.query('select cms.get_settings_reference_status($1,$2,$3) value',[site,rec.id,current])).rows[0].value;assert.equal(evidence[0].available,true);
