test('settings restore creates a fresh draft without replacing published settings and rejects stale expectations',async()=>{
 await root();const rec=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and content_type='settings' and locale='en'",[site])).rows[0];
 const saveSettings=async(expected,payload)=>{await actor(editor);return (await db.query("select cms.save_draft($1,$2,$3,'settings',null,'History settings',$4::jsonb) value",[site,rec.id,expected,JSON.stringify(payload)])).rows[0].value;};
 const payload=newGlobalSettings();payload.brand.name='Earlier brand';const old=await saveSettings(rec.current_revision_id,payload);
 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[old.revisionId,rec.id]);
 const latest=await saveSettings(old.revisionId,{...payload,brand:{...payload.brand,name:'Newer brand'}});
 await assert.rejects(db.query('select cms.restore_draft($1,$2,$3,$4)',[site,rec.id,old.revisionId,old.revisionId]),/revision_conflict/);
 const restored=(await db.query('select cms.restore_draft($1,$2,$3,$4) value',[site,rec.id,old.revisionId,latest.revisionId])).rows[0].value;
 assert.notEqual(restored.revisionId,old.revisionId);assert.notEqual(restored.revisionId,latest.revisionId);
 const detail=(await db.query('select cms.get_editor_record($1,$2) value',[site,rec.id])).rows[0].value;
 assert.equal(detail.currentRevision,restored.revisionId);assert.equal(detail.publishedRevision,old.revisionId);assert.equal(detail.payload.brand.name,'Earlier brand');assert.equal(detail.reviewStatus,'draft');assert.equal(detail.approvedRevision,null);assert.ok(detail.history.some(item=>item.id===latest.revisionId));
});

test('revision history pages equal timestamps without omissions and isolates record and website cursors',async()=>{
 await actor(editor);const saved=await save('/history-pagination');const other=await save('/other-history-pagination');
 await root();
 // Equal timestamps exercise the UUID tie-breaker, including beyond the original 20-entry cap.
 await db.query("insert into cms.revisions(website_id,record_id,payload,created_by,created_at) select $1,$2,'{}'::jsonb,$3,'2020-01-01'::timestamptz from generate_series(1,25)",[site,saved.recordId,editor]);
 const expected=(await db.query('select id from cms.revisions where website_id=$1 and record_id=$2 order by created_at desc,id desc',[site,saved.recordId])).rows.map(row=>row.id);
 const read=async(before=null,limit=20,record=saved.recordId,website=site)=>(await db.query('select cms.list_revision_history($1,$2,$3,$4) value',[website,record,before,limit])).rows[0].value;
 await actor(editor);const first=await read();assert.equal(first.items.length,20);assert.equal(first.nextCursor,first.items.at(-1).id);
 const second=await read(first.nextCursor);assert.equal(second.items.length,6);assert.equal(second.nextCursor,null);assert.deepEqual([...first.items,...second.items].map(item=>item.id),expected);assert.equal('payload' in first.items[0],false);
 assert.deepEqual((await read(expected.at(-1))).items,[]);
 await assert.rejects(read(other.revisionId),/invalid_history_cursor/);await assert.rejects(read(null,101),/invalid_page_size/);
 assert.equal(await read(null,20,saved.recordId,otherSite),null);
 await actor(outsider);assert.equal(await read(),null);
 await actor(null,'anon');await assert.rejects(read(),/permission denied/);
});

