test('specialist migration HTTP review, apply and recovery run against actual database procedures',async()=>{
 const {handleSpecialistMigrationReview}=await import('../lib/cms/specialist-migration-api.ts');const {planSpecialistMigration}=await import('../lib/cms/specialist-migration.ts');
 const source={specialists:[{name:'Integrated import guide',role:'Guide',expertise:'Forests',bio:'A guide biography',moment:'',image:{src:'/source.jpg'}}],journeys:[],expeditions:[]};const key=planSpecialistMigration(source).candidates[0].sourceKey;
 const body={action:'review',site,locale:'en',source,mappings:{profiles:{[key]:{image:{assetId:'specialist-rollback-image',alt:'Guide',decorative:false}}}}};
 const request=value=>new Request('https://site.test/api/cms/migrations/specialists',{method:'POST',headers:{Authorization:'Bearer a.b.c','Content-Type':'application/json'},body:JSON.stringify(value)});
 const rpc=async(_token,name,args)=>{if(name==='review_specialist_migration_links')return (await db.query('select cms.review_specialist_migration_links($1,$2,$3::jsonb) value',[args.p_site,args.p_assets,JSON.stringify(args.p_references)])).rows[0].value;if(name==='get_specialist_migration_result')return (await db.query('select cms.get_specialist_migration_result($1,$2) value',[args.p_site,args.p_request])).rows[0].value;assert.equal(name,'apply_specialist_migration');return (await db.query('select cms.apply_specialist_migration($1,$2,$3,$4,$5::jsonb) value',[args.p_site,args.p_request,args.p_source,args.p_review,JSON.stringify(args.p_items)])).rows[0].value;};
 await actor(editor);const reviewed=await (await handleSpecialistMigrationReview(request(body),rpc)).json();assert.equal(reviewed.applyAvailable,true);
 const apply={...body,action:'apply',requestKey:randomUUID(),reviewDigest:reviewed.reviewDigest};const response=await handleSpecialistMigrationReview(request(apply),rpc);assert.equal(response.status,200);const first=await response.json();assert.equal(first.replayed,false);assert.equal(first.result.length,1);
 const replay=await handleSpecialistMigrationReview(request(apply),rpc);assert.equal(replay.status,200);assert.deepEqual((await replay.json()).result,first.result);
 const status=await (await handleSpecialistMigrationReview(request({action:'status',site,requestKey:apply.requestKey}),rpc)).json();assert.equal(status.status,'complete');assert.deepEqual(status.result,first.result);
});

