test('expedition Office atomic saves enforce revisions, rollback and receipt isolation',async()=>{
 const {newPhotoExpedition}=await import('../lib/cms/photo-expeditions.ts');
 const item={sourceKey:'expedition_import_'+'c'.repeat(64),operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newPhotoExpedition(),slug:'office-atomic-proof',title:'Office atomic proof'}};
 const apply=async(items,key=randomUUID())=>(await db.query('select cms.apply_expedition_import($1,$2,$3,$4,$5::jsonb) value',[site,key,'c'.repeat(64),'d'.repeat(64),JSON.stringify(items)])).rows[0].value;
 const status=async key=>(await db.query('select cms.get_expedition_import_receipt($1,$2) value',[site,key])).rows[0].value;
 await actor(editor);const key=randomUUID(),created=await apply([item],key);assert.equal(created.length,1);assert.deepEqual(await apply([item],key),created);assert.deepEqual((await status(key)).result,created);
 await assert.rejects(apply([{...item,payload:{...item.payload,title:'Altered'}}],key),/idempotency_key_reused/);
 await assert.rejects(apply([item]),/import_key_already_exists/);
 const update={...item,operation:'update',recordId:created[0].recordId,expectedRevision:created[0].revisionId,payload:{...item.payload,title:'Updated Office draft'}};
 const updated=await apply([update]);assert.notEqual(updated[0].revisionId,created[0].revisionId);await assert.rejects(apply([update]),/revision_conflict/);
 const pending={...item,sourceKey:'expedition_import_'+'a'.repeat(64),payload:{...item.payload,slug:'office-rollback-proof'}};
 const invalid={...item,sourceKey:'expedition_import_'+'b'.repeat(64),payload:{...item.payload,slug:'office-bad-reference',specialists:[{role:'mentor',recordId:randomUUID()}]}};
 const failed=randomUUID();await assert.rejects(apply([pending,invalid],failed),/expedition_reference_verification_required/);assert.equal(await status(failed),null);
 await actor(reviewer);assert.equal(await status(key),null);await assert.rejects(apply([pending]),/forbidden/);
 await actor(null,'anon');await assert.rejects(status(key),/permission denied/);
 await root();assert.equal((await db.query("select count(*)::int n from cms.records where path='/photo-expeditions/office-rollback-proof'")).rows[0].n,0);
 assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[created[0].recordId])).rows[0].published_revision_id,null);
 assert.equal((await db.query('select count(*)::int n from cms.expedition_import_batches where request_key=$1',[failed])).rows[0].n,0);
});

test('expedition Word upload reviews and saves through real database RPCs with recoverable receipts',async()=>{
 const {handleExpeditionImportUpload}=await import('../lib/cms/photo-expedition-import-api.ts');
 const bytes=await fs.readFile(new URL('./fixtures/expedition-v1-filled.docx',import.meta.url));let writes=0;
 const rpc=async(_token,name,args)=>{
  if(name==='list_editor_sites')return (await db.query('select cms.list_editor_sites() value')).rows[0].value;
  if(name==='review_expedition_import_links')return (await db.query('select cms.review_expedition_import_links($1,$2,$3,$4,$5::jsonb) value',[args.p_site,args.p_create,args.p_records,args.p_assets,JSON.stringify(args.p_references)])).rows[0].value;
  if(name==='get_expedition_import_receipt')return (await db.query('select cms.get_expedition_import_receipt($1,$2) value',[args.p_site,args.p_request])).rows[0].value;
  assert.equal(name,'apply_expedition_import');writes++;return (await db.query('select cms.apply_expedition_import($1,$2,$3,$4,$5::jsonb) value',[args.p_site,args.p_request,args.p_source,args.p_review,JSON.stringify(args.p_items)])).rows[0].value;
 };
 const request=(action,extra={})=>new Request('https://site.test/api/cms/import/expeditions',{method:'POST',headers:{Authorization:'Bearer a.b.c','X-CMS-Site':site,'X-CMS-Format':'docx','X-CMS-Action':action,...extra},body:action==='status'?null:bytes});
 await actor(editor);const review=await handleExpeditionImportUpload(request('review'),rpc);assert.equal(review.status,200);const reviewed=await review.json();assert.equal(reviewed.applyAvailable,true);
 const requestKey=randomUUID(),headers={'Idempotency-Key':requestKey,'X-CMS-Review':reviewed.reviewDigest};
 const applied=await handleExpeditionImportUpload(request('apply',headers),rpc);assert.equal(applied.status,200);const saved=await applied.json();assert.equal(saved.applied,true);assert.equal(saved.replayed,false);
 const retry=await(await handleExpeditionImportUpload(request('apply',headers),rpc)).json();assert.equal(retry.replayed,true);assert.deepEqual(retry.result,saved.result);assert.equal(writes,1);
 const receipt=await(await handleExpeditionImportUpload(request('status',headers),rpc)).json();assert.equal(receipt.status,'complete');assert.deepEqual(receipt.result,saved.result);
 await root();const record=(await db.query('select r.published_revision_id,v.payload from cms.records r join cms.revisions v on v.id=r.current_revision_id where r.id=$1',[saved.result[0].recordId])).rows[0];assert.equal(record.published_revision_id,null);assert.deepEqual(record.payload,reviewed.plan.changes[0].payload);
});

