 await actor(editor);await db.query('select cms.save_draft($1,$2,$3,$4,$5,$6,$7::jsonb)',[site,saved.recordId,saved.revisionId,'photoExpedition','/photo-expeditions/public-expedition-proof','Unpublished title',JSON.stringify({...payload,title:'Unpublished title'})]);await actor(null,'anon');assert.equal((await read()).page.payload.title,'Public expedition');
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(null,'anon');assert.equal(await read(),null);
 await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await db.query('update cms.records set published_revision_id=null where id=$1',[specialist.recordId]);await actor(null,'anon');assert.equal(await read(),null);
 await release(specialist);await root();await db.query('update cms.records set published_revision_id=null where id=$1',[form.recordId]);await actor(null,'anon');assert.equal(await read(),null);await release(form);await actor(null,'anon');assert.ok(await read());
