test('expedition publication rechecks withdrawn forms and revoked specialist media before changing pointers',async()=>{
 await root();const source=(await db.query("select v.payload from cms.records r join cms.revisions v on v.id=r.current_revision_id where r.website_id=$1 and r.path='/photo-expeditions/public-expedition-proof'",[site])).rows[0].payload;
 const payload={...source,slug:'release-reference-proof'};
 await actor(editor);const draft=(await db.query('select cms.save_draft($1,null,null,$2,$3,$4,$5::jsonb) value',[site,'photoExpedition','/photo-expeditions/release-reference-proof',payload.title,JSON.stringify(payload)])).rows[0].value;
 const release=async()=>{await root();return db.query('update cms.records set published_revision_id=$1 where id=$2',[draft.revisionId,draft.recordId]);};
 const pointer=async()=>{await root();return (await db.query('select published_revision_id from cms.records where id=$1',[draft.recordId])).rows[0].published_revision_id;};
 await root();const form=payload.enquiry.form.recordId;const formRevision=(await db.query('select published_revision_id from cms.records where id=$1',[form])).rows[0].published_revision_id;
 await db.query('update cms.records set published_revision_id=null where id=$1',[form]);await assert.rejects(release(),/expedition_reference_verification_required/);assert.equal(await pointer(),null);
 await db.query('update cms.records set published_revision_id=$1 where id=$2',[formRevision,form]);
 await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,payload.image.assetId]);await assert.rejects(release(),/expedition_reference_verification_required/);assert.equal(await pointer(),null);
 await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,payload.image.assetId]);await release();assert.equal(await pointer(),draft.revisionId);
 // The pointer trigger is defense in depth, not an authorization bypass for clients.
 await actor(publisher);await assert.rejects(db.query('select cms.publish($1,$2,$3)',[site,draft.recordId,draft.revisionId]));
 await root();await db.query('update cms.records set published_revision_id=null where id=$1',[draft.recordId]);
});

