 const {newPhotoExpedition}=await import('../lib/cms/photo-expeditions.ts');const {projectPublishedExpedition}=await import('../lib/cms/published-expedition.ts');
 await root();const source=(await db.query("select v.payload from cms.records r join cms.revisions v on v.id=r.current_revision_id where r.website_id=$1 and r.path='/photo-expeditions/public-expedition-proof'",[site])).rows[0].payload;
