 await actor(editor);const newer=(await db.query("select cms.save_draft($1,$2,$3,'photoExpedition',$4,$5,$6::jsonb) value",[site,rec.id,rec.current_revision_id,path,'Updated expedition',JSON.stringify({...rec.payload,title:'Updated expedition'})])).rows[0].value;
 await review(newer,'submit');await actor(reviewer);await review(newer,'approve');assert.equal((await check(newer)).contentChecksPass,true);await actor(publisher);await publish(newer);
 await actor(editor);await assert.rejects(db.query('select cms.restore_draft($1,$2,$3,$4)',[site,rec.id,original,rec.current_revision_id]),/revision_conflict/);
 const restored=(await db.query('select cms.restore_draft($1,$2,$3,$4) value',[site,rec.id,original,newer.revisionId])).rows[0].value;
