 await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[otherSite,editor]);await actor(editor);await assert.rejects(apply(),/forbidden/);await assert.rejects(db.query('select cms.get_legal_migration_result($1,$2)',[otherSite,key]),/forbidden/);
