test('legal HTTP review and apply use the real database receipt for safe retry recovery',async()=>{
 const {handleLegalMigration}=await import('../lib/cms/legal-migration-api.ts');await actor(editor);const rec=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and path='/legal/cookies'",[site])).rows[0];const targets=[{path:'/legal/cookies',recordId:rec.id,expectedRevision:rec.current_revision_id}],requestKey=randomUUID();
 const request=body=>new Request('https://cms.test/api/cms/migrations/legal',{method:'POST',headers:{authorization:'Bearer test.editor.token','content-type':'application/json'},body:JSON.stringify(body)});
 const rpc=async(_token,name,args)=>{
  if(name==='get_editor_record')return (await db.query('select cms.get_editor_record($1,$2) value',[args.p_site,args.p_record])).rows[0].value;
  if(name==='get_legal_migration_result')return (await db.query('select cms.get_legal_migration_result($1,$2) value',[args.p_site,args.p_request])).rows[0].value;
  if(name==='apply_legal_migration')return (await db.query('select cms.apply_legal_migration($1,$2,$3,$4,$5::jsonb) value',[args.p_site,args.p_request,args.p_source,args.p_review,JSON.stringify(args.p_items)])).rows[0].value;
  throw Error('Unexpected RPC');
 };
 const reviewResponse=await handleLegalMigration(request({action:'review',site,targets}),rpc);assert.equal(reviewResponse.status,200);const plan=await reviewResponse.json();const command={action:'apply',site,targets,requestKey,reviewDigest:plan.reviewDigest};
 const applied=await handleLegalMigration(request(command),rpc);assert.equal(applied.status,200);const result=await applied.json();assert.equal(result.replayed,false);const retried=await handleLegalMigration(request(command),rpc);assert.equal(retried.status,200);const retry=await retried.json();assert.equal(retry.replayed,true);assert.deepEqual(retry.result,result.result);
 const status=await handleLegalMigration(request({action:'status',site,requestKey}),rpc);assert.equal((await status.json()).status,'complete');const detail=(await db.query('select cms.get_editor_record($1,$2) value',[site,rec.id])).rows[0].value;assert.equal(detail.publishedRevision,rec.published_revision_id);assert.equal(detail.currentRevision,result.result[0].revisionId);assert.equal(detail.reviewStatus,'draft');
});

test('About release requires current processed media and links after trusted validation',async()=>{
 const fixture=JSON.parse(await fs.readFile(new URL('./fixtures/cms-about-page.json',import.meta.url),'utf8'));const payload=JSON.parse(JSON.stringify(fixture.payload).replaceAll('"forest"','"about-forest"').replaceAll('"portrait"','"about-portrait"').replaceAll('"founder"','"about-founder"'));
 // The synthetic asset-name substitution also touches the forest background; retain the approved background value.
 payload.composition.sections[3].controls.background='forest';
 await root();for(const asset of ['about-forest','about-portrait','about-founder'])await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'d'.repeat(64)]);
 await actor(editor);const draft=(await db.query("select cms.save_draft($1,null,null,'page','/about','About',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;await review(draft,'submit');await assert.rejects(review(draft,'approve'),/self_approval_forbidden/);await actor(reviewer);await review(draft,'approve');await actor(publisher);await assert.rejects(publish(draft),/validated_revision_required/);
 const check=async()=>{await actor(null,'service_role');return runTrustedValidation(async(name,args)=>{if(name==='get_validation_input')return (await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value;await db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]);},{site,record:draft.recordId,revision:draft.revisionId});};
 await root();await db.query("update cms.media_objects set mime_type='image/jpeg' where website_id=$1 and id='about-portrait'",[site]);assert.equal((await check()).contentChecksPass,false);await root();await db.query("update cms.media_objects set mime_type='image/webp' where website_id=$1 and id='about-portrait'",[site]);const checked=await check();assert.equal(checked.contentChecksPass,true,JSON.stringify(checked.findings));assert.equal(checked.validatorVersion,'composition-5');
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id='about-forest'",[site]);await actor(publisher);await assert.rejects(publish(draft),/media_verification_required/);await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id='about-forest'",[site]);await db.query("delete from cms.navigation_public_paths where path='/contact'");await actor(publisher);await assert.rejects(publish(draft),/about_page_link_unavailable/);await root();await db.query("insert into cms.navigation_public_paths(path) values('/contact')");await actor(publisher);await publish(draft);
 await actor(null,'anon');const live=(await db.query("select cms.get_public_page($1,'/about') value",[site])).rows[0].value;const {projectAboutPage}=await import('../lib/cms/about-page.ts');assert.equal(projectAboutPage(live,{locale:'en',now:new Date()}).sections.length,5);
 await root();await assert.rejects(db.query("update cms.records set path='/concept' where id=$1",[draft.recordId]),/about_page_route_not_ready/);await assert.rejects(db.query("update cms.records set locale='fr' where id=$1",[draft.recordId]),/about_page_route_not_ready/);
});
