 await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic test approval')",[site,id,`${site}/${id}/delivery.webp`,processed]);
