test('About draft migration locks media evidence, rolls back failures and replays one immutable receipt',async()=>{
 const {default:inventory}=await import('../docs/cms/about-migration-inventory.json',{with:{type:'json'}});const {aboutMigrationDependencies,planAboutMigration}=await import('../lib/cms/about-migration.ts');
 const bindings=[];await root();
 for(const source of inventory.media){const id=randomUUID();bindings.push({sourcePath:source.sourcePath,sourceSha256:source.sha256,assetId:id});await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,'source.jpg','image/jpeg',100,$5,'ready',$6,'image-1')",[id,site,editor,randomUUID(),`${site}/${id}/original`,source.sha256]);await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic rights')",[site,id,`${site}/${id}/delivery.webp`,'d'.repeat(64)]);}
 const before=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and path='/about' and locale='en'",[site])).rows[0];assert.ok(before?.published_revision_id);
 await actor(editor);const payload=planAboutMigration(aboutMigrationDependencies,bindings).previewPayload,mediaBindings=bindings.map(({assetId,sourceSha256})=>({assetId,sourceSha256}));
 const evidence=async()=>(await db.query('select cms.review_about_migration_media($1,$2::jsonb) value',[site,JSON.stringify(mediaBindings)])).rows[0].value;
 let manifest={recordId:before.id,expectedRevision:before.current_revision_id,payload,bindings:mediaBindings,evidence:await evidence()};const request=randomUUID();
 const apply=async(body=manifest,key=request)=>(await db.query('select cms.apply_about_migration($1,$2,$3,$4,$5::jsonb) value',[site,key,'e'.repeat(64),'f'.repeat(64),JSON.stringify(body)])).rows[0].value;
 await root();await db.query("update cms.media_objects set title='Metadata changed after review' where website_id=$1 and id=$2",[site,bindings[0].assetId]);await actor(editor);await assert.rejects(apply(),/migration_media_changed/);
 await root();assert.equal((await db.query('select count(*)::int count from cms.about_migration_batches where request_key=$1',[request])).rows[0].count,0);assert.equal((await db.query('select current_revision_id from cms.records where id=$1',[before.id])).rows[0].current_revision_id,before.current_revision_id);
 await actor(editor);manifest={...manifest,evidence:await evidence()};const wrong=structuredClone(manifest);wrong.payload.composition.sections[0].data.desktop.assetId='unmapped';await assert.rejects(apply(wrong),/migration_media_mismatch/);
 const stale={...manifest,expectedRevision:randomUUID()};await assert.rejects(apply(stale),/revision_conflict/);
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,bindings[1].assetId]);await actor(editor);await assert.rejects(apply(),/migration_media_unavailable/);await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,bindings[1].assetId]);await actor(editor);manifest={...manifest,evidence:await evidence()};
 const saved=await apply();assert.equal(saved.recordId,before.id);assert.notEqual(saved.revisionId,before.current_revision_id);assert.deepEqual(await apply(),saved);
 const later=(await db.query("select cms.save_draft($1,$2,$3,'page','/about','Later edit',$4::jsonb,'en') value",[site,before.id,saved.revisionId,JSON.stringify({...payload,composition:{...payload.composition,title:'Later edit'}})])).rows[0].value;
 assert.deepEqual(await apply(),saved);await assert.rejects(apply({...manifest,payload:{...payload,seo:{...payload.seo,title:'Tampered'}}}),/idempotency_key_reused/);
 const receipt=(await db.query('select cms.get_about_migration_result($1,$2) value',[site,request])).rows[0].value;assert.deepEqual(receipt.result,saved);
 await actor(reviewer);assert.equal((await db.query('select cms.get_about_migration_result($1,$2) value',[site,request])).rows[0].value,null);
 await root();const after=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[before.id])).rows[0];assert.equal(after.current_revision_id,later.revisionId);assert.equal(after.published_revision_id,before.published_revision_id);assert.equal((await db.query("select count(*)::int count from cms.audit_events where website_id=$1 and action='about_migration.applied' and details->>'recordId'=$2",[site,before.id])).rows[0].count,1);
 await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,editor]);await actor(editor);await assert.rejects(apply(),/forbidden/);await assert.rejects(db.query('select cms.get_about_migration_result($1,$2)',[site,request]),/forbidden/);await root();await db.query('update cms.memberships set revoked_at=null where website_id=$1 and user_id=$2',[site,editor]);
});
test('About HTTP apply recovers a lost response using exact receipts without overwriting a later draft',async()=>{
 const {handleAboutMigrationReview}=await import('../lib/cms/about-migration-api.ts');const {default:inventory}=await import('../docs/cms/about-migration-inventory.json',{with:{type:'json'}});
 await root();const previous=(await db.query('select manifest from cms.about_migration_batches order by created_at desc limit 1')).rows[0].manifest;const rec=(await db.query('select id,current_revision_id,published_revision_id from cms.records where id=$1',[previous.recordId])).rows[0];
 const selection={action:'review',site,recordId:rec.id,expectedRevision:rec.current_revision_id,bindings:inventory.media.map(m=>({sourcePath:m.sourcePath,sourceSha256:m.sha256,assetId:previous.bindings.find(b=>b.sourceSha256===m.sha256).assetId}))};
 const req=body=>new Request('http://localhost/api/cms/migrations/about',{method:'POST',headers:{authorization:'Bearer test.editor.token',origin:'http://localhost','content-type':'application/json'},body:JSON.stringify(body)});
 let loseResponse=false;const names=[];const call=async(token,name,args)=>{assert.equal(token,'test.editor.token');assert.ok(['get_editor_record','review_about_migration_media','get_about_migration_result','apply_about_migration'].includes(name));names.push(name);const entries=Object.entries(args),values=entries.map(([,v])=>v&&typeof v==='object'?JSON.stringify(v):v);const result=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key}=>$${i+1}`).join(',')}) value`,values)).rows[0].value;if(name==='apply_about_migration'&&loseResponse){loseResponse=false;throw Error('Simulated response lost after commit');}return result;};
 await actor(editor);let reviewResponse=await handleAboutMigrationReview(req(selection),call);assert.equal(reviewResponse.status,200);let review=await reviewResponse.json();assert.equal(review.applyAvailable,true);
 const key=randomUUID();let command={...selection,action:'apply',requestKey:key,reviewDigest:review.reviewDigest,evidence:review.verification.evidence};
 await root();await db.query("update cms.media_objects set title='Changed after API review' where website_id=$1 and id=$2",[site,selection.bindings[0].assetId]);await actor(editor);assert.equal((await handleAboutMigrationReview(req(command),call)).status,409);
 review=await (await handleAboutMigrationReview(req(selection),call)).json();command={...command,reviewDigest:review.reviewDigest,evidence:review.verification.evidence};loseResponse=true;assert.ok((await handleAboutMigrationReview(req(command),call)).status>=500);
 const status=await (await handleAboutMigrationReview(req({action:'status',site,requestKey:key}),call)).json();assert.equal(status.status,'complete');assert.equal(status.sourceDigest,review.sourceDigest);assert.equal(status.reviewDigest,review.reviewDigest);assert.equal(status.result.recordId,rec.id);
 const later=(await db.query("select cms.save_draft($1,$2,$3,'page','/about','After HTTP migration',$4::jsonb,'en') value",[site,rec.id,status.result.revisionId,JSON.stringify(review.proposal)])).rows[0].value;
 names.length=0;const replay=await (await handleAboutMigrationReview(req(command),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,status.result);assert.deepEqual(names,['get_about_migration_result','apply_about_migration']);
 await root();const after=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[rec.id])).rows[0];assert.equal(after.current_revision_id,later.revisionId);assert.equal(after.published_revision_id,rec.published_revision_id);
});

