test('hero video migration evidence binds source checksum, silent processing, tenant and current usage rights',async()=>{
 const id=randomUUID(),source='c'.repeat(64),processed='d'.repeat(64);
 await root();
 await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,'review.mp4','video/mp4',100,$5,'ready',$6,'hero-video-1')",[id,site,editor,randomUUID(),`${site}/${id}/original`,source]);
 await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,'video/mp4',100,1280,720,'ready','approved','PRIVATE_VIDEO_RIGHTS',15,30,false,'h264','yuv420p')",[site,id,`${site}/${id}/delivery.mp4`,processed]);
 const bindings=[{assetId:id,sourceSha256:source}];
 const review=async(value=bindings,s=site)=>(await db.query('select cms.review_hero_video_migration_media($1,$2::jsonb) value',[s,JSON.stringify(value)])).rows[0].value;
 await actor(editor);let result=await review();assert.equal(result[0].available,true);assert.equal(result[0].sourceMatches,true);assert.equal(result[0].processedSha256,processed);assert.equal(JSON.stringify(result).includes('PRIVATE_VIDEO_RIGHTS'),false);
 assert.equal((await review([{assetId:id,sourceSha256:'e'.repeat(64)}]))[0].available,false);
 await assert.rejects(review([...bindings,...bindings]),/invalid_video_media_bindings/);
 await actor(outsider);await assert.rejects(review(),/forbidden/);
 await actor(editor);await assert.rejects(review(bindings,otherSite),/forbidden/);
 for(const update of ["rights_status='revoked'","rights_status='approved',rights_expires_at=now()-interval '1 second'","rights_expires_at=null,archived_at=now()"]){
  await root();await db.query(`update cms.media_objects set ${update} where website_id=$1 and id=$2`,[site,id]);await actor(editor);assert.equal((await review())[0].available,false);
 }
 await root();await db.query("update cms.media_objects set archived_at=null where website_id=$1 and id=$2",[site,id]);await db.query("update cms.uploads set inspection_version='image-1' where id=$1",[id]);await actor(editor);result=await review();assert.equal(result[0].sourceMatches,false);assert.equal(result[0].available,false);
 const missing=(await review([{assetId:randomUUID(),sourceSha256:source}]))[0];assert.equal(missing.available,false);assert.equal(missing.revision,null);
});
