test('desktop/mobile video references protect draft and active-preview assets from archive',async()=>{
 for(const field of ['desktopAssetId','mobileAssetId']){
  const id=randomUUID();await root();
  await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,'video/mp4',100,1280,720,'ready',15,30,false,'h264','yuv420p')",[site,id,`${site}/${id}/delivery.mp4`,'a'.repeat(64)]);
  await db.query("insert into cms.permissions(website_id,role_id,action,content_type) values($1,$2,'delete','document') on conflict do nothing",[site,editorRole]);
  const payload={title:'Video reference protection',composition:{sections:[{kind:'homepageHero',data:{background:{kind:'video',[field]:id}}}]}};
  await actor(editor);const route=`/journeys/video-reference-${field.toLowerCase()}`,draft=await save(route,null,null,payload);
  const usage=(await db.query('select cms.media_usage($1,$2) value',[site,id])).rows[0].value;assert.ok(usage.some(row=>row.recordId===draft.recordId&&row.draft));
  const archive=()=>db.query('select cms.archive_media($1,$2,1,true)',[site,id]);await assert.rejects(archive(),/media_in_use/);
  const session=await preview(draft),next=await save(route,draft.recordId,draft.revisionId,{title:'Video removed'});await assert.rejects(archive(),/media_in_use/);
  await db.query('select cms.revoke_preview($1)',[session.previewId]);await archive();
  await assert.rejects(save(route,draft.recordId,next.revisionId,payload),/archived_media_reference/);await assert.rejects(preview(draft),/archived_media_reference/);
  await actor(outsider);assert.deepEqual((await db.query('select cms.media_usage($1,$2) value',[site,id])).rows[0].value,[]);
 }
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='delete' and content_type='document'",[site,editorRole]);
});
