test('video validation status includes both references, deduplicates and fails conflicting image usage',async()=>{
 await root();const id=(await db.query("select id from cms.uploads where website_id=$1 and filename='eligible.mp4'",[site])).rows[0].id;
 await db.query("update cms.media_objects set rights_status='approved',archived_at=null,rights_expires_at=null where website_id=$1 and id=$2",[site,id]);
 await actor(editor);const draft=await save('/journeys/video-status-fixture',null,null,{title:'Status fixture',background:{desktopAssetId:id,mobileAssetId:id}});
 const status=async()=>(await db.query('select cms.get_record_media_status($1,$2,$3) value',[site,draft.recordId,draft.revisionId])).rows[0].value;
 assert.deepEqual(await status(),[{assetId:id,available:false}]); // Journey records cannot use hero videos.
 await actor(outsider);assert.equal(await status(),null);
 await actor(editor);await root();
 // Exercise homepage status using a temporary record identity without changing an existing homepage.
 const recordId=randomUUID(),revisionId=randomUUID();
 await db.query("insert into cms.records(id,website_id,content_type,path,locale,internal_title,owner_id) values($1,$2,'homepage','/','fr','Status fixture',$3)",[recordId,site,editor]);
 await db.query("insert into cms.revisions(id,website_id,record_id,payload,created_by) values($1,$2,$3,$4::jsonb,$5)",[revisionId,site,recordId,JSON.stringify({background:{desktopAssetId:id,mobileAssetId:id}}),editor]);
 const home=async()=>(await db.query('select cms.get_record_media_status($1,$2,$3) value',[site,recordId,revisionId])).rows[0].value;
 assert.deepEqual(await home(),[{assetId:id,available:true}]);
 const mixed=randomUUID();await db.query('insert into cms.revisions(id,website_id,record_id,payload,created_by) values($1,$2,$3,$4::jsonb,$5)',[mixed,site,recordId,JSON.stringify({background:{desktopAssetId:id},image:{assetId:id}}),editor]);assert.deepEqual((await db.query('select cms.get_record_media_status($1,$2,$3) value',[site,recordId,mixed])).rows[0].value,[{assetId:id,available:false}]);
 await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,id]);assert.deepEqual(await home(),[{assetId:id,available:false}]);
});
test('public hero video visibility rejects hidden, scheduled, restricted and malformed sections',async()=>{
 await root();const section={kind:'homepageHero',controls:{visible:true,locales:[],regions:[]}};
 const visible=async(value)=>(await db.query("select cms.hero_video_section_visible($1::jsonb,'en') value",[JSON.stringify(value)])).rows[0].value;
 assert.equal(await visible(section),true);
 for(const patch of [{visible:false},{visible:'true'},{locales:['fr']},{regions:['india']},{visibleFrom:'2099-01-01T00:00:00Z'},{visibleUntil:'2000-01-01T00:00:00Z'},{visibleFrom:'not-a-dateZ'},{visibleUntil:'2030-01-01'},{regions:null}])assert.equal(await visible({...section,controls:{...section.controls,...patch}}),false);
 assert.equal(await visible({...section,kind:'homepageStory'}),false);
 assert.equal(await visible({...section,controls:{...section.controls,visibleFrom:'2000-01-01T00:00:00Z',visibleUntil:'2099-01-01T00:00:00Z',locales:['en']}}),true);
});
