test('homepage publication guard rechecks direct selections and links after withdrawal or rights changes',async()=>{
 await root();const asset='homepage-release-image';await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Fixture rights')",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
 await actor(editor);const trip=await save('/journeys/home-release-target',null,null,{slug:'home-release-target',title:'Forest',description:'Forest journey',intro:'Explore the forest',region:'India',duration:'Five days',bestMonths:'November',media:[{assetId:asset,alt:'Forest',role:'hero'}]});await review(trip,'submit');await actor(reviewer);await review(trip,'approve');await validate(trip);await actor(publisher);await publish(trip);
 const section={kind:'homepageJourneys',controls:{visible:true},data:{items:[{recordId:trip.recordId}],button:{href:'/journeys/home-release-target'}}};await actor(editor);let draft=await save('/journeys/home-release-harness',null,null,{composition:{sections:[section]}});
 await root();await db.exec("create temporary table home_release_fixture(website_id uuid,id uuid,content_type text,path text,locale text,published_revision_id uuid);create trigger home_guard before update on home_release_fixture for each row execute function cms.enforce_homepage_publication_references()");await db.query("insert into home_release_fixture values($1,$2,'homepage','/','en',null)",[site,draft.recordId]);
 const release=()=>db.query('update home_release_fixture set published_revision_id=$1',[draft.revisionId]);await release();await db.exec('update home_release_fixture set published_revision_id=null');
 await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await assert.rejects(release(),/homepage_reference_verification_required/);await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await release();await db.exec('update home_release_fixture set published_revision_id=null');
 await db.query('update cms.records set published_revision_id=null where id=$1',[trip.recordId]);await assert.rejects(release(),/homepage_reference_verification_required/);
 await actor(editor);draft=await save('/journeys/home-release-harness',draft.recordId,draft.revisionId,{composition:{sections:[{...section,data:{...section.data,items:[]}}]}});await root();await assert.rejects(release(),/homepage_link_verification_required/);
 await actor(editor);draft=await save('/journeys/home-release-harness',draft.recordId,draft.revisionId,{composition:{sections:[{...section,controls:{visible:false}}]}});await root();await release();await db.exec('update home_release_fixture set published_revision_id=null');
 await db.query('update home_release_fixture set website_id=$1',[otherSite]);await assert.rejects(release(),/homepage_reference_verification_required/);await db.exec('drop table home_release_fixture');
});
test('public homepage boundary allowlists visible published content and strips statistic evidence',async()=>{
 await root();const home=(await db.query("select id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0],rev=randomUUID();
 const controls={visible:true,locales:[],regions:[],label:'Story',headingLevel:'h2'},story={id:'story',kind:'homepageStory',controls:{...controls,private:'PRIVATE_CONTROL'},data:{eyebrow:'Story',heading:{lines:[{runs:[{text:'Our story',emphasis:false}]}]},copy:'Public copy',button:{label:'About',href:'/about',newWindow:false},ledgerTitle:'Experience',statistics:[{id:'years',value:75,suffix:'+',label:'Years',source:'PRIVATE_EVIDENCE'}],private:'PRIVATE_DATA'}};
 const payload={private:'PRIVATE_ROOT',composition:{schemaVersion:1,title:'Home',private:'PRIVATE_COMPOSITION',sections:[story,{...story,id:'hidden',controls:{...controls,visible:false},data:{copy:'PRIVATE_HIDDEN'}},{...story,id:'future',controls:{...controls,visibleFrom:'2099-01-01T00:00:00Z'},data:{copy:'PRIVATE_FUTURE'}}]}};
 await db.query('insert into cms.revisions(id,website_id,record_id,payload,created_by) values($1,$2,$3,$4::jsonb,$5)',[rev,site,home.id,JSON.stringify(payload),editor]);
 const get=async(s=site)=>(await db.query('select cms.get_public_homepage($1) value',[s])).rows[0].value;
 await actor(null,'anon');assert.equal(await get(),null);await root();
 // Isolated read-boundary fixture. No claim that this incomplete composition can publish.
 await db.exec('alter table cms.records disable trigger user');try{await db.query('update cms.records set published_revision_id=$1 where id=$2',[rev,home.id]);}finally{await db.exec('alter table cms.records enable trigger user');}
 try{
  await actor(null,'anon');assert.equal(await get(),null);await root();await db.query("insert into cms.validation_policy values('homepage','homepage-1') on conflict(content_type) do update set validator_version='homepage-1'");await db.query("insert into cms.validations(revision_id,validator_version,valid,findings,checked_at,expires_at) values($1,'homepage-1',true,'[]',now(),now()+interval '15 minutes')",[rev]);
  await actor(null,'anon');const value=await get();assert.equal(value.revisionId,rev);assert.equal(value.payload.composition.sections.length,1);assert.equal(value.payload.composition.sections[0].data.statistics[0].value,75);assert.equal(JSON.stringify(value).includes('PRIVATE'),false);assert.equal(await get(otherSite),null);
  await root();await db.query("update cms.validations set expires_at=now()-interval '1 second' where revision_id=$1",[rev]);await actor(null,'anon');assert.equal((await get()).revisionId,rev);
  await root();await db.query('update cms.validations set valid=false where revision_id=$1',[rev]);await actor(null,'anon');assert.equal(await get(),null);
  await root();await db.query('update cms.validations set valid=true where revision_id=$1',[rev]);await db.query('update cms.records set published_revision_id=null where id=$1',[home.id]);await actor(null,'anon');assert.equal(await get(),null);
 }finally{await root();await db.exec('alter table cms.records disable trigger user');try{await db.query('update cms.records set published_revision_id=$1 where id=$2',[home.published_revision_id,home.id]);}finally{await db.exec('alter table cms.records enable trigger user');}await db.query("insert into cms.validation_policy values('homepage','homepage-1') on conflict(content_type) do update set validator_version='homepage-1'");}
});

test('homepage header release rechecks published settings, menus, descendants and image rights',async()=>{
 await root();await db.exec('begin');
 try{
  const settings=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and content_type='settings' and locale='en'",[site])).rows[0];
  const asset='homepage-header-release-logo';
  await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Fixture rights')",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
  await actor(editor);const trip=await save('/journeys/header-release-target',null,null,{slug:'header-release-target',title:'Header journey',media:[{assetId:asset,role:'hero',alt:'Forest'}]});
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[trip.revisionId,trip.recordId]);
  await actor(editor);const menu=(await db.query("select cms.save_draft($1,null,null,'navigation',null,'Header release menu',$2::jsonb) value",[site,JSON.stringify({schemaVersion:1,title:'Header release menu',items:[{id:'trip',parentId:null,label:'Forest',target:{kind:'record',recordId:trip.recordId,contentType:'journey'},visibility:{visible:true}}]})])).rows[0].value;
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[menu.revisionId,menu.recordId]);
  const payload=newGlobalSettings();payload.header.mainMenu={recordId:menu.recordId};payload.brand.logo={assetId:asset,alt:'Brand'};
  await actor(editor);const draft=(await db.query("select cms.save_draft($1,$2,$3,'settings',null,'Header release settings',$4::jsonb) value",[site,settings.id,settings.current_revision_id,JSON.stringify(payload)])).rows[0].value;
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[draft.revisionId,draft.recordId]);
  await db.exec('create temporary table home_header_fixture(website_id uuid,id uuid,content_type text,path text,locale text,published_revision_id uuid);create trigger header_guard before update on home_header_fixture for each row execute function cms.enforce_homepage_header_release()');
  await db.query("insert into home_header_fixture values($1,$2,'homepage','/','en',null)",[site,randomUUID()]);
  const release=()=>db.query('update home_header_fixture set published_revision_id=$1',[randomUUID()]);
  const reset=()=>db.exec('update home_header_fixture set published_revision_id=null');
  const rejected=async()=>{await db.exec('savepoint rejected_release');try{await assert.rejects(release(),/homepage_header_verification_required/);}finally{await db.exec('rollback to savepoint rejected_release');}};
  await release();await reset();
  await db.query('update cms.records set published_revision_id=null where id=$1',[menu.recordId]);await rejected();
  await db.query('update cms.records set published_revision_id=$1 where id=$2',[menu.revisionId,menu.recordId]);await release();await reset();
  await db.query('update cms.records set published_revision_id=null where id=$1',[trip.recordId]);await rejected();
  await db.query('update cms.records set published_revision_id=$1 where id=$2',[trip.revisionId,trip.recordId]);
  await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await rejected();
  await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await release();await reset();
  await db.query('update cms.records set published_revision_id=null where id=$1',[draft.recordId]);await rejected();
  await db.query('update cms.records set published_revision_id=$1 where id=$2',[draft.revisionId,draft.recordId]);
  await db.query('update home_header_fixture set website_id=$1',[otherSite]);await rejected();
  await db.query('update home_header_fixture set website_id=$1',[site]);await release();await reset();
  assert.equal((await db.query('select published_revision_id from home_header_fixture')).rows[0].published_revision_id,null);
 }finally{await db.exec('rollback');await root();}
});

test('homepage completes real trusted validation, review, publication, restore and withdrawal',async()=>{
 await root();await db.exec('begin');
 try{
  const {planHomepageMigration}=await import('../lib/cms/homepage-migration.ts'),{homepageMigrationDependencies}=await import('../lib/cms/homepage-migration-review.ts'),{makeHomepageMigrationFixture}=await import('./fixtures/cms-homepage-migration.mjs');
  const payload=structuredClone(planHomepageMigration(homepageMigrationDependencies,makeHomepageMigrationFixture().mappings).previewPayload);
  payload.composition.sections=payload.composition.sections.filter(s=>['homepageHero','homepageStory'].includes(s.kind));
  payload.composition.sections[0].data.background={kind:'image'};
  payload.composition.sections[1].data.statistics.forEach(s=>s.source='PRIVATE_STATISTIC_EVIDENCE');
  const assets=new Set();function collect(value){if(!value||typeof value!=='object')return;for(const [key,item]of Object.entries(value)){if(key==='assetId')assets.add(item);else collect(item);}}collect(payload);
  for(const asset of assets)await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Fixture rights') on conflict(website_id,id) do nothing",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
  await actor(editor);const menu=(await db.query("select cms.save_draft($1,null,null,'navigation',null,'Homepage workflow menu',$2::jsonb) value",[site,JSON.stringify({schemaVersion:1,title:'Main menu',items:[{id:'contact',parentId:null,label:'Contact',target:{kind:'url',href:'/contact'},visibility:{visible:true}}]})])).rows[0].value;
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[menu.revisionId,menu.recordId]);
  const settings=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and content_type='settings' and locale='en'",[site])).rows[0],global=newGlobalSettings();global.header.mainMenu={recordId:menu.recordId};
  await actor(editor);const settingsDraft=(await db.query("select cms.save_draft($1,$2,$3,'settings',null,'Homepage workflow settings',$4::jsonb) value",[site,settings.id,settings.current_revision_id,JSON.stringify(global)])).rows[0].value;
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[settingsDraft.revisionId,settingsDraft.recordId]);
  const home=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0];
  const saveHome=async(expected,value)=>{await actor(editor);return (await db.query("select cms.save_draft($1,$2,$3,'homepage','/','Homepage',$4::jsonb) value",[site,home.id,expected,JSON.stringify(value)])).rows[0].value;};
  const draft=await saveHome(home.current_revision_id,payload);
  const rejected=async(work,pattern)=>{await db.exec('savepoint rejected_action');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to savepoint rejected_action');}};
  await actor(publisher);await rejected(()=>publish(draft),/approved_revision_required/);
  await actor(editor);await review(draft,'submit');await rejected(()=>review(draft,'approve'),/self_approval_forbidden/);
  await actor(reviewer);await review(draft,'approve');await actor(publisher);await rejected(()=>publish(draft),/validated_revision_required/);
  const check=async record=>{await actor(null,'service_role');return runTrustedValidation(async(name,args)=>name==='get_validation_input'?(await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value:db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]),{site,record:record.recordId,revision:record.revisionId});};
  const checked=await check(draft);assert.deepEqual(checked.findings.filter(f=>f.severity==='error'),[]);assert.equal(checked.contentChecksPass,true);assert.equal(checked.validatorVersion,'homepage-1');
  await root();await db.query('update cms.records set published_revision_id=null where id=$1',[menu.recordId]);await actor(publisher);await rejected(()=>publish(draft),/homepage_header_verification_required/);
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[menu.revisionId,menu.recordId]);await actor(publisher);await publish(draft);
  const live=async()=>{await actor(null,'anon');return (await db.query('select cms.get_public_homepage($1) value',[site])).rows[0].value;};
  let published=await live();assert.equal(published.revisionId,draft.revisionId);assert.equal(published.payload.composition.sections.length,2);assert.equal(JSON.stringify(published).includes('PRIVATE_STATISTIC_EVIDENCE'),false);
  const changed=structuredClone(payload);changed.composition.sections[1].data.copy='An updated homepage story.';
  const newer=await saveHome(draft.revisionId,changed);assert.equal((await live()).revisionId,draft.revisionId);
  await actor(editor);await review(newer,'submit');await actor(reviewer);await review(newer,'approve');assert.equal((await check(newer)).contentChecksPass,true);await actor(publisher);await publish(newer);assert.equal((await live()).revisionId,newer.revisionId);
  await actor(editor);const restored=(await db.query('select cms.restore_draft($1,$2,$3,$4) value',[site,home.id,draft.revisionId,newer.revisionId])).rows[0].value;assert.notEqual(restored.revisionId,draft.revisionId);assert.equal((await live()).revisionId,newer.revisionId);
  await actor(editor);await review(restored,'submit');await actor(reviewer);await review(restored,'approve');assert.equal((await check(restored)).contentChecksPass,true);await actor(publisher);await publish(restored);assert.equal((await live()).revisionId,restored.revisionId);
  await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,home.id,restored.revisionId]);assert.equal(await live(),null);
 }finally{await db.exec('rollback');await root();}
});

test('homepage migration atomically checks image/video provenance and record revisions, then recovers without overwriting later drafts',async()=>{
 await root();await db.exec('begin');
 try{
  const home=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0];
  const bindings=[];
  for(const kind of ['image','video']){
   const id=randomUUID(),video=kind==='video',source=(video?'b':'a').repeat(64);bindings.push({kind,assetId:id,sourceSha256:source});
   await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,$5,$6,100,$7,'ready',$8,$9)",[id,site,editor,randomUUID(),video?'source.mp4':'source.jpg',video?'video/mp4':'image/jpeg',`${site}/${id}/original`,source,video?'hero-video-1':'image-1']);
   await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,$5,100,80,40,'ready','approved','Fixture rights',$6,$7,$8,$9,$10)",[site,id,`${site}/${id}/delivery.${video?'mp4':'webp'}`,'d'.repeat(64),video?'video/mp4':'image/webp',video?10:null,video?30:null,video?false:null,video?'h264':null,video?'yuv420p':null]);
  }
  await actor(editor);const trip=await save('/journeys/home-migration-source',null,null,{title:'Migration source journey'});
  const evidence=[];for(const {kind,...binding}of bindings)evidence.push(...(await db.query(`select cms.${kind==='video'?'review_hero_video_migration_media':'review_about_migration_media'}($1,$2::jsonb) value`,[site,JSON.stringify([binding])])).rows[0].value);
  assert.ok(evidence.every(e=>e.available));
  const payload={composition:{schemaVersion:1,title:'Migrated homepage draft',sections:[{id:'hero',kind:'homepageHero',controls:{label:'Hero'},data:{poster:{assetId:bindings[0].assetId,alt:'Forest'},background:{kind:'video',desktopAssetId:bindings[1].assetId}}},{id:'journeys',kind:'homepageJourneys',controls:{label:'Journeys'},data:{items:[{recordId:trip.recordId}]}}]}};
  const manifest={recordId:home.id,expectedRevision:home.current_revision_id,payload,bindings,evidence,records:[{recordId:trip.recordId,revisionId:trip.revisionId,type:'journey',path:'/journeys/home-migration-source'}]},key=randomUUID(),source='a'.repeat(64),reviewDigest='b'.repeat(64);
  const apply=async(request=key,value=manifest,website=site)=>(await db.query('select cms.apply_homepage_migration($1,$2,$3,$4,$5::jsonb) value',[website,request,source,reviewDigest,JSON.stringify(value)])).rows[0].value;
  const rejected=async(work,pattern)=>{await db.exec('savepoint rejected_migration');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to savepoint rejected_migration');}};
  const result=await apply();assert.equal(result.recordId,home.id);assert.notEqual(result.revisionId,home.current_revision_id);assert.deepEqual(await apply(),result);
  const status=async()=> (await db.query('select cms.get_homepage_migration_result($1,$2) value',[site,key])).rows[0].value;
  assert.deepEqual((await status()).result,result);await actor(reviewer);assert.equal(await status(),null);await actor(editor);
  await rejected(()=>apply(key,{...manifest,payload:{...payload,changed:true}}),/idempotency_key_reused/);
  const later=(await db.query("select cms.save_draft($1,$2,$3,'homepage','/','Later draft',$4::jsonb) value",[site,home.id,result.revisionId,JSON.stringify({...payload,later:true})])).rows[0].value;
  await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,bindings[1].assetId]);await actor(editor);assert.deepEqual(await apply(),result);
  const fresh={...manifest,expectedRevision:later.revisionId},failedKey=randomUUID();await rejected(()=>apply(failedKey,fresh),/migration_media_unavailable/);
  await root();assert.equal((await db.query('select count(*)::int n from cms.homepage_migration_batches where request_key=$1',[failedKey])).rows[0].n,0);let state=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[home.id])).rows[0];assert.equal(state.current_revision_id,later.revisionId);assert.equal(state.published_revision_id,home.published_revision_id);
  await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,bindings[1].assetId]);await actor(editor);
  const newTrip=await save('/journeys/home-migration-source',trip.recordId,trip.revisionId,{title:'Changed source'});await rejected(()=>apply(randomUUID(),fresh),/migration_reference_changed/);
  const current={...fresh,records:[{...fresh.records[0],revisionId:newTrip.revisionId}]};await rejected(()=>apply(randomUUID(),{...current,evidence:current.evidence.map(e=>({...e,revision:999}))}),/migration_media_changed/);
  await rejected(()=>apply(randomUUID(),{...current,records:[]}),/migration_reference_mismatch/);
  await rejected(()=>apply(randomUUID(),current,otherSite),/forbidden/);
  await actor(outsider);await rejected(()=>apply(randomUUID(),current),/forbidden/);
 }finally{await db.exec('rollback');await root();}
});

test('homepage HTTP review and apply use full captured mappings and recover a lost result through actual database receipts',async()=>{
 await root();await db.exec('begin');
 try{
  const {handleHomepageMigrationReview}=await import('../lib/cms/homepage-migration-api.ts'),{makeHomepageMigrationFixture}=await import('./fixtures/cms-homepage-migration.mjs');
  const fixture=makeHomepageMigrationFixture(),mappedMedia=new Map();
  for(const binding of fixture.mappings.media){
   const previous=binding.assetId,id=randomUUID(),video=binding.sourcePath.endsWith('.mp4');binding.assetId=id;mappedMedia.set(previous,id);
   await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,$5,$6,100,$7,'ready',$8,$9)",[id,site,editor,randomUUID(),video?'source.mp4':'source.jpg',video?'video/mp4':'image/jpeg',`${site}/${id}/original`,binding.sourceSha256,video?'hero-video-1':'image-1']);
   await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,$5,100,80,40,'ready','approved','Fixture rights',$6,$7,$8,$9,$10)",[site,id,`${site}/${id}/delivery.${video?'mp4':'webp'}`,'d'.repeat(64),video?'video/mp4':'image/webp',video?10:null,video?30:null,video?false:null,video?'h264':null,video?'yuv420p':null]);
  }
  function replaceMedia(value){if(!value||typeof value!=='object')return;for(const [key,item]of Object.entries(value)){if(key==='assetId'&&mappedMedia.has(item))value[key]=mappedMedia.get(item);else replaceMedia(item);}}
  for(const record of fixture.records){
   replaceMedia(record.payload);await root();const existing=record.path?(await db.query('select id,current_revision_id from cms.records where website_id=$1 and path=$2 and locale=\'en\'',[site,record.path])).rows[0]:null;
   await actor(editor);const saved=(await db.query('select cms.save_draft($1,$2,$3,$4,$5,$6,$7::jsonb) value',[site,existing?.id??null,existing?.current_revision_id??null,record.type,record.path,'Homepage mapped source',JSON.stringify(record.payload)])).rows[0].value;
   fixture.mappings.records.find(item=>item.recordId===record.id).recordId=saved.recordId;
  }
  await root();const home=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0];await actor(editor);
  let loseResponse=false;const calls=[];const call=async(token,name,args)=>{
   assert.equal(token,'test.editor.token');calls.push(name);const entries=Object.entries(args),values=entries.map(([,v])=>v&&typeof v==='object'?JSON.stringify(v):v);
   const value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key}=>$${i+1}`).join(',')}) value`,values)).rows[0].value;
   if(name==='apply_homepage_migration'&&loseResponse){loseResponse=false;throw Error('Response lost after draft save');}return value;
  };
  const request=body=>new Request('https://cms.test/api/cms/migrations/homepage',{method:'POST',headers:{authorization:'Bearer test.editor.token','content-type':'application/json'},body:JSON.stringify(body)});
  const selection={site,recordId:home.id,expectedRevision:home.current_revision_id,mappings:fixture.mappings};
  const response=await handleHomepageMigrationReview(request({action:'review',...selection}),call);assert.equal(response.status,200);const reviewed=await response.json();assert.equal(reviewed.applyAvailable,true,JSON.stringify(reviewed.recordComparison.findings));
  const command={action:'apply',...selection,requestKey:randomUUID(),reviewDigest:reviewed.reviewDigest,evidence:{recordComparison:reviewed.recordComparison,mediaVerification:reviewed.mediaVerification}};
  loseResponse=true;assert.equal((await handleHomepageMigrationReview(request(command),call)).status,500);
  const status=await (await handleHomepageMigrationReview(request({action:'status',site,requestKey:command.requestKey}),call)).json();assert.equal(status.status,'complete');
  const saved=status.result;assert.equal(saved.recordId,home.id);
  const newer=(await db.query("select cms.save_draft($1,$2,$3,'homepage','/','Later client edit',$4::jsonb) value",[site,home.id,saved.revisionId,JSON.stringify({...reviewed.proposal,composition:{...reviewed.proposal.composition,title:'Later client edit'}})])).rows[0].value;
  calls.length=0;const retry=await handleHomepageMigrationReview(request(command),call);assert.equal(retry.status,200);const replay=await retry.json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,saved);assert.deepEqual(calls,['get_homepage_migration_result','apply_homepage_migration']);
  await root();const state=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[home.id])).rows[0];assert.equal(state.current_revision_id,newer.revisionId);assert.equal(state.published_revision_id,home.published_revision_id);
  const stored=(await db.query('select payload from cms.revisions where id=$1',[saved.revisionId])).rows[0].payload;assert.equal(stored.composition.sections.length,10);assert.deepEqual(stored,reviewed.proposal);
 }finally{await db.exec('rollback');await root();}
});

test('PDF reservations are caller scoped, recoverable and isolated from image/video processing and storage',async()=>{
 await root();await db.exec('begin');
 try{
  // Avoid unrelated fixture quota usage; transaction rollback preserves fixtures.
  await db.query("update cms.uploads set status='cancelled' where website_id=$1 and created_by=$2 and status in ('reserved','uploaded','processing')",[site,editor]);
  await actor(editor);const key=randomUUID();
  const reserve=async(request=key,filename='Client brochure.pdf',bytes=1200,mime='application/pdf')=>(await db.query('select cms.reserve_document_upload($1,$2,$3,$4,$5) value',[site,request,filename,mime,bytes])).rows[0].value;
  const upload=await reserve();assert.equal(upload.status,'reserved');assert.deepEqual(await reserve(),upload);
  // Use savepoints because PostgreSQL errors abort the transaction.
  async function rejects(work,pattern){await db.exec('savepoint rejected');await assert.rejects(work(),pattern);await db.exec('rollback to savepoint rejected');}
  await rejects(()=>reserve(key,'Changed.pdf'),/idempotency_key_reused/);
  for(const args of [[randomUUID(),'../guide.pdf'],[randomUUID(),'.pdf'],[randomUUID(),'guide.pdf',25000001],[randomUUID(),'guide.pdf',0],[randomUUID(),'guide.pdf',1200,'image/png']])await rejects(()=>reserve(...args),/invalid_upload/);
  assert.equal((await db.query('select cms.get_upload($1,$2) value',[site,upload.id])).rows[0].value.mime,'application/pdf');
  assert.ok((await db.query('select cms.list_document_uploads($1) value',[site])).rows[0].value.some(x=>x.id===upload.id));
  for(const fn of ['list_uploads','list_hero_video_uploads'])assert.ok(!(await db.query(`select cms.${fn}($1) value`,[site])).rows[0].value.some(x=>x.id===upload.id));
  assert.equal((await db.query('select cms.can_upload_object($1) value',[`${site}/${upload.id}/original`])).rows[0].value,false);
  await actor(outsider);assert.equal((await db.query('select cms.get_upload($1,$2) value',[site,upload.id])).rows[0].value,null);
  assert.deepEqual((await db.query('select cms.list_document_uploads($1) value',[site])).rows[0].value,[]);
  await rejects(()=>reserve(randomUUID()),/forbidden/);
  await actor(null,'service_role');
  for(const fn of ['claim_upload','claim_hero_video_upload'])assert.equal((await db.query(`select cms.${fn}($1,$2) value`,[site,upload.id])).rows[0].value,null);
  await actor(editor);const storageKey=`${site}/${upload.id}/original`;
  assert.deepEqual((await db.query('select cms.get_document_upload_transfer($1,$2) value',[site,upload.id])).rows[0].value,{id:upload.id,site,key:storageKey,mime:'application/pdf',bytes:1200});
  assert.equal((await db.query('select cms.get_document_upload_transfer($1,$2) value',[otherSite,upload.id])).rows[0].value,null);
  for(const bucket of ['cms-originals','cms-video-originals','cms-document-media'])await rejects(()=>db.query('insert into storage.objects(bucket_id,name) values($1,$2)',[bucket,storageKey]),/row-level security/);
  await db.query("insert into storage.objects(bucket_id,name) values('cms-document-originals',$1)",[storageKey]);
  assert.equal((await db.query("select count(*)::int n from storage.objects where bucket_id='cms-document-originals'")).rows[0].n,0);
  await db.query("update storage.objects set name='changed' where bucket_id='cms-document-originals'");await db.query("delete from storage.objects where bucket_id='cms-document-originals'");
  await root();assert.equal((await db.query("select count(*)::int n from storage.objects where bucket_id='cms-document-originals' and name=$1",[storageKey])).rows[0].n,1);
  await db.query("insert into storage.objects(bucket_id,name) values('cms-document-media',$1)",[`${site}/${upload.id}/delivery.pdf`]);
  for(const identity of [editor,outsider,null]){await actor(identity,identity?'authenticated':'anon');assert.equal((await db.query("select count(*)::int n from storage.objects where bucket_id in ('cms-document-originals','cms-document-media')")).rows[0].n,0);}
  await actor(outsider);await rejects(()=>db.query("insert into storage.objects(bucket_id,name) values('cms-document-originals',$1)",[storageKey]),/row-level security/);
  await actor(editor);await db.query('select cms.cancel_upload($1,$2)',[site,upload.id]);assert.equal((await reserve()).status,'cancelled');
  assert.equal((await db.query('select cms.get_document_upload_transfer($1,$2) value',[site,upload.id])).rows[0].value,null);
  const expired=await reserve(randomUUID());await root();await db.query("update cms.uploads set expires_at=now()-interval '1 second' where id=$1",[expired.id]);await actor(editor);
  assert.equal((await db.query('select cms.get_upload($1,$2) value',[site,expired.id])).rows[0].value.status,'expired');
 }finally{await db.exec('rollback');await root();}
});

test('PDF reception discovers only stored live reservations and recovers confirmation without repeating writes',async()=>{
 const {createDocumentReceptionAdapter,receiveDocuments}=await import('../lib/cms/document-reception.ts');
 await root();await db.exec('begin');
 try{
  await db.query("update cms.uploads set status='cancelled' where website_id=$1 and created_by=$2 and status in ('reserved','uploaded','processing')",[site,editor]);
  await actor(editor);const upload=(await db.query("select cms.reserve_document_upload($1,$2,'Reception.pdf','application/pdf',3) value",[site,randomUUID()])).rows[0].value;
  await actor(null,'service_role');assert.ok(!(await db.query('select cms.list_document_receptions(20) value')).rows[0].value.some(x=>x.id===upload.id));
  await actor(editor);await db.query("insert into storage.objects(bucket_id,name) values('cms-document-originals',$1)",[`${site}/${upload.id}/original`]);
  await db.exec('savepoint denied');await assert.rejects(db.query('select cms.get_document_reception($1,$2)',[site,upload.id]),/permission denied/);await db.exec('rollback to savepoint denied');
  await actor(null,'service_role');let confirmations=0;
  const adapter=createDocumentReceptionAdapter({url:'https://cms.test',serviceKey:'test-worker'},async(url,options)=>{
   if(url.pathname.startsWith('/storage/'))return new Response(Buffer.from('PDF'));
   const args=JSON.parse(options.body),fn=url.pathname.split('/').at(-1);
   if(fn==='list_document_receptions')return Response.json((await db.query('select cms.list_document_receptions($1) value',[args.p_limit])).rows[0].value);
   if(fn==='get_document_reception')return Response.json((await db.query('select cms.get_document_reception($1,$2) value',[args.p_site,args.p_upload])).rows[0].value);
   assert.equal(fn,'confirm_upload');confirmations++;await db.query('select cms.confirm_upload($1,$2,$3,$4)',[args.p_site,args.p_upload,args.p_sha256,args.p_bytes]);throw Error('Simulated lost acknowledgement after commit');
  });
  const result=await receiveDocuments(adapter,20);assert.equal(result.find(x=>x.id===upload.id).status,'unacknowledged');
  assert.equal(await adapter.confirm(site,upload.id),'not_reserved');assert.equal(confirmations,1);
  assert.ok(!(await receiveDocuments(adapter,20)).some(x=>x.id===upload.id));
  await root();const row=(await db.query('select status,original_sha256,inspection_version from cms.uploads where id=$1',[upload.id])).rows[0];
  assert.deepEqual(row,{status:'uploaded',original_sha256:createHash('sha256').update('PDF').digest('hex'),inspection_version:null});
  assert.equal((await db.query('select count(*)::int n from cms.media_objects where id=$1',[upload.id])).rows[0].n,0);
 }finally{await db.exec('rollback');await root();}
});

test('document processing fences stale workers, limits retries and registers private files without image/public access',async()=>{
 await root();await db.exec('begin');
 try{
  await db.query("update cms.uploads set status='cancelled' where website_id=$1 and created_by=$2 and status in ('reserved','uploaded','processing')",[site,editor]);
  const reserve=async()=>{await actor(editor);return (await db.query("select cms.reserve_document_upload($1,$2,'Worker.pdf','application/pdf',3) value",[site,randomUUID()])).rows[0].value;};
  const upload=await reserve();
  async function rejects(work,pattern){await db.exec('savepoint rejected');await assert.rejects(work(),pattern);await db.exec('rollback to savepoint rejected');}
  await rejects(()=>db.query('select cms.claim_document_upload($1,$2)',[site,upload.id]),/permission denied/);
  await actor(null,'service_role');assert.equal((await db.query('select cms.claim_document_upload($1,$2) value',[site,upload.id])).rows[0].value,null);
  const hash=createHash('sha256').update('PDF').digest('hex');await db.query('select cms.confirm_upload($1,$2,$3,3)',[site,upload.id,hash]);
  const claim=async()=>(await db.query('select cms.claim_document_upload($1,$2) value',[site,upload.id])).rows[0].value;
  const first=await claim();assert.equal(first.deliveryKey,`${site}/${upload.id}/delivery.pdf`);assert.equal(await claim(),null);
  await root();await db.query("update cms.uploads set leased_until=now()-interval '1 second' where id=$1",[upload.id]);await actor(null,'service_role');
  const next=await claim();assert.notEqual(next.leaseToken,first.leaseToken);
  const result={originalSha256:hash,sha256:'a'.repeat(64),bytes:10,pages:1,parserVersion:'6.10.0',inspectionVersion:'document-pdf-1'};
  const finish=(token,data=result)=>db.query('select cms.finish_document_upload($1,$2,$3,$4::jsonb) value',[site,upload.id,token,JSON.stringify(data)]);
  await rejects(()=>finish(first.leaseToken),/upload_lease_lost/);
  for(const change of [{pages:0},{pages:301},{bytes:25000001},{originalSha256:'b'.repeat(64)},{inspectionVersion:'image-1'},{parserVersion:'unverified'},{extra:true}])await rejects(()=>finish(next.leaseToken,{...result,...change}),/invalid_document_inspection_result/);
  assert.equal((await finish(next.leaseToken)).rows[0].value,upload.id);assert.equal(await claim(),null);
  await rejects(()=>finish(next.leaseToken),/upload_lease_lost/);
  const file=(await db.query('select * from cms.document_files where website_id=$1 and id=$2',[site,upload.id])).rows[0];assert.equal(file.rights_status,'pending');assert.equal(file.page_count,1);
  await actor(editor);await rejects(()=>db.query('select * from cms.document_files'),/permission denied/);
  await actor(null,'anon');assert.equal((await db.query('select cms.get_public_media($1,$2) value',[site,upload.id])).rows[0].value,null);
  const failed=await reserve();await actor(null,'service_role');await db.query('select cms.confirm_upload($1,$2,$3,3)',[site,failed.id,hash]);
  for(let attempt=0;attempt<3;attempt++){const job=(await db.query('select cms.claim_document_upload($1,$2) value',[site,failed.id])).rows[0].value;assert.ok(job);await db.query("select cms.fail_upload($1,$2,$3,'scan_unavailable',true)",[site,failed.id,job.leaseToken]);}
  assert.equal((await db.query('select cms.claim_document_upload($1,$2) value',[site,failed.id])).rows[0].value,null);
  assert.ok(!(await db.query('select cms.list_document_work(20) value')).rows[0].value.some(x=>x.id===failed.id||x.id===upload.id));
  await root();assert.equal((await db.query('select status from cms.uploads where id=$1',[failed.id])).rows[0].status,'rejected');
 }finally{await db.exec('rollback');await root();}
});

test('real PDF processing reaches durable private completion and recovers a lost completion acknowledgement',{skip:!process.env.CMS_TEST_PDF_PYTHON},async()=>{
 const {processDocumentUpload}=await import('../lib/cms/document-upload-worker.ts');const {execFile}=await import('node:child_process');const {promisify}=await import('node:util');const {tmpdir}=await import('node:os');const path=await import('node:path');
 const dir=await fs.mkdtemp(path.join(tmpdir(),'cms-pdf-database-'));await root();await db.exec('begin');
 try{
  const source=path.join(dir,'fixture.pdf'),python=process.env.CMS_TEST_PDF_PYTHON;
  const {stdout}=await promisify(execFile)(python,['-c',"from pypdf import PdfWriter; import pypdf,sys; w=PdfWriter(); w.add_blank_page(595,842); w.write(sys.argv[1]); print(pypdf.__version__)",source]);
  const bytes=await fs.readFile(source),hash=createHash('sha256').update(bytes).digest('hex');
  await db.query("update cms.uploads set status='cancelled' where website_id=$1 and created_by=$2 and status in ('reserved','uploaded','processing')",[site,editor]);await actor(editor);
  const upload=(await db.query("select cms.reserve_document_upload($1,$2,'Guide.pdf','application/pdf',$3) value",[site,randomUUID(),bytes.length])).rows[0].value;
  await actor(null,'service_role');await db.query('select cms.confirm_upload($1,$2,$3,$4)',[site,upload.id,hash,bytes.length]);
  let stored,finishCount=0;const adapter={
   claim:async(s,id)=>(await db.query('select cms.claim_document_upload($1,$2) value',[s,id])).rows[0].value,
   read:async(key,expected)=>{assert.equal(key,`${site}/${upload.id}/original`);assert.equal(expected,bytes.length);return bytes;},scan:async()=> 'clean',
   putVerified:async(key,data,sha,mime)=>{assert.equal(key,`${site}/${upload.id}/delivery.pdf`);assert.equal(mime,'application/pdf');assert.equal(createHash('sha256').update(data).digest('hex'),sha);stored={sha,bytes:data.length};},
   finish:async(job,result)=>{finishCount++;assert.equal(result.sha256,stored.sha);assert.equal(result.bytes,stored.bytes);await db.query('select cms.finish_document_upload($1,$2,$3,$4::jsonb)',[job.site,job.id,job.leaseToken,JSON.stringify(result)]);throw Error('Lost completion acknowledgement');},
   fail:async()=>assert.fail('A completion acknowledgement loss must not fail the committed upload'),
  };
  const runtime={python,script:path.resolve('scripts/cms/pdf/pdf_structure.py'),parserVersion:stdout.trim(),temporaryRoot:dir};
  assert.equal((await processDocumentUpload(adapter,site,upload.id,runtime)).status,'unacknowledged');
  assert.equal((await processDocumentUpload(adapter,site,upload.id,runtime)).status,'not_claimed');assert.equal(finishCount,1);
  const file=(await db.query('select sha256,byte_size,page_count,rights_status from cms.document_files where website_id=$1 and id=$2',[site,upload.id])).rows[0];assert.equal(file.sha256,stored.sha);assert.equal(file.page_count,1);assert.equal(file.rights_status,'pending');
  await root();assert.equal((await db.query('select status from cms.uploads where id=$1',[upload.id])).rows[0].status,'ready');
 }finally{await root();await db.exec('rollback');await fs.rm(dir,{recursive:true,force:true});}
});

