  await actor(editor);const about=(await db.query("select cms.save_draft($1,$2,$3,'page','/about','About resources',$4::jsonb) value",[site,previousAbout?.id??null,previousAbout?.current_revision_id??null,JSON.stringify(aboutPayload)])).rows[0].value;
