test('Conservation HTTP apply recovers a lost response using exact receipts without overwriting a later draft',async()=>{
 const {handleConservationMigrationReview}=await import('../lib/cms/conservation-migration-api.ts');const {default:inventory}=await import('../docs/cms/conservation-migration-inventory.json',{with:{type:'json'}});
 await root();const previous=(await db.query('select manifest from cms.conservation_migration_batches order by created_at desc limit 1')).rows[0].manifest;const rec=(await db.query('select id,current_revision_id,published_revision_id from cms.records where id=$1',[previous.recordId])).rows[0];
 const selection={action:'review',site,recordId:rec.id,expectedRevision:rec.current_revision_id,bindings:inventory.media.map(m=>({sourcePath:m.sourcePath,sourceSha256:m.sha256,assetId:previous.bindings.find(b=>b.sourceSha256===m.sha256).assetId}))};
 const req=body=>new Request('http://localhost/api/cms/migrations/conservation',{method:'POST',headers:{authorization:'Bearer test.editor.token',origin:'http://localhost','content-type':'application/json'},body:JSON.stringify(body)});
 let loseResponse=false;const names=[];const call=async(token,name,args)=>{assert.equal(token,'test.editor.token');assert.ok(['get_editor_record','review_conservation_migration_media','get_conservation_migration_result','apply_conservation_migration'].includes(name));names.push(name);const entries=Object.entries(args),values=entries.map(([,v])=>v&&typeof v==='object'?JSON.stringify(v):v);const result=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key}=>$${i+1}`).join(',')}) value`,values)).rows[0].value;if(name==='apply_conservation_migration'&&loseResponse){loseResponse=false;throw Error('Simulated response lost after commit');}return result;};
 await actor(editor);let reviewResponse=await handleConservationMigrationReview(req(selection),call);assert.equal(reviewResponse.status,200);let review=await reviewResponse.json();assert.equal(review.applyAvailable,true);
 const key=randomUUID();let command={...selection,action:'apply',requestKey:key,reviewDigest:review.reviewDigest,evidence:review.verification.evidence};
 await root();await db.query("update cms.media_objects set title='Changed after API review' where website_id=$1 and id=$2",[site,selection.bindings[0].assetId]);await actor(editor);assert.equal((await handleConservationMigrationReview(req(command),call)).status,409);
 review=await (await handleConservationMigrationReview(req(selection),call)).json();command={...command,reviewDigest:review.reviewDigest,evidence:review.verification.evidence};loseResponse=true;assert.ok((await handleConservationMigrationReview(req(command),call)).status>=500);
 const status=await (await handleConservationMigrationReview(req({action:'status',site,requestKey:key}),call)).json();assert.equal(status.status,'complete');assert.equal(status.sourceDigest,review.sourceDigest);assert.equal(status.reviewDigest,review.reviewDigest);assert.equal(status.result.recordId,rec.id);
 const later=(await db.query("select cms.save_draft($1,$2,$3,'page','/conservation-commitment','After HTTP migration',$4::jsonb,'en') value",[site,rec.id,status.result.revisionId,JSON.stringify(review.proposal)])).rows[0].value;
 names.length=0;const replay=await (await handleConservationMigrationReview(req(command),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,status.result);assert.deepEqual(names,['get_conservation_migration_result','apply_conservation_migration']);
 await root();const after=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[rec.id])).rows[0];assert.equal(after.current_revision_id,later.revisionId);assert.equal(after.published_revision_id,rec.published_revision_id);
});


