test('contact release rechecks published form availability after validation and preserves the live revision on failure',async()=>{
 await root();await db.exec('begin');
 try{
  const {planContactMigration,contactMigrationDependencies}=await import('../lib/cms/contact-migration.ts');
  const inventory=JSON.parse(await fs.readFile(new URL('../docs/cms/contact-migration-inventory.json',import.meta.url),'utf8'));
  const bindings=inventory.media.map((m,i)=>({sourcePath:m.sourcePath,sourceSha256:m.sha256,assetId:`contact-release-${i}`}));
  for(const {assetId}of bindings)await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Fixture rights')",[site,assetId,`${site}/${assetId}/delivery.webp`,'a'.repeat(64)]);
  const check=async record=>{await actor(null,'service_role');return runTrustedValidation(async(name,args)=>name==='get_validation_input'?(await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value:db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]),{site,record:record.recordId,revision:record.revisionId});};
  const approve=async record=>{await actor(editor);await review(record,'submit');await actor(reviewer);await review(record,'approve');};
  const reject=async(work,pattern)=>{await db.exec('savepoint contact_rejected');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to savepoint contact_rejected');}};
  await actor(editor);const form=(await db.query("select cms.save_draft($1,null,null,'form',null,'Release form',$2::jsonb) value",[site,JSON.stringify({...newForm('name'),notificationRouteIds:[site]})])).rows[0].value;
  await installNotificationFixture(form);
  assert.equal((await check(form)).contentChecksPass,true);await approve(form);await actor(publisher);await publish(form);
  const photo=bindings.find(b=>b.sourcePath.endsWith('.webp')),social=bindings.find(b=>b!==photo);
  const payload=planContactMigration(contactMigrationDependencies,photo,social).previewPayload;payload.composition.sections[1].data.form={recordId:form.recordId};
  await root();const previous=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and path='/contact' and locale='en'",[site])).rows[0];
  const save=async(prev,body)=>{await actor(editor);return (await db.query("select cms.save_draft($1,$2,$3,'page','/contact','Contact',$4::jsonb) value",[site,prev.recordId,prev.revisionId,JSON.stringify(body)])).rows[0].value;};
  const first=await save({recordId:previous.id,revisionId:previous.current_revision_id},payload);
  const validation=await check(first);assert.equal(validation.contentChecksPass,true,JSON.stringify(validation.findings));await approve(first);
  await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,form.recordId,form.revisionId]);
  await reject(()=>publish(first),/contact_form_unavailable/);
  await publish(form);await publish(first);
  const live=async()=>{await actor(null,'anon');return (await db.query("select cms.get_public_page($1,'/contact','en') value",[site])).rows[0].value;};
  assert.equal((await live()).revisionId,first.revisionId);
  await root();await db.query('update cms.notification_email_routes set enabled=false where website_id=$1 and id=$1',[site]);assert.equal(await live(),null);
  await root();await db.query('update cms.notification_email_routes set enabled=true where website_id=$1 and id=$1',[site]);assert.equal((await live()).revisionId,first.revisionId);

  const edited=structuredClone(payload);edited.composition.sections[0].data.lead='A revised contact introduction.';
  const second=await save(first,edited);assert.equal((await check(second)).contentChecksPass,true);await approve(second);
  await root();await db.query("update cms.media_objects set rights_status='pending' where website_id=$1 and id=$2",[site,photo.assetId]);await actor(publisher);await reject(()=>publish(second),/media_verification_required/);
  await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,photo.assetId]);assert.equal((await live()).revisionId,first.revisionId);
  await root();await db.query('update cms.notification_worker_health set healthy=false where deployment_id=(select deployment_id from cms.website_notification_deployments where website_id=$1)',[site]);await actor(publisher);await reject(()=>publish(second),/contact_form_unavailable/);assert.equal(await live(),null);
  await root();await db.query('update cms.notification_worker_health set healthy=true,observed_at=clock_timestamp() where deployment_id=(select deployment_id from cms.website_notification_deployments where website_id=$1)',[site]);
  await actor(publisher);await publish(second);assert.equal((await live()).revisionId,second.revisionId);
  await root();await reject(()=>db.query("update cms.records set path='/contact-moved' where id=$1",[first.recordId]),/contact_page_route_not_ready/);
  const invalid=structuredClone(payload);invalid.composition.sections.push({id:'unsupported',kind:'text',controls:{label:'Unsupported'},data:{body:[]}});
  const bad=await save(second,invalid);assert.equal((await check(bad)).contentChecksPass,false);await approve(bad);await actor(null,'service_role');await receipt(bad,'composition-5',true);await actor(publisher);await reject(()=>publish(bad),/contact_page_section_unsupported/);
  assert.equal((await live()).revisionId,second.revisionId);await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,first.recordId,second.revisionId]);assert.equal(await live(),null);
 }finally{await db.exec('rollback');await root();}
});

