test('contact form migration saves both drafts atomically and recovers a lost response without replacing later edits',async()=>{
 await root();await db.exec('begin');try{
 const {handleContactFormMigration}=await import('../lib/cms/contact-form-migration-api.ts');
 const req=body=>new Request('http://localhost/api/cms/migrations/contact-forms',{method:'POST',headers:{authorization:'Bearer test.editor.token',origin:'http://localhost','content-type':'application/json'},body:JSON.stringify(body)});
 let loseResponse=false;const call=async(token,name,args)=>{assert.equal(token,'test.editor.token');assert.ok(['can','get_editor_record','apply_contact_form_migration','get_contact_form_migration_result'].includes(name));const entries=Object.entries(args);const value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key}=>$${i+1}`).join(',')}) value`,entries.map(([,v])=>v&&typeof v==='object'?JSON.stringify(v):v))).rows[0].value;if(name==='apply_contact_form_migration'&&loseResponse){loseResponse=false;throw Error('Lost completed response');}return value;};
 const targets=['contact','corporate'].map(variant=>({variant,recordId:null,expectedRevision:null}));
 await actor(editor);const review=await (await handleContactFormMigration(req({action:'review',site,targets}),call)).json();assert.equal(review.proposal.forms.length,2);
 const key=randomUUID(),command={action:'apply',site,targets,requestKey:key,reviewDigest:review.reviewDigest};loseResponse=true;assert.ok((await handleContactFormMigration(req(command),call)).status>=500);
 const status=await (await handleContactFormMigration(req({action:'status',site,requestKey:key}),call)).json();assert.equal(status.status,'complete');assert.equal(status.result.length,2);
 for(const result of status.result){const record=(await db.query('select cms.get_editor_record($1,$2) value',[site,result.recordId])).rows[0].value;assert.equal(record.publishedRevision,null);assert.deepEqual(record.payload,review.proposal.forms.find(f=>f.variant===result.variant).definition);}
 const first=status.result[0],second=status.result[1],edited={...review.proposal.forms[0].definition,title:'Later client edit'};
 const later=(await db.query("select cms.save_draft($1,$2,$3,'form',null,$4,$5::jsonb) value",[site,first.recordId,first.revisionId,edited.title,JSON.stringify(edited)])).rows[0].value;
 const replay=await (await handleContactFormMigration(req(command),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,status.result);
 const reject=async(work,pattern)=>{await db.exec('savepoint forms_rejected');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to savepoint forms_rejected');}};
 const manifest=status.result.map((r,i)=>({variant:r.variant,recordId:r.recordId,expectedRevision:i===0?later.revisionId:randomUUID(),payload:review.proposal.forms[i].definition})),staleKey=randomUUID();
 await reject(()=>db.query('select cms.apply_contact_form_migration($1,$2,$3,$4,$5::jsonb)',[site,staleKey,'a'.repeat(64),'b'.repeat(64),JSON.stringify(manifest)]),/revision_conflict/);
 await root();assert.equal((await db.query('select current_revision_id from cms.records where id=$1',[first.recordId])).rows[0].current_revision_id,later.revisionId);assert.equal((await db.query('select count(*)::int n from cms.contact_form_migration_batches where request_key=$1',[staleKey])).rows[0].n,0);
 await actor(reviewer);assert.equal((await db.query('select cms.get_contact_form_migration_result($1,$2) value',[site,key])).rows[0].value,null);
 await actor(editor);assert.equal((await db.query('select cms.get_contact_form_migration_result($1,$2) value',[otherSite,key])).rows[0].value,null);
 const originalManifest=targets.map((t,i)=>({...t,payload:review.proposal.forms[i].definition}));
 await reject(()=>db.query('select cms.apply_contact_form_migration($1,$2,$3,$4,$5::jsonb)',[site,key,'c'.repeat(64),review.reviewDigest,JSON.stringify(originalManifest)]),/idempotency_key_reused/);
 await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,editor]);await actor(editor);await reject(()=>db.query('select cms.get_contact_form_migration_result($1,$2)',[site,key]),/forbidden/);await reject(()=>db.query('select cms.apply_contact_form_migration($1,$2,$3,$4,$5::jsonb)',[site,key,review.sourceDigest,review.reviewDigest,JSON.stringify(originalManifest)]),/forbidden/);
 }finally{await db.exec('rollback');await root();}
});

test('Concept page-owned menu saves and restores with its revision without changing homepage records',async()=>{
 await root();await db.exec('begin');try{
 const {planConceptNavigationMigration,conceptNavigationDependencies}=await import('../lib/cms/concept-navigation-migration.ts');const navigation=planConceptNavigationMigration(conceptNavigationDependencies).navigation;
 const homeBefore=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' order by id",[site])).rows;
 const existing=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and content_type='page' and path='/concept' and locale='en'",[site])).rows[0];
 const payload={composition:{schemaVersion:1,title:'Concept draft',sections:[]},navigation};await actor(editor);
 const first=(await db.query("select cms.save_draft($1,$2,$3,'page','/concept','Concept draft',$4::jsonb) value",[site,existing?.id??null,existing?.current_revision_id??null,JSON.stringify(payload)])).rows[0].value;
 const changed=structuredClone(payload);changed.navigation.primary.reverse();changed.navigation.contextLabel='A new Concept context';
 const second=(await db.query("select cms.save_draft($1,$2,$3,'page','/concept','Concept draft',$4::jsonb) value",[site,first.recordId,first.revisionId,JSON.stringify(changed)])).rows[0].value;
 assert.deepEqual((await db.query('select cms.get_editor_record($1,$2) value',[site,first.recordId])).rows[0].value.payload.navigation,changed.navigation);
 await db.query('select cms.restore_draft($1,$2,$3,$4)',[site,first.recordId,first.revisionId,second.revisionId]);const restored=(await db.query('select cms.get_editor_record($1,$2) value',[site,first.recordId])).rows[0].value;assert.deepEqual(restored.payload.navigation,navigation);assert.notEqual(restored.currentRevision,first.revisionId);
 await root();assert.deepEqual((await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' order by id",[site])).rows,homeBefore);
 }finally{await db.exec('rollback');await root();}
});

test('Concept migration atomically checks image/video provenance and record revisions, then recovers without overwriting later drafts',async()=>{
 await root();await db.exec('begin');
 try{
  const homepageBefore=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0];
  await actor(editor);const initial=(await db.query("select cms.save_draft($1,null,null,'page','/concept','Concept',$2::jsonb) value",[site,JSON.stringify({composition:{schemaVersion:1,title:'Concept',sections:[]}})])).rows[0].value;
  await root();const home=(await db.query('select id,current_revision_id,published_revision_id from cms.records where id=$1',[initial.recordId])).rows[0];
  const bindings=[];
  for(const kind of ['image','video']){
   const id=randomUUID(),video=kind==='video',source=(video?'b':'a').repeat(64);bindings.push({kind,assetId:id,sourceSha256:source});
   await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,$5,$6,100,$7,'ready',$8,$9)",[id,site,editor,randomUUID(),video?'source.mp4':'source.jpg',video?'video/mp4':'image/jpeg',`${site}/${id}/original`,source,video?'hero-video-1':'image-1']);
   await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,$5,100,80,40,'ready','approved','Fixture rights',$6,$7,$8,$9,$10)",[site,id,`${site}/${id}/delivery.${video?'mp4':'webp'}`,'d'.repeat(64),video?'video/mp4':'image/webp',video?10:null,video?30:null,video?false:null,video?'h264':null,video?'yuv420p':null]);
  }
  await actor(editor);const trip=await save('/journeys/concept-migration-source',null,null,{title:'Migration source journey'});
  const evidence=[];for(const {kind,...binding}of bindings)evidence.push(...(await db.query(`select cms.${kind==='video'?'review_hero_video_migration_media':'review_about_migration_media'}($1,$2::jsonb) value`,[site,JSON.stringify([binding])])).rows[0].value);
  assert.ok(evidence.every(e=>e.available));
  const payload={navigation:{schemaVersion:1,primary:[{id:'menu-one',image:{assetId:bindings[0].assetId,alt:'Menu forest'}}]},composition:{schemaVersion:1,title:'Migrated Concept draft',sections:[{id:'hero',kind:'homepageHero',controls:{label:'Hero'},data:{poster:{assetId:bindings[0].assetId,alt:'Forest'},background:{kind:'video',desktopAssetId:bindings[1].assetId}}},{id:'journeys',kind:'homepageJourneys',controls:{label:'Journeys'},data:{items:[{recordId:trip.recordId}]}}]}};
  const manifest={recordId:home.id,expectedRevision:home.current_revision_id,payload,bindings,evidence,records:[{recordId:trip.recordId,revisionId:trip.revisionId,type:'journey',path:'/journeys/concept-migration-source'}]},key=randomUUID(),source='a'.repeat(64),reviewDigest='b'.repeat(64);
  const apply=async(request=key,value=manifest,website=site)=>(await db.query('select cms.apply_concept_migration($1,$2,$3,$4,$5::jsonb) value',[website,request,source,reviewDigest,JSON.stringify(value)])).rows[0].value;
  const rejected=async(work,pattern)=>{await db.exec('savepoint rejected_migration');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to savepoint rejected_migration');}};
  const result=await apply();assert.equal(result.recordId,home.id);assert.notEqual(result.revisionId,home.current_revision_id);assert.deepEqual(await apply(),result);
  const status=async()=> (await db.query('select cms.get_concept_migration_result($1,$2) value',[site,key])).rows[0].value;
  assert.deepEqual((await status()).result,result);await actor(reviewer);assert.equal(await status(),null);await actor(editor);
  await rejected(()=>apply(key,{...manifest,payload:{...payload,changed:true}}),/idempotency_key_reused/);
  const later=(await db.query("select cms.save_draft($1,$2,$3,'page','/concept','Later draft',$4::jsonb) value",[site,home.id,result.revisionId,JSON.stringify({...payload,later:true})])).rows[0].value;
  await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,bindings[1].assetId]);await actor(editor);assert.deepEqual(await apply(),result);
  const fresh={...manifest,expectedRevision:later.revisionId},failedKey=randomUUID();await rejected(()=>apply(failedKey,fresh),/migration_media_unavailable/);
  await root();assert.equal((await db.query('select count(*)::int n from cms.concept_migration_batches where request_key=$1',[failedKey])).rows[0].n,0);let state=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[home.id])).rows[0];assert.equal(state.current_revision_id,later.revisionId);assert.equal(state.published_revision_id,home.published_revision_id);
  await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,bindings[1].assetId]);await actor(editor);
  const newTrip=await save('/journeys/concept-migration-source',trip.recordId,trip.revisionId,{title:'Changed source'});await rejected(()=>apply(randomUUID(),fresh),/migration_reference_changed/);
  const current={...fresh,records:[{...fresh.records[0],revisionId:newTrip.revisionId}]};await rejected(()=>apply(randomUUID(),{...current,evidence:current.evidence.map(e=>({...e,revision:999}))}),/migration_media_changed/);
  await rejected(()=>apply(randomUUID(),{...current,records:[]}),/migration_reference_mismatch/);
  await rejected(()=>apply(randomUUID(),{...current,payload:{...payload,navigation:{...payload.navigation,primary:[{image:{assetId:'unmapped'}}]}}}),/migration_media_mismatch/);
  await rejected(()=>apply(randomUUID(),{...current,payload:{composition:payload.composition}}),/invalid_migration_manifest/);
  await rejected(()=>apply(randomUUID(),current,otherSite),/forbidden/);
  await root();assert.deepEqual((await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0],homepageBefore);
  await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,editor]);await actor(editor);await rejected(()=>apply(),/forbidden/);
  await actor(outsider);await rejected(()=>apply(randomUUID(),current),/forbidden/);
 }finally{await db.exec('rollback');await root();}
});

test('concept HTTP review and apply use full captured mappings and recover a lost result through actual database receipts',async()=>{
 await root();await db.exec('begin');
 try{
  const {handleConceptMigrationReview}=await import('../lib/cms/concept-migration-api.ts'),{makeConceptMigrationFixture}=await import('./fixtures/cms-concept-migration.mjs');
  const fixture=makeConceptMigrationFixture(),mappedMedia=new Map();
  for(const binding of fixture.mappings.media){
   const previous=binding.assetId,id=randomUUID(),video=binding.sourcePath.endsWith('.mp4');binding.assetId=id;mappedMedia.set(previous,id);
   await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,$5,$6,100,$7,'ready',$8,$9)",[id,site,editor,randomUUID(),video?'source.mp4':'source.jpg',video?'video/mp4':'image/jpeg',`${site}/${id}/original`,binding.sourceSha256,video?'hero-video-1':'image-1']);
   await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,$5,100,80,40,'ready','approved','Fixture rights',$6,$7,$8,$9,$10)",[site,id,`${site}/${id}/delivery.${video?'mp4':'webp'}`,'d'.repeat(64),video?'video/mp4':'image/webp',video?10:null,video?30:null,video?false:null,video?'h264':null,video?'yuv420p':null]);
  }
  function replaceMedia(value){if(!value||typeof value!=='object')return;for(const [key,item]of Object.entries(value)){if(key==='assetId'&&mappedMedia.has(item))value[key]=mappedMedia.get(item);else replaceMedia(item);}}
  for(const record of fixture.records){
   replaceMedia(record.payload);await root();const existing=record.path?(await db.query('select id,current_revision_id from cms.records where website_id=$1 and path=$2 and locale=\'en\'',[site,record.path])).rows[0]:null;
   await actor(editor);const saved=(await db.query('select cms.save_draft($1,$2,$3,$4,$5,$6,$7::jsonb) value',[site,existing?.id??null,existing?.current_revision_id??null,record.type,record.path,'Concept mapped source',JSON.stringify(record.payload)])).rows[0].value;
   fixture.mappings.records.find(item=>item.recordId===record.id).recordId=saved.recordId;
  }
  await root();const homepageBefore=(await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0];await actor(editor);
  let loseResponse=false;const calls=[];const call=async(token,name,args)=>{
   assert.equal(token,'test.editor.token');calls.push(name);const entries=Object.entries(args),values=entries.map(([,v])=>v&&typeof v==='object'?JSON.stringify(v):v);
   const value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key}=>$${i+1}`).join(',')}) value`,values)).rows[0].value;
   if(name==='apply_concept_migration'&&loseResponse){loseResponse=false;throw Error('Response lost after draft save');}return value;
  };
  const request=body=>new Request('https://cms.test/api/cms/migrations/concept',{method:'POST',headers:{authorization:'Bearer test.editor.token','content-type':'application/json'},body:JSON.stringify(body)});
  const selection={site,recordId:null,expectedRevision:null,mappings:fixture.mappings};
  const response=await handleConceptMigrationReview(request({action:'review',...selection}),call);assert.equal(response.status,200);const reviewed=await response.json();assert.equal(reviewed.applyAvailable,true,JSON.stringify(reviewed.recordComparison.findings));
  const command={action:'apply',...selection,requestKey:randomUUID(),reviewDigest:reviewed.reviewDigest,evidence:{recordComparison:reviewed.recordComparison,mediaVerification:reviewed.mediaVerification}};
  loseResponse=true;assert.equal((await handleConceptMigrationReview(request(command),call)).status,500);
  const status=await (await handleConceptMigrationReview(request({action:'status',site,requestKey:command.requestKey}),call)).json();assert.equal(status.status,'complete');
  const saved=status.result;assert.match(saved.recordId,/^[a-f0-9-]{36}$/);
  const newer=(await db.query("select cms.save_draft($1,$2,$3,'page','/concept','Later client edit',$4::jsonb) value",[site,saved.recordId,saved.revisionId,JSON.stringify({...reviewed.proposal,composition:{...reviewed.proposal.composition,title:'Later client edit'}})])).rows[0].value;
  calls.length=0;const retry=await handleConceptMigrationReview(request(command),call);assert.equal(retry.status,200);const replay=await retry.json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,saved);assert.deepEqual(calls,['get_concept_migration_result','apply_concept_migration']);
  await root();const state=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[saved.recordId])).rows[0];assert.equal(state.current_revision_id,newer.revisionId);assert.equal(state.published_revision_id,null);
  const stored=(await db.query('select payload from cms.revisions where id=$1',[saved.revisionId])).rows[0].payload;assert.equal(stored.composition.sections.length,10);assert.deepEqual(stored,reviewed.proposal);assert.equal(stored.navigation.primary.length,6);
  assert.deepEqual((await db.query("select id,current_revision_id,published_revision_id from cms.records where website_id=$1 and content_type='homepage' and locale='en'",[site])).rows[0],homepageBefore);
 }finally{await db.exec('rollback');await root();}
});
