  await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await db.query('update cms.validations set valid=false where revision_id=$1',[saved.revisionId]);await actor(null,'anon');assert.equal(await get(),null);
  await root();await db.query('update cms.validations set valid=true where revision_id=$1',[saved.revisionId]);await db.query('update cms.records set published_revision_id=null where id=$1',[saved.recordId]);await actor(null,'anon');assert.equal(await get(),null);
