  payload.composition.sections.push({...structuredClone(payload.composition.sections[1]),id:'future-copy',controls:{...payload.composition.sections[1].controls,visibleFrom:'2099-01-01T00:00:00Z'},data:{privateNotes:'PRIVATE_FUTURE'}});
