test('Bespoke completes trusted review publication restore and withdrawal without bypassing release guards',async()=>{
 await root();await db.exec('begin');try{
  const {planGuidedSafarisMigration,guidedMigrationDependencies}=await import('../lib/cms/guided-safaris-migration.ts');
  const payload=structuredClone(planGuidedSafarisMigration(guidedMigrationDependencies).previewPayload),ids=new Set();
  for(const [id,controls]of [['hidden-encounter',{visible:false}],['future-encounter',{visibleFrom:'2099-01-01T00:00:00Z'}]]){const section=structuredClone(payload.composition.sections[2]);section.id=id;section.controls={...section.controls,...controls};section.data.media.image.assetId=id;section.data.accessibleLabel='Unreleased '+id;payload.composition.sections.push(section);}
  function collect(value){if(!value||typeof value!=='object')return;for(const [key,item]of Object.entries(value))if(key==='assetId')ids.add(item);else collect(item);}collect(payload);
  for(const asset of ids)await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Fixture rights')",[site,asset,`${site}/${asset}/delivery.webp`,'a'.repeat(64)]);
  const image=[...ids][0];
  const savePage=async(previous,body)=>{await actor(editor);return (await db.query("select cms.save_draft($1,$2,$3,'page','/guided-bespoke-safaris','Bespoke',$4::jsonb) value",[site,previous?.recordId??null,previous?.revisionId??null,JSON.stringify(body)])).rows[0].value;};
  const check=async record=>{await actor(null,'service_role');return runTrustedValidation(async(name,args)=>name==='get_validation_input'?(await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value:db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]),{site,record:record.recordId,revision:record.revisionId});};
  const approve=async record=>{await actor(editor);await review(record,'submit');await actor(reviewer);await review(record,'approve');};
  const live=async()=>{await actor(null,'anon');return (await db.query("select cms.get_public_guided($1,'en') value",[site])).rows[0].value;};
  const rejects=async(work,pattern)=>{await db.exec('savepoint guided_release_rejected');try{await assert.rejects(work,pattern);}finally{await db.exec('rollback to guided_release_rejected');}};
  const first=await savePage(null,payload),checked=await check(first);assert.equal(checked.contentChecksPass,true,JSON.stringify(checked.findings));await approve(first);await actor(publisher);await publish(first);assert.equal((await live()).revisionId,first.revisionId);assert.equal((await live()).payload.composition.sections.length,8);assert.doesNotMatch(JSON.stringify(await live()),/Unreleased/);for(const hidden of ['hidden-encounter','future-encounter'])assert.equal((await db.query('select cms.get_public_media($1,$2) value',[site,hidden])).rows[0].value,null);assert.equal((await db.query('select cms.get_public_media($1,$2) value',[site,image])).rows[0].value!==null,true);assert.deepEqual((await db.query("select cms.get_public_page($1,'/guided-bespoke-safaris','en') value",[site])).rows[0].value.payload,(await live()).payload);
  const changed=structuredClone(payload);changed.composition.sections[1].data.paragraphs[0].text='Revised published introduction.';const second=await savePage(first,changed);assert.equal((await live()).revisionId,first.revisionId);assert.equal((await check(second)).contentChecksPass,true);await approve(second);
  await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,image]);await actor(publisher);await rejects(()=>publish(second),/media_verification_required/);assert.equal(await live(),null);
  await root();assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[first.recordId])).rows[0].published_revision_id,first.revisionId);await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,image]);await actor(publisher);await publish(second);assert.equal((await live()).revisionId,second.revisionId);
  await actor(editor);const restored=(await db.query('select cms.restore_draft($1,$2,$3,$4) value',[site,first.recordId,first.revisionId,second.revisionId])).rows[0].value;assert.notEqual(restored.revisionId,first.revisionId);assert.equal((await live()).revisionId,second.revisionId);assert.equal((await check(restored)).contentChecksPass,true);await approve(restored);await actor(publisher);await publish(restored);assert.equal((await live()).payload.composition.sections[1].data.paragraphs[0].text,payload.composition.sections[1].data.paragraphs[0].text);
  await root();await rejects(()=>db.query("update cms.records set path='/guided-moved' where id=$1",[first.recordId]),/guided_route_not_ready/);
  const invalid=structuredClone(payload);invalid.composition.sections.push({id:'unsupported',kind:'text',controls:{label:'Unsupported'},data:{body:[]}});const bad=await savePage(restored,invalid);assert.equal((await check(bad)).contentChecksPass,false);await approve(bad);await actor(null,'service_role');await receipt(bad,'composition-5',true);await actor(publisher);await rejects(()=>publish(bad),/guided_page_section_unsupported/);
  await db.query('select cms.unpublish($1,$2,$3)',[site,restored.recordId,restored.revisionId]);assert.equal(await live(),null);assert.equal((await db.query('select cms.get_public_media($1,$2) value',[site,image])).rows[0].value,null);
 }finally{await db.exec('rollback');await root();}
});


test('Aviation mixed media review binds four images and one silent video to current tenant evidence',async()=>{
 await root();await db.exec('begin');try{
 const reject=async(work,pattern)=>{await db.exec('savepoint aviation_media_reject');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to aviation_media_reject');}};
 const bindings=[];
 for(let i=0;i<5;i++){const id=randomUUID(),video=i===4,source=String(i).repeat(64);bindings.push({kind:video?'video':'image',assetId:id,sourceSha256:source});
 await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,'fixture',$5,100,$6,'ready',$7,$8)",[id,site,editor,randomUUID(),video?'video/mp4':'image/jpeg',`${site}/${id}/original`,source,video?'hero-video-1':'image-1']);
 await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,$5,100,1280,720,'ready','approved','PRIVATE_AVIATION_RIGHTS',$6,$7,$8,$9,$10)",[site,id,`${site}/${id}/delivery.${video?'mp4':'webp'}`,'d'.repeat(64),video?'video/mp4':'image/webp',video?15:null,video?30:null,video?false:null,video?'h264':null,video?'yuv420p':null]);}
 const review=async(maps=bindings,s=site)=>(await db.query('select cms.review_aviation_migration_media($1,$2::jsonb) value',[s,JSON.stringify(maps)])).rows[0].value;
 const {verifyAviationMigrationMedia}=await import('../lib/cms/aviation-migration-media.ts');await actor(editor);const initial=await review();assert.equal(verifyAviationMigrationMedia(bindings,initial).verified,true);assert.equal(JSON.stringify(initial).includes('PRIVATE_AVIATION_RIGHTS'),false);assert.equal(JSON.stringify(initial).includes('storage_key'),false);
 const wrong=structuredClone(bindings);wrong[4].sourceSha256='f'.repeat(64);assert.equal((await review(wrong))[4].available,false);
 const swapped=structuredClone(bindings);swapped[0].kind='video';swapped[4].kind='image';const kindEvidence=await review(swapped);assert.equal(kindEvidence[0].available,false);assert.equal(kindEvidence[4].available,false);
 await reject(()=>review(bindings.slice(1)),/invalid_aviation_media_bindings/);await reject(()=>review(bindings.map(b=>({...b,assetId:bindings[0].assetId}))),/invalid_aviation_media_bindings/);await reject(()=>review(bindings.map(b=>({...b,approved:true}))),/invalid_aviation_media_bindings/);
 await actor(outsider);await reject(()=>review(),/forbidden/);await actor(editor);await reject(()=>review(bindings,otherSite),/forbidden/);
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,bindings[0].assetId]);await actor(editor);assert.equal((await review())[0].available,false);
 await root();await reject(()=>db.query('update cms.media_objects set has_audio=true where website_id=$1 and id=$2',[site,bindings[4].assetId]),/media_objects_video_metadata_check/);await actor(editor);assert.equal((await review())[4].available,true);
 await root();await db.query("update cms.media_objects set has_audio=false,rights_expires_at=now()-interval '1 second' where website_id=$1 and id=$2",[site,bindings[4].assetId]);await actor(editor);assert.equal((await review())[4].available,false);
 await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,editor]);await actor(editor);await reject(()=>review(),/forbidden/);
 }finally{await db.exec('rollback');await root();}
});


test('Aviation atomic draft migration rechecks media, protects revisions and recovers immutable results',async()=>{
 await root();await db.exec('begin');try{
 const reject=async(work,pattern)=>{await db.exec('savepoint aviation_apply_reject');try{await assert.rejects(work(),pattern);}finally{await db.exec('rollback to aviation_apply_reject');}};
 const {default:inventory}=await import('../docs/cms/private-aviation-migration-inventory.json',{with:{type:'json'}});
 const {planPrivateAviationMigration,aviationMigrationDependencies}=await import('../lib/cms/private-aviation-migration.ts');
 const bindings=[],mappings=[];
 for(let i=0;i<5;i++){const id=randomUUID(),video=inventory.media[i].sourcePath.endsWith('.mp4'),source=inventory.media[i].sha256;mappings.push({sourcePath:inventory.media[i].sourcePath,sourceSha256:source,assetId:id});bindings.push({kind:video?'video':'image',assetId:id,sourceSha256:source});
 await db.query("insert into cms.uploads(id,website_id,created_by,request_key,filename,mime_type,expected_bytes,storage_key,status,original_sha256,inspection_version) values($1,$2,$3,$4,'fixture',$5,100,$6,'ready',$7,$8)",[id,site,editor,randomUUID(),video?'video/mp4':'image/jpeg',`${site}/${id}/original`,source,video?'hero-video-1':'image-1']);
 await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence,duration_seconds,frames_per_second,has_audio,video_codec,video_pixel_format) values($1,$2,$3,$4,$5,100,1280,720,'ready','approved','PRIVATE_AVIATION_RIGHTS',$6,$7,$8,$9,$10)",[site,id,`${site}/${id}/delivery.${video?'mp4':'webp'}`,'d'.repeat(64),video?'video/mp4':'image/webp',video?15:null,video?30:null,video?false:null,video?'h264':null,video?'yuv420p':null]);}
 const source='a'.repeat(64),reviewDigest='b'.repeat(64),request=randomUUID();
 const payload=planPrivateAviationMigration(aviationMigrationDependencies,mappings).previewPayload;
 const evidence=async()=>(await db.query('select cms.review_aviation_migration_media($1,$2::jsonb) value',[site,JSON.stringify(bindings)])).rows[0].value;
 await actor(editor);let manifest={recordId:null,expectedRevision:null,payload,bindings,evidence:await evidence()};
 const apply=async(value=manifest,key=request)=>(await db.query('select cms.apply_aviation_migration($1,$2,$3,$4,$5::jsonb) value',[site,key,source,reviewDigest,JSON.stringify(value)])).rows[0].value;
 const video=bindings.find(b=>b.kind==='video');await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id=$2",[site,video.assetId]);await actor(editor);await reject(()=>apply(),/migration_media_unavailable/);
 await root();assert.equal((await db.query('select count(*)::int n from cms.aviation_migration_batches where request_key=$1',[request])).rows[0].n,0);await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,video.assetId]);await actor(editor);await reject(()=>apply(),/migration_media_changed/);manifest={...manifest,evidence:await evidence()};
 const missing=structuredClone(manifest);delete missing.payload.composition.sections[0].data.media.background.desktopAssetId;await reject(()=>apply(missing),/migration_media_mismatch/);
 const wrongRole=structuredClone(manifest);wrongRole.payload.composition.sections[0].data.media.poster.assetId=video.assetId;await reject(()=>apply(wrongRole),/migration_media_mismatch/);
 const saved=await apply();assert.deepEqual(await apply(),saved);const sharedAviation=await preview(saved);const stored=(await db.query('select cms.get_editor_record($1,$2) value',[site,saved.recordId])).rows[0].value;assert.equal(stored.path,'/private-aviation');assert.equal(stored.publishedRevision,null);assert.equal(stored.payload.composition.sections.length,5);
 await actor(null,'anon');assert.equal((await db.query('select cms.get_public_aviation($1,$2) value',[site,'en'])).rows[0].value,null);assert.equal((await db.query('select cms.get_public_hero_video($1,$2) value',[site,video.assetId])).rows[0].value,null);await actor(editor);
 const later=(await db.query("select cms.save_draft($1,$2,$3,'page','/private-aviation','Later client edit',$4::jsonb,'en') value",[site,saved.recordId,saved.revisionId,JSON.stringify({...payload,composition:{...payload.composition,title:'Later client edit'}})])).rows[0].value;
 await actor(reviewer);const pinnedAviation=await getPreview(sharedAviation.previewId);assert.equal(pinnedAviation.revisionId,saved.revisionId);assert.deepEqual(pinnedAviation.payload,payload);
 assert.equal((await db.query('select cms.get_hero_video_preview($1,$2) value',[site,video.assetId])).rows[0].value.id,video.assetId);
 await actor(outsider);assert.equal(await getPreview(sharedAviation.previewId),null);assert.equal((await db.query('select cms.get_hero_video_preview($1,$2) value',[site,video.assetId])).rows[0].value,null);
 await actor(editor);await db.query('select cms.revoke_preview($1)',[sharedAviation.previewId]);await actor(reviewer);assert.equal(await getPreview(sharedAviation.previewId),null);await actor(editor);
 assert.deepEqual(await apply(),saved);await reject(()=>apply({...manifest,payload:{...payload,seo:{...payload.seo,title:'Tampered'}}}),/idempotency_key_reused/);
 await reject(()=>apply({...manifest,recordId:saved.recordId,expectedRevision:saved.revisionId},randomUUID()),/revision_conflict/);
 const updated=await apply({...manifest,recordId:saved.recordId,expectedRevision:later.revisionId},randomUUID());assert.equal(updated.recordId,saved.recordId);assert.notEqual(updated.revisionId,later.revisionId);
 const receipt=(await db.query('select cms.get_aviation_migration_result($1,$2) value',[site,request])).rows[0].value;assert.deepEqual(receipt.result,saved);await actor(reviewer);assert.equal((await db.query('select cms.get_aviation_migration_result($1,$2) value',[site,request])).rows[0].value,null);

 const {handleAviationMigrationReview}=await import('../lib/cms/aviation-migration-api.ts');
 const req=body=>new Request('http://localhost/api/cms/migrations/aviation',{method:'POST',headers:{authorization:'Bearer test.editor.token',origin:'http://localhost','content-type':'application/json'},body:JSON.stringify(body)});
 let loseResponse=false;
 const call=async(token,name,args)=>{assert.equal(token,'test.editor.token');assert.ok(['get_editor_record','review_aviation_migration_media','get_aviation_migration_result','apply_aviation_migration'].includes(name));const entries=Object.entries(args),values=entries.map(([,v])=>v&&typeof v==='object'?JSON.stringify(v):v);const value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key}=>$${i+1}`).join(',')}) value`,values)).rows[0].value;if(name==='apply_aviation_migration'&&loseResponse){loseResponse=false;throw Error('Lost completed response');}return value;};
 await actor(editor);const selection={action:'review',site,recordId:saved.recordId,expectedRevision:updated.revisionId,bindings:mappings};
 const reviewed=await (await handleAviationMigrationReview(req(selection),call)).json();assert.equal(reviewed.applyAvailable,true);assert.equal(reviewed.verification.evidence.filter(e=>e.kind==='video').length,1);assert.equal(reviewed.metadataChanges[0].proposed,'https://safaricrafters.com/private-aviation');
 const httpKey=randomUUID(),command={...selection,action:'apply',requestKey:httpKey,reviewDigest:reviewed.reviewDigest,evidence:reviewed.verification.evidence};loseResponse=true;assert.ok((await handleAviationMigrationReview(req(command),call)).status>=500);
 const status=await (await handleAviationMigrationReview(req({action:'status',site,requestKey:httpKey}),call)).json();assert.equal(status.status,'complete');
 const newest=(await db.query("select cms.save_draft($1,$2,$3,'page','/private-aviation','Client edit after lost response',$4::jsonb,'en') value",[site,saved.recordId,status.result.revisionId,JSON.stringify(reviewed.proposal)])).rows[0].value;
 const replay=await (await handleAviationMigrationReview(req(command),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,status.result);
 await actor(outsider);await reject(()=>apply(),/forbidden/);await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,editor]);await actor(editor);await reject(()=>apply(),/forbidden/);await reject(()=>db.query('select cms.get_aviation_migration_result($1,$2)',[site,request]),/forbidden/);
 await root();const final=(await db.query('select current_revision_id,published_revision_id from cms.records where id=$1',[saved.recordId])).rows[0];assert.equal(final.current_revision_id,newest.revisionId);assert.equal(final.published_revision_id,null);assert.equal((await db.query("select count(*)::int n from cms.audit_events where website_id=$1 and action='aviation_migration.applied' and details->>'recordId'=$2",[site,saved.recordId])).rows[0].n,3);
 }finally{await db.exec('rollback');await root();}
});

