test('Aviation public projection preserves approved fields and excludes private or inactive content',async()=>{
 await root();await db.exec('begin');try{
  const {planPrivateAviationMigration,aviationMigrationDependencies}=await import('../lib/cms/private-aviation-migration.ts');
  const payload=structuredClone(planPrivateAviationMigration(aviationMigrationDependencies).previewPayload),expected=structuredClone(payload);
  const inject=value=>{if(Array.isArray(value)){value.forEach(inject);return;}if(value&&typeof value==='object'){Object.values(value).forEach(inject);value.privateNotes='PRIVATE_NESTED';}};inject(payload);
  for(const section of payload.composition.sections)section.controls.label='PRIVATE_LABEL';
  for(const [id,controls]of [['hidden',{visible:false}],['future',{visibleFrom:'2099-01-01T00:00:00Z'}],['expired',{visibleUntil:'2000-01-01T00:00:00Z'}],['region',{regions:['asia']}],['locale',{locales:['fr']}]] )payload.composition.sections.push({...structuredClone(payload.composition.sections[1]),id,controls:{...payload.composition.sections[1].controls,...controls}});
  const project=async(body=payload,locale='en')=>(await db.query('select cms.project_aviation_payload($1::jsonb,$2) value',[JSON.stringify(body),locale])).rows[0].value;
  const publicPayload=await project();assert.equal(publicPayload.composition.sections.length,5);assert.doesNotMatch(JSON.stringify(publicPayload),/PRIVATE_/);
  for(let i=0;i<5;i++){assert.deepEqual(publicPayload.composition.sections[i].data,expected.composition.sections[i].data);assert.equal(publicPayload.composition.sections[i].controls.label,expected.composition.sections[i].kind);}
  assert.deepEqual(publicPayload.seo,expected.seo);
  const {projectPrivateAviationPage}=await import('../lib/cms/private-aviation-page.ts');const id=randomUUID();assert.equal(projectPrivateAviationPage({recordId:id,revisionId:id,type:'page',payload:publicPayload},{locale:'en',now:new Date()}).sections.length,5);
  const imageOnly=structuredClone(payload);imageOnly.composition.sections[0].data.media.background.kind='image';assert.deepEqual((await project(imageOnly)).composition.sections[0].data.media.background,{kind:'image'});
  const malformed=structuredClone(payload);malformed.composition.sections[0].data.copy={privateNotes:'PRIVATE_SCALAR'};assert.doesNotMatch(JSON.stringify(await project(malformed)),/PRIVATE_/);
  const unknown=structuredClone(payload);unknown.composition.sections[0].kind='unreviewed';assert.equal(await project(unknown),null);assert.equal(await project(payload,'fr'),null);assert.equal(await project({}),null);
  await actor(editor);await db.query("select cms.save_draft($1,null,null,'page','/private-aviation','Private draft',$2::jsonb,'en')",[site,JSON.stringify(payload)]);
  await actor(null,'anon');for(const [s,l]of [[site,'en'],[otherSite,'en'],[site,'fr']])assert.equal((await db.query('select cms.get_public_aviation($1,$2) value',[s,l])).rows[0].value,null);
  await db.exec('savepoint private_projector');await assert.rejects(db.query('select cms.project_aviation_payload($1::jsonb,$2)',[JSON.stringify(payload),'en']),/permission denied/);await db.exec('rollback to private_projector');
 }finally{await db.exec('rollback');await root();}
});

