 const rpc=async(name,args)=>{
  const entries=Object.entries(args);const sql=`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) result`;
  return (await db.query(sql,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].result;
 };
