assert.doesNotMatch(JSON.stringify(await publicRead()),/unpublished-title-marker/);
  await root();await db.exec('savepoint mice_public_incompatible_form');await actor(editor);const brokenForm={...definition,fields:definition.fields.filter(f=>f.id!=='phone')};const brokenSaved=(await db.query("select cms.save_draft($1,$2,$3,'form',null,'Changed corporate mapping',$4::jsonb) value",[site,form.recordId,form.revisionId,JSON.stringify(brokenForm)])).rows[0].value;await root();await db.query('update cms.records set published_revision_id=$2 where id=$1',[form.recordId,brokenSaved.revisionId]);assert.equal(await publicRead(),null);await root();await db.exec('rollback to savepoint mice_public_incompatible_form');

