test('MICE published-form compatibility rejects changed corporate mappings without exposing definitions',async()=>{
 await root();await db.exec('begin');try{
  const {planContactFormMigration}=await import('../lib/cms/contact-form-migration.ts');const {contactMigrationDependencies}=await import('../lib/cms/contact-migration.ts');
  const {validateMiceFormCompatibility}=await import('../lib/cms/mice-form-resolution.ts');
  const definition=planContactFormMigration(contactMigrationDependencies).forms.find(f=>f.variant==='corporate').definition;
  const check=async(d)=>(await db.query('select cms.mice_form_compatible($1::jsonb) value',[JSON.stringify(d)])).rows[0].value;
  assert.equal(await check(definition),true);
  const cases=[null,{}, {...definition,fields:null},{...definition,notificationRouteIds:[randomUUID()]}, {...definition,fields:[...definition.fields,definition.fields[0]]}];
  for(const id of ['name','email','phone','company','destination','message','consent']){
   cases.push({...definition,fields:definition.fields.filter(f=>f.id!==id)});
   for(const patch of [{required:null},{type:'text'},{showWhen:{fieldId:'destination',optionId:'destination-1'}}])cases.push({...definition,fields:definition.fields.map(f=>f.id===id?{...f,...patch}:f)});
  }
  for(const patch of [{defaultOptionId:'missing'},{defaultOptionId:null},{options:null},{options:[]}])cases.push({...definition,fields:definition.fields.map(f=>f.id==='destination'?{...f,...patch}:f)});
  cases.push({...definition,fields:definition.fields.map(f=>f.id==='consent'?{...f,purpose:'marketing'}:f)});
  for(const bad of cases){assert.equal(validateMiceFormCompatibility(bad).contentChecksPass,false);assert.equal(await check(bad),false);}
  const editable=structuredClone(definition);editable.fields[0].label='Your full name';assert.equal(await check(editable),true);
  await actor(editor);const form=(await db.query("select cms.save_draft($1,null,null,'form',null,'Corporate',$2::jsonb) value",[site,JSON.stringify(definition)])).rows[0].value;
  const read=async()=>(await db.query('select cms.review_mice_migration_form($1,$2) value',[site,form.recordId])).rows[0].value;
  assert.equal((await read()).available,false);
  await root();await db.query('update cms.records set published_revision_id=$2 where id=$1',[form.recordId,form.revisionId]);await actor(editor);assert.equal((await read()).available,true);
  const changed={...definition,notificationRouteIds:[randomUUID()]};const next=(await db.query("select cms.save_draft($1,$2,$3,'form',null,'Corporate',$4::jsonb) value",[site,form.recordId,form.revisionId,JSON.stringify(changed)])).rows[0].value;
  assert.equal((await read()).revisionId,form.revisionId); // A draft must not replace the published binding.
  await root();await db.query('update cms.records set published_revision_id=$2 where id=$1',[form.recordId,next.revisionId]);await actor(editor);
  // Delivery-ineligible published forms are now absent from the shared public source.
  assert.deepEqual(await read(),{recordId:form.recordId,revisionId:null,locale:null,available:false});
 }finally{await db.exec('rollback');await root();}
});


test('record usage distinguishes current/published references and respects source and target access',async()=>{
 await root();await db.exec('begin');try{
  await actor(editor);const target=await save('/journeys/usage-target'),source=await save('/journeys/usage-source',null,null,{related:{recordId:target.recordId}});
  const call=async(record=target.recordId,revision=target.revisionId,after=null)=>(await db.query('select cms.record_reference_usage($1,$2,$3,$4) value',[site,record,revision,after])).rows[0].value;
  let result=await call();assert.equal(result.items.length,1);assert.equal(result.items[0].recordId,source.recordId);assert.equal(result.items[0].draft,true);assert.equal(result.items[0].published,false);
  await review(source,'submit');await actor(reviewer);await review(source,'approve');await validate(source);await actor(publisher);await publish(source);
  await actor(editor);await save('/journeys/usage-source',source.recordId,source.revisionId,{title:'Reference removed from draft'});
  result=await call();assert.equal(result.items[0].draft,false);assert.equal(result.items[0].published,true);assert.deepEqual((await call(target.recordId,target.revisionId,source.recordId)).items,[]);
  const rejected=async(work,pattern)=>{await db.exec('savepoint usage_rejected');try{await assert.rejects(work,pattern);}finally{await db.exec('rollback to savepoint usage_rejected');}};
  await rejected(()=>call(target.recordId,randomUUID()),/revision_conflict/);await rejected(()=>call(randomUUID()),/forbidden/);
  await rejected(()=>db.query('select cms.record_reference_usage($1,$2,$3)',[otherSite,target.recordId,target.revisionId]),/forbidden/);
  await actor(null,'anon');await rejected(()=>call(),/permission denied/);await actor(editor);
  for(let i=0;i<51;i++)await save('/journeys/usage-page-'+i,null,null,{related:{recordId:target.recordId.toUpperCase()}});
  const firstPage=await call();assert.equal(firstPage.items.length,50);assert.equal(firstPage.nextCursor,firstPage.items.at(-1).recordId);const lastPage=await call(target.recordId,target.revisionId,firstPage.nextCursor);assert.equal(lastPage.items.length,2);assert.equal(lastPage.nextCursor,null);assert.equal(new Set([...firstPage.items,...lastPage.items].map(r=>r.recordId)).size,52);
  await root();await db.query("update cms.permissions set content_type='journey',record_id=$1 where role_id=$2 and action='view'",[target.recordId,editorRole]);await actor(editor);assert.deepEqual((await call()).items,[]);
  await root();await db.query("update cms.permissions set record_id=$1 where role_id=$2 and action='view'",[source.recordId,editorRole]);await actor(editor);await assert.rejects(()=>call(),/forbidden/);await db.exec('rollback');
 }catch(e){await db.exec('rollback');throw e;}finally{await root();}
});


test('page moves preserve URLs/content, reject cycles/conflicts and recover exact requests',async()=>{
 await root();await db.exec('begin');try{
  await actor(editor);const page=async(path,locale='en')=>(await db.query("select cms.save_draft($1,null,null,'page',$2,'Hierarchy page',$3::jsonb,$4) value",[site,path,JSON.stringify({composition:{schemaVersion:1,title:'Hierarchy page',sections:[]}}),locale])).rows[0].value;
  const a=await page('/hierarchy-a'),b=await page('/hierarchy-b'),c=await page('/hierarchy-c'),fr=await page('/hierarchy-fr','fr');
  const read=async(r)=>(await db.query('select cms.get_page_hierarchy($1,$2) value',[site,r.recordId])).rows[0].value;
  const move=async(r,parent,version=0,key=randomUUID())=>(await db.query('select cms.move_page($1,$2,$3,$4,$5,$6) value',[site,r.recordId,r.revisionId,version,parent,key])).rows[0].value;
  const fail=async(work,pattern)=>{await db.exec('savepoint move_rejected');try{await assert.rejects(work,pattern);}finally{await db.exec('rollback to savepoint move_rejected');}};
  const cancel=async(r,parent,version,key)=>(await db.query('select cms.cancel_page_move($1,$2,$3,$4,$5,$6) value',[site,r.recordId,r.revisionId,version,parent,key])).rows[0].value;
  const cancelledKey=randomUUID();const cancelled=await cancel(a,b.recordId,0,cancelledKey);assert.equal(cancelled.status,'cancelled');assert.deepEqual(await cancel(a,b.recordId,0,cancelledKey),cancelled);await fail(()=>move(a,b.recordId,0,cancelledKey),/page_move_cancelled/);await fail(()=>cancel(a,c.recordId,0,cancelledKey),/page_move_request_mismatch/);
  assert.equal((await read(a)).version,0);const key=randomUUID(),moved=await move(b,a.recordId,0,key);assert.equal(moved.version,1);assert.deepEqual(await move(b,a.recordId,0,key),moved);assert.deepEqual(await cancel(b,a.recordId,0,key),{status:'completed',result:moved});
  await fail(()=>move(b,c.recordId,0,key),/page_move_request_mismatch/);await fail(()=>move(b,c.recordId,0),/revision_conflict/);await fail(()=>move({...b,revisionId:randomUUID()},c.recordId,1),/revision_conflict/);
  const parents=async(r,after=null)=>(await db.query('select cms.list_page_parents($1,$2,$3) value',[site,r.recordId,after])).rows[0].value;
  await move(c,b.recordId);const eligible=await parents(a);assert.equal(eligible.recordId,a.recordId);assert.equal(eligible.revisionId,a.revisionId);assert.ok(!eligible.items.some(p=>[a.recordId,b.recordId,c.recordId,fr.recordId].includes(p.id)));assert.ok((await parents(c)).items.some(p=>p.id===b.recordId));await fail(()=>move(a,c.recordId),/page_hierarchy_cycle/);await fail(()=>move(a,a.recordId),/page_hierarchy_cycle/);await fail(()=>move(a,fr.recordId),/page_parent_unavailable/);await fail(()=>move(a,randomUUID()),/page_parent_unavailable/);
  assert.equal((await read(b)).path,'/hierarchy-b');assert.equal((await read(b)).revisionId,b.revisionId);assert.equal((await read(b)).parentId,a.recordId);
  const rootMove=await move(b,null,1);assert.equal(rootMove.version,2);assert.deepEqual(await move(b,a.recordId,0,key),moved);assert.equal((await read(b)).parentId,null);
  await actor(publisher);await fail(()=>move(a,null),/forbidden/);await fail(()=>cancel(a,null,0,randomUUID()),/forbidden/);await actor(null,'anon');await fail(()=>read(a),/permission denied/);await actor(editor);
  const journey=await save('/journeys/hierarchy-nonpage');await fail(()=>move(a,journey.recordId),/page_parent_unavailable/);await fail(()=>move(journey,null),/forbidden/);
  await root();const foreign=randomUUID();await db.query("insert into cms.records(id,website_id,content_type,path,internal_title,owner_id) values($1,$2,'page','/foreign-parent','Foreign parent',$3)",[foreign,otherSite,editor]);await actor(editor);await fail(()=>move(a,foreign),/page_parent_unavailable/);
  await root();let deep=null;for(let i=0;i<100;i++){const node=randomUUID();await db.query("insert into cms.records(id,website_id,content_type,path,internal_title,owner_id) values($1,$2,'page',$3,'Depth fixture',$4)",[node,site,'/hierarchy-depth-'+i,editor]);if(deep)await db.query('insert into cms.page_hierarchy(website_id,record_id,parent_id) values($1,$2,$3)',[site,node,deep]);deep=node;}
  await actor(editor);await fail(()=>move(b,deep,2),/page_hierarchy_depth/);assert.equal((await read(b)).version,2);
  await move(b,a.recordId,2);await root();await db.query("update cms.permissions set content_type='page',record_id=$1 where role_id=$2 and action in ('view','edit')",[b.recordId,editorRole]);await actor(editor);
  assert.deepEqual((await parents(b)).items,[]);const restricted=await read(b);assert.equal(restricted.parentRestricted,true);assert.equal(restricted.parentId,null);assert.equal(restricted.parentTitle,null);await fail(()=>move(b,null,3),/page_parent_unavailable/);
  await root();assert.equal((await db.query("select count(*)::int n from cms.audit_events where action='page.moved' and record_id=$1",[b.recordId])).rows[0].n,3);
 }finally{await db.exec('rollback');await root();}
});


