test('page sibling order is atomic, scope-bound, permission checked and safely replayable',async()=>{
 await root();await db.exec('begin');try{
  await actor(editor);const create=async path=>(await db.query("select cms.save_draft($1,null,null,'page',$2,'Order page',$3::jsonb,'en') value",[site,path,JSON.stringify({composition:{schemaVersion:1,title:'Order page',sections:[]}})])).rows[0].value;
  const parent=await create('/order-parent'),a=await create('/order-a'),b=await create('/order-b');
  for(const page of [a,b])await db.query('select cms.move_page($1,$2,$3,0,$4,$5)',[site,page.recordId,page.revisionId,parent.recordId,randomUUID()]);
  const read=async(p=parent.recordId,s=site)=>(await db.query("select cms.get_page_sibling_order($1,'en',$2) value",[s,p])).rows[0].value;
  const write=async(snapshot,ids,key=randomUUID())=>(await db.query("select cms.set_page_sibling_order($1,'en',$2,$3,$4::uuid[],$5) value",[site,parent.recordId,snapshot,ids,key])).rows[0].value;
  const initial=await read(),ids=initial.items.map(item=>item.id).reverse(),key=randomUUID();
  const saved=await write(initial.snapshot,ids,key);assert.equal(saved.version,1);assert.deepEqual((await read()).items.map(item=>item.id),ids);assert.deepEqual(await write(initial.snapshot,ids,key),saved);
  await mfaReject(()=>write(initial.snapshot,ids),/page_order_changed/);await mfaReject(()=>write(initial.snapshot,ids.slice(1),key),/request_mismatch/);
  let state=await read();await mfaReject(()=>write(state.snapshot,[a.recordId,a.recordId]),/invalid_page_order/);await mfaReject(()=>write(state.snapshot,[a.recordId,randomUUID()]),/members_changed/);
  const second=await write(state.snapshot,ids.slice().reverse());assert.equal(second.version,2);assert.deepEqual(await write(initial.snapshot,ids,key),saved);assert.notEqual((await read()).snapshot,initial.snapshot);
  state=await read();await db.query('select cms.move_page($1,$2,$3,1,null,$4)',[site,a.recordId,a.revisionId,randomUUID()]);await mfaReject(()=>write(state.snapshot,ids),/page_order_changed/);
  assert.equal((await db.query('select path from cms.records where id=$1',[b.recordId])).rows[0].path,'/order-b');
  await mfaReject(()=>read(parent.recordId,otherSite),/forbidden/);await actor(publisher);await mfaReject(()=>read(),/page_order_unavailable/);
  await actor(null,'anon');await mfaReject(()=>read(),/permission denied/);
  await root();await db.query("update cms.permissions set content_type='page',record_id=$1 where role_id=$2 and action='edit'",[parent.recordId,editorRole]);await actor(editor);await mfaReject(()=>read(),/page_order_unavailable/);
  await mfaReject(()=>db.query('select * from cms.page_branch_orders'),/permission denied/);
  await root();assert.equal((await db.query("select count(*)::int n from cms.audit_events where website_id=$1 and action='page.order_changed'",[site])).rows[0].n,2);
 }finally{await db.exec('rollback');await root();}
});

