  await actor(null,'anon');const delivered=await readPublic();assert.equal(delivered.revisionId,delivery.revisionId);assert.equal(delivered.payload.composition.sections.length,10);assert.equal(await readPublic(otherSite),null);assert.equal(await readPublic(site,'fr'),null);
  assert.equal((await db.query('select cms.get_public_media($1,$2) value',[site,bindings[0].assetId])).rows[0].value.id,bindings[0].assetId);
  assert.deepEqual((await db.query("select cms.get_public_page($1,'/destinations/kenya','en') value",[site])).rows[0].value.payload,delivered.payload);
  await root();await db.exec('savepoint kenya_public_media');await db.query("update cms.media_objects set rights_status='revoked' where id=$1",[bindings[0].assetId]);await actor(null,'anon');assert.equal(await readPublic(),null);assert.equal((await db.query('select cms.get_public_media($1,$2) value',[site,bindings[1].assetId])).rows[0].value,null,'No image access through an ineligible Kenya page');await root();await db.exec('rollback to savepoint kenya_public_media');
  await db.exec('savepoint kenya_public_route');await db.query("delete from cms.navigation_public_paths where path='/plan'");await actor(null,'anon');assert.equal(await readPublic(),null);await root();await db.exec('rollback to savepoint kenya_public_route');
  await db.exec('savepoint kenya_public_receipt');await db.query('update cms.validations set valid=false where revision_id=$1',[delivery.revisionId]);await actor(null,'anon');assert.equal(await readPublic(),null);await root();await db.exec('rollback to savepoint kenya_public_receipt');
