  const http=body=>handleKenyaMigrationReview(new Request('https://site.test/api/cms/migrations/kenya',{method:'POST',headers:{Authorization:'Bearer test.editor.token','Content-Type':'application/json'},body:JSON.stringify(body)}),rpc);
