 assert.equal(detail.locale,'fr');assert.equal(detail.path,'/projects/translated-project');assert.equal(detail.payload.slug,payload.slug);assert.equal(detail.payload.seo.canonical,'');assert.equal(projectSchema.safeParse(detail.payload).success,true);assert.equal(detail.publishedRevision,null);
 const status=async()=>(await db.query('select cms.get_translation_status($1,$2) value',[site,translated.recordId])).rows[0].value;
