 await actor(reviewer);await db.query('select cms.review_translation($1,$2,$3,$4)',[site,translated.recordId,translated.revisionId,source.revisionId]);assert.equal((await status()).status,'current');
 await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'project','/projects/translated-project','Updated source',$4::jsonb)",[site,source.recordId,source.revisionId,JSON.stringify({...payload,title:'Updated source'})]);assert.equal((await status()).status,'source_changed');assert.deepEqual(await create(),translated);
 const family=(await db.query('select cms.get_translation_family($1,$2,null) value',[site,translated.recordId])).rows[0].value;assert.equal(family.source.id,source.recordId);assert.equal(family.translations[0].type,'project');
