test('translated custom-page release rechecks withdrawn dependencies and retains source translation review',async()=>{
 await root();await db.exec('begin');
 try{
  const payload=href=>({composition:{schemaVersion:1,title:'Notre histoire',sections:[{id:'intro',kind:'text',controls:{label:'Introduction',headingLevel:'h1'},data:{title:'Notre histoire',body:[{kind:'paragraph',text:'Une histoire de voyage.'},...(href?[{kind:'link',label:'Lire',href}]:[])]}}]}});
  const savePage=async(path,locale='fr',href)=>{await actor(editor);return (await db.query("select cms.save_draft($1,null,null,'page',$2,'Notre histoire',$3::jsonb,$4) value",[site,path,JSON.stringify(payload(href)),locale])).rows[0].value;};
  const check=async record=>{await actor(null,'service_role');return runTrustedValidation(async(name,args)=>name==='get_validation_input'?(await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value:db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]),{site,record:record.recordId,revision:record.revisionId});};
  const approve=async record=>{await actor(editor);await review(record,'submit');await actor(reviewer);await review(record,'approve');};
  const fail=async(fn,pattern)=>{await db.exec('savepoint expected_failure');try{await assert.rejects(fn,pattern);}finally{await db.exec('rollback to savepoint expected_failure');}};
  const destination=await savePage('/translated-destination');assert.equal((await check(destination)).contentChecksPass,true);await approve(destination);await actor(publisher);await publish(destination);
  const page=await savePage('/translated-source','fr','https://www.safaricrafters.com/translated-destination?from=story#main');const pageCheck=await check(page);assert.equal(pageCheck.contentChecksPass,true,JSON.stringify(pageCheck.findings));await approve(page);await actor(publisher);
  // Keep the successful receipt, then withdraw its dependency through the actual API.
  await db.exec('savepoint destination_available');await db.query('select cms.unpublish($1,$2,$3)',[site,destination.recordId,destination.revisionId]);await fail(()=>publish(page),/custom_page_link_unavailable/);await db.exec('rollback to savepoint destination_available');
  await publish(page);await actor(null,'anon');const publicPage=(await db.query("select cms.get_public_page($1,'/translated-source','fr') value",[site])).rows[0].value;assert.equal(publicPage.revisionId,page.revisionId);assert.equal((await db.query("select cms.get_public_page($1,'/translated-source','en') value",[site])).rows[0].value,null);
  const wrongLanguage=await savePage('/translated-only-english','en');assert.equal((await check(wrongLanguage)).contentChecksPass,true);await approve(wrongLanguage);await actor(publisher);await publish(wrongLanguage);
  const blocked=await savePage('/translated-wrong-language','fr','/translated-only-english');assert.equal((await check(blocked)).contentChecksPass,false);await approve(blocked);await actor(null,'service_role');await receipt(blocked,'composition-5',true);await actor(publisher);await fail(()=>publish(blocked),/custom_page_link_unavailable/);
  const source=await savePage('/translation-reviewed-source','en');await actor(editor);const translated=(await db.query("select cms.create_translation_draft($1,$2,$3,'fr','/translation-reviewed-target',$4) value",[site,source.recordId,source.revisionId,randomUUID()])).rows[0].value;
  assert.equal((await check(translated)).contentChecksPass,true);await approve(translated);await actor(publisher);await fail(()=>publish(translated),/translation_review_required/);
  await actor(reviewer);await db.query('select cms.review_translation($1,$2,$3,$4)',[site,translated.recordId,translated.revisionId,source.revisionId]);await actor(publisher);await publish(translated);
  await db.query('select cms.unpublish($1,$2,$3)',[site,translated.recordId,translated.revisionId]);await actor(null,'anon');assert.equal((await db.query("select cms.get_public_page($1,'/translation-reviewed-target','fr') value",[site])).rows[0].value,null);
 }finally{await db.exec('rollback');await root();}
});

