test('translated settings complete approved publication and assemble the public page and shared shell',async()=>{
 await root();await db.exec('begin');
 try{
  const {defaultInterfaceText}=await import('../lib/cms/interface-text.ts');const {loadLocalizedCustomPage}=await import('../lib/cms/localized-page-runtime.ts');const {loadLocalizedShell}=await import('../lib/cms/localized-shell.ts');
  const saveRecord=async(type,path,payload)=>{await actor(editor);return (await db.query("select cms.save_draft($1,null,null,$2,$3,'French publication',$4::jsonb,'fr') value",[site,type,path,JSON.stringify(payload)])).rows[0].value;};
  const check=async record=>{await actor(null,'service_role');return runTrustedValidation(async(name,args)=>name==='get_validation_input'?(await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value:db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]),{site,record:record.recordId,revision:record.revisionId});};
  const approve=async record=>{await actor(editor);await review(record,'submit');await actor(reviewer);await review(record,'approve');};
  const release=async record=>{const result=await check(record);assert.equal(result.contentChecksPass,true,JSON.stringify(result.findings));await approve(record);await actor(publisher);await publish(record);};
  const fail=async(fn,pattern)=>{await db.exec('savepoint expected_failure');try{await assert.rejects(fn,pattern);}finally{await db.exec('rollback to savepoint expected_failure');}};
  const path='/complete-french-page',page=await saveRecord('page',path,{composition:{schemaVersion:1,title:'Notre histoire',sections:[{id:'intro',kind:'text',controls:{label:'Introduction',headingLevel:'h1'},data:{title:'Notre histoire',body:[{kind:'paragraph',text:'Notre récit de voyage.'}]}}]}});await release(page);
  const menu=await saveRecord('navigation',null,{schemaVersion:1,title:'Explorer',items:[{id:'home',parentId:null,label:'Notre histoire',target:{kind:'record',contentType:'page',recordId:page.recordId},visibility:{visible:true}}]});await release(menu);
  const payload=newGlobalSettings();payload.header.mainMenu={recordId:menu.recordId};payload.interfaceText={...defaultInterfaceText('Marque'),homeHref:path,homeLabel:'Accueil',skipLink:'Aller au contenu',openMenu:'Ouvrir le menu',closeMenu:'Fermer le menu'};payload.search.enabled=false;payload.cookies.title='Vos préférences';payload.cookies.description='Choisissez votre confidentialité.';payload.cookies.policy={label:'Notre politique',href:path,newWindow:false};payload.footer.copyright='Tous droits réservés.';payload.footer.legalLinks=[{id:'policy',link:{label:'Notre politique',href:path,newWindow:false}}];payload.seo.description='Notre histoire en français.';
  payload.header.languageSelector=true;payload.header.languageSelectorLabel='Langues';
  const settings=await saveRecord('settings',null,payload);await actor(outsider);await fail(()=>db.query('select cms.get_editor_localized_settings_evidence($1,$2,$3)',[site,settings.recordId,settings.revisionId]),/forbidden/);await actor(editor);assert.equal((await db.query('select cms.get_editor_localized_settings_evidence($1,$2,$3) value',[site,settings.recordId,settings.revisionId])).rows[0].value.revisionId,settings.revisionId);const checked=await check(settings);assert.equal(checked.contentChecksPass,true,JSON.stringify(checked.findings));await approve(settings);await actor(publisher);
  await db.exec('savepoint selector_label');await actor(editor);const missingLabel=structuredClone(payload);delete missingLabel.header.languageSelectorLabel;
  const invalidSelector=(await db.query("select cms.save_draft($1,$2,$3,'settings',null,'French publication',$4::jsonb,'fr') value",[site,settings.recordId,settings.revisionId,JSON.stringify(missingLabel)])).rows[0].value;
  assert.equal((await check(invalidSelector)).contentChecksPass,false);await approve(invalidSelector);await actor(null,'service_role');await receipt(invalidSelector,'settings-1',true);await actor(publisher);await fail(()=>publish(invalidSelector),/settings_language_selector_label_required/);await db.exec('rollback to savepoint selector_label');
  await db.exec('savepoint menu_available');await db.query('select cms.unpublish($1,$2,$3)',[site,menu.recordId,menu.revisionId]);await fail(()=>publish(settings),/settings_reference_verification_required/);await db.exec('rollback to savepoint menu_available');
  await db.exec('savepoint page_available');await db.query('select cms.unpublish($1,$2,$3)',[site,page.recordId,page.revisionId]);await fail(()=>publish(settings),/settings_reference_verification_required|custom_page_link_unavailable/);await db.exec('rollback to savepoint page_available');await publish(settings);
  await actor(null,'anon');const env={CMS_LOCALIZED_PAGES_ENABLED:'true',CMS_CUSTOM_PAGES_ENABLED:'true',CMS_PUBLIC_DELIVERY_ENABLED:'true',CMS_WEBSITE_ID:site,CMS_SUPABASE_URL:'https://db.test',CMS_SUPABASE_ANON_KEY:'anon'};
  const fetcher=async(url,init)=>{assert.equal(init.headers.Authorization,'Bearer anon');const args=JSON.parse(init.body);assert.equal(args.p_locale,'fr');let result;switch(String(url).split('/').at(-1)){
   case 'get_public_page':result=await db.query('select cms.get_public_page($1,$2,$3) value',[site,args.p_path,args.p_locale]);break;
   case 'get_public_seo_settings':result=await db.query('select cms.get_public_seo_settings($1,$2) value',[site,args.p_locale]);break;
   case 'get_public_header':result=await db.query('select cms.get_public_header($1,$2) value',[site,args.p_locale]);break;
   case 'get_public_localized_routes':result=await db.query('select cms.get_public_localized_routes($1,$2,$3::jsonb) value',[site,args.p_locale,JSON.stringify(args.p_paths)]);break;
   default:throw Error('Unexpected public read');
  }return Response.json(result.rows[0].value);};
  const content=await loadLocalizedCustomPage(path,'fr',env,fetcher),shell=await loadLocalizedShell('fr',{recordId:content.settingsRecordId,revisionId:content.settingsRevisionId},env,fetcher);
  assert.equal(shell.settings.header.languageSelectorLabel,'Langues');assert.equal(shell.header.languageSelector,true);
  assert.equal(content.page.path,'/languages/fr'+path);assert.equal(shell.header.main.items[0].link.href,content.page.path);assert.equal(shell.settings.cookies.policy.href,content.page.path);assert.equal(shell.settings.footer.legalLinks[0].link.href,content.page.path);assert.equal(shell.interfaceText.skipLink,'Aller au contenu');assert.equal(shell.revisionId,settings.revisionId);
  await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,settings.recordId,settings.revisionId]);await actor(null,'anon');await assert.rejects(()=>loadLocalizedCustomPage(path,'fr',env,fetcher),/SEO defaults/);
 }finally{await db.exec('rollback');await root();}
});

test('menu translation adapts source-language visibility without changing regions schedules links or recovery receipts',async()=>{
 const {navigationSchema,visibleNavigationItems}=await import('../lib/cms/navigation.ts');await root();await db.exec('begin');
 try{
  const payload={schemaVersion:1,title:'Source menu',items:[
   {id:'source',parentId:null,label:'Source',target:{kind:'url',href:'https://example.com/source'},visibility:{visible:true,locales:['qaa','qab','de'],regions:[]}},
   {id:'unrestricted',parentId:'source',label:'Child',target:{kind:'url',href:'https://example.com/child'},visibility:{visible:true,locales:[],regions:[]}},
   {id:'other',parentId:null,label:'Other',target:{kind:'url',href:'https://example.com/other'},visibility:{visible:true,locales:['de'],regions:[]}},
   {id:'hidden',parentId:null,label:'Hidden',target:{kind:'url',href:'https://example.com/hidden'},visibility:{visible:false,locales:['qaa'],regions:['europe']}},
   {id:'future',parentId:null,label:'Future',target:{kind:'url',href:'https://example.com/future'},visibility:{visible:true,locales:['qaa'],regions:[],from:'2027-01-01T00:00:00Z'}},
   {id:'reference',parentId:null,label:'Source reference',target:{kind:'record',contentType:'page',recordId:randomUUID()},visibility:{locales:['qaa']}}
  ]};
  await actor(editor);const source=(await db.query("select cms.save_draft($1,null,null,'navigation',null,'Source menu',$2::jsonb,'qaa') value",[site,JSON.stringify(payload)])).rows[0].value;
  const args=[site,source.recordId,source.revisionId,'qab',null,randomUUID()];const translated=(await db.query('select cms.create_translation_draft($1,$2,$3,$4,$5,$6) value',args)).rows[0].value;
  const get=async id=>(await db.query('select cms.get_editor_record($1,$2) value',[site,id])).rows[0].value;
  const target=await get(translated.recordId);assert.equal(target.locale,'qab');assert.equal(target.publishedRevision,null);assert.deepEqual(target.payload.items.map(i=>i.visibility.locales),[['qab','de'],[],['de'],['qab'],['qab'],['qab']]);
  const expected=structuredClone(payload);expected.items.forEach(item=>{item.visibility.locales=[...new Set(item.visibility.locales.map(locale=>locale==='qaa'?'qab':locale))];});assert.deepEqual(target.payload,expected);assert.deepEqual((await get(source.recordId)).payload,payload);
  const menu=navigationSchema.parse(target.payload);assert.deepEqual(visibleNavigationItems(menu,{locale:'qab',now:new Date('2026-10-28T00:00:00Z')}).map(i=>i.id),['source','unrestricted','reference']);assert.equal(menu.items[5].target.recordId,payload.items[5].target.recordId);
  // Recovering creation must not rewrite a subsequent editor change or re-run adaptation.
  const edited=structuredClone(target.payload);edited.items[0].visibility.locales=['de'];const saved=(await db.query("select cms.save_draft($1,$2,$3,'navigation',null,'Edited translation',$4::jsonb,'qab') value",[site,target.id,target.currentRevision,JSON.stringify(edited)])).rows[0].value;
  assert.deepEqual((await db.query('select cms.create_translation_draft($1,$2,$3,$4,$5,$6) value',args)).rows[0].value,translated);const recovered=await get(target.id);assert.equal(recovered.currentRevision,saved.revisionId);assert.deepEqual(recovered.payload,edited);
 }finally{await db.exec('rollback');await root();}
});

test('public language discovery includes only published family pages with available published language shells',async()=>{
 const {defaultInterfaceText}=await import('../lib/cms/interface-text.ts');await root();await db.exec('begin');
 try{
  const saveRecord=async(type,path,locale,payload,previous)=>{await actor(editor);return (await db.query("select cms.save_draft($1,$2,$3,$4,$5,'Language family fixture',$6::jsonb,$7) value",[site,previous?.recordId??null,previous?.revisionId??null,type,path,JSON.stringify(payload),locale])).rows[0].value;};
  const release=async(record,source)=>{
   await actor(null,'service_role');const checked=await runTrustedValidation(async(name,args)=>name==='get_validation_input'?(await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value:db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]),{site,record:record.recordId,revision:record.revisionId});assert.equal(checked.contentChecksPass,true,JSON.stringify(checked.findings));
   await actor(editor);await review(record,'submit');await actor(reviewer);await review(record,'approve');if(source)await db.query('select cms.review_translation($1,$2,$3,$4)',[site,record.recordId,record.revisionId,source.revisionId]);await actor(publisher);await publish(record);
  };
  const shell=async(page,path,locale)=>{
   const menu=await saveRecord('navigation',null,locale,{schemaVersion:1,title:'Explorer',items:[{id:'home',parentId:null,label:'Notre histoire',target:{kind:'record',contentType:'page',recordId:page.recordId},visibility:{visible:true}}]});await release(menu);
   const payload=newGlobalSettings();payload.header.mainMenu={recordId:menu.recordId};payload.interfaceText={...defaultInterfaceText('Marque'),homeHref:path};payload.search.enabled=false;payload.cookies.title='Préférences';payload.cookies.description='Confidentialité';payload.footer.copyright='Droits réservés.';payload.seo.description='Notre histoire.';
   const settings=await saveRecord('settings',null,locale,payload);await release(settings);return {menu,settings,payload};
  };
  const sourcePath='/language-family-root',targetPath='/language-family-target',source=await saveRecord('page',sourcePath,'fr',{composition:{schemaVersion:1,title:'Notre histoire',sections:[{id:'intro',kind:'text',controls:{label:'Introduction',headingLevel:'h1'},data:{title:'Notre histoire',body:[{kind:'paragraph',text:'Notre récit.'}]}}]}});await release(source);await shell(source,sourcePath,'fr');
  await actor(editor);const target=(await db.query("select cms.create_translation_draft($1,$2,$3,'de',$4,$5) value",[site,source.recordId,source.revisionId,targetPath,randomUUID()])).rows[0].value;
  await db.query("select cms.create_translation_draft($1,$2,$3,'es','/private-language-draft',$4)",[site,source.recordId,source.revisionId,randomUUID()]);
  const read=async(record=source.recordId,revision=source.revisionId,locale='fr',website=site)=>{await actor(null,'anon');return (await db.query('select cms.get_public_language_variants($1,$2,$3,$4) value',[website,record,revision,locale])).rows[0].value;};
  const list=async(after=null,limit=100,website=site)=>{await actor(null,'anon');return (await db.query('select cms.list_published_localized_pages($1,$2,$3) value',[website,after,limit])).rows[0].value;};
  assert.ok((await list()).items.some(v=>v.recordId===source.recordId));assert.ok(!(await list()).items.some(v=>v.recordId===target.recordId));assert.deepEqual(await list(null,100,otherSite),{websiteId:otherSite,items:[]});
  assert.deepEqual((await read()).variants.map(v=>v.locale),['fr']);assert.equal(await read(target.recordId,target.revisionId,'de'),null);assert.equal(await read(source.recordId,target.revisionId),null);assert.equal(await read(source.recordId,source.revisionId,'fr',otherSite),null);
  await release(target,source);assert.deepEqual((await read()).variants.map(v=>v.locale),['fr']);const translatedShell=await shell(target,targetPath,'de');
  const catalogue=await list();assert.ok(catalogue.items.some(v=>v.recordId===target.recordId&&v.revisionId===target.revisionId&&v.locale==='de'));assert.ok(!JSON.stringify(catalogue).includes('/private-language-draft'));
  const first=(await list(null,1)).items;assert.equal(first.length,1);const next=(await list(first[0].recordId,1)).items;assert.ok(next.every(v=>v.recordId>first[0].recordId));
  await db.exec('savepoint invalid_catalogue_limit');await assert.rejects(()=>list(null,101),/invalid_page_size/);await db.exec('rollback to savepoint invalid_catalogue_limit');
  const family=await read(),reverse=await read(target.recordId,target.revisionId,'de');assert.deepEqual(family.variants.map(v=>v.locale),['de','fr']);assert.deepEqual(reverse.variants,family.variants);assert.ok(!JSON.stringify(family).includes('/private-language-draft'));assert.equal('sourceRevisionId' in family,false);assert.equal('reviewedBy' in family,false);
  const draft=structuredClone(translatedShell.payload);draft.interfaceText.homeHref='/private-unpublished-destination';await saveRecord('settings',null,'de',draft,translatedShell.settings);assert.deepEqual((await read()).variants,family.variants);assert.deepEqual(await list(),catalogue);
  await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,translatedShell.menu.recordId,translatedShell.menu.revisionId]);assert.deepEqual((await read()).variants.map(v=>v.locale),['fr']);assert.ok(!(await list()).items.some(v=>v.recordId===target.recordId));
  await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,source.recordId,source.revisionId]);assert.equal(await read(),null);
 }finally{await db.exec('rollback');await root();}
});

test('content health is permission filtered and distinguishes absent failed stale and current validation',async()=>{
 await root();await db.exec('begin');try{
  await actor(editor);const saved=(await db.query("select cms.save_draft($1,null,null,'journey','/journeys/health-fixture','Health fixture','{}'::jsonb,'en') value",[site])).rows[0].value;
  const read=async(after=null,limit=50)=>(await db.query('select cms.list_content_health($1,$2,$3) value',[site,after,limit])).rows[0].value;
  const find=async()=>{let after=null;for(let i=0;i<100;i++){const result=await read(after);const row=result.items.find(v=>v.id===saved.recordId);if(row)return row;if(!result.nextCursor)break;after=result.nextCursor;}throw Error('Fixture missing');};
  assert.equal((await find()).validationState,'not_checked');assert.equal((await find()).canRequest,true);
  await actor(null,'service_role');await receipt(saved,'journey-2',false,[{field:'title',severity:'error',code:'missing',message:'Add a title'}]);await actor(editor);assert.equal((await find()).validationState,'failed');assert.equal((await find()).errors,1);
  await actor(null,'service_role');await receipt(saved);await actor(editor);assert.equal((await find()).validationState,'passed');
  await root();await db.query("update cms.validations set expires_at=now()-interval '1 second' where revision_id=$1",[saved.revisionId]);await actor(editor);assert.equal((await find()).validationState,'stale');
  await actor(outsider);assert.deepEqual(await read(),{websiteId:site,items:[],nextCursor:null});
  await root();const role=randomUUID();await db.query("insert into cms.roles(id,website_id,name) values($1,$2,'Health limited')",[role,site]);await db.query('insert into cms.memberships(website_id,user_id,role_id) values($1,$2,$3)',[site,outsider,role]);await db.query("insert into cms.permissions(website_id,role_id,action,content_type,record_id) values($1,$2,'view','journey',$3)",[site,role,saved.recordId]);await actor(outsider);
  const limited=await read(null,1);assert.equal(limited.items.length,1);assert.equal(limited.items[0].id,saved.recordId);assert.equal(limited.items[0].canRequest,false);assert.equal(limited.nextCursor,null);
  await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,outsider]);await actor(outsider);assert.deepEqual((await read()).items,[]);
  await db.exec('savepoint anon_health');await actor(null,'anon');await assert.rejects(()=>read(),/permission denied/);await db.exec('rollback to savepoint anon_health');
 }finally{await db.exec('rollback');await root();}
});

