test('standalone delivery retry rechecks permissions state and leases without changing publication',async()=>{
 await root();await db.exec('begin');try{
 await actor(editor);const saved=await save('/journeys/standalone-retry');await root();
 const add=async(status='failed',attempts=8,operation='unpublish',lease=null)=>(await db.query("insert into cms.delivery_jobs(website_id,record_id,revision_id,operation,status,attempts,lease_until,last_error) values($1,$2,$3,$4,$5,$6,$7,'old error') returning id",[site,saved.recordId,saved.revisionId,operation,status,attempts,lease])).rows[0].id;
 const target=await add(),running=await add('running'),automatic=await add('failed',3),stale=await add('failed',8,'publish'),leased=await add('failed',8,'unpublish','2099-01-01'),group=await add();
 await db.query("insert into cms.publication_releases(website_id,request_id,actor_id,items,result) values($1,$2,$3,$4::jsonb,$5::jsonb)",[site,randomUUID(),publisher,JSON.stringify([{record:saved.recordId,revision:saved.revisionId}]),JSON.stringify({items:[{record:saved.recordId,revision:saved.revisionId,deliveryJob:group}]})]);
 const retry=async(job=target,website=site)=>(await db.query('select cms.retry_standalone_delivery($1,$2) value',[website,job])).rows[0].value;
 await actor(editor);await db.exec('savepoint denied_retry');await assert.rejects(()=>retry(),/forbidden/);await db.exec('rollback to savepoint denied_retry');
 await actor(publisher);for(const job of [running,automatic,stale,leased,group])assert.equal((await retry(job)).status,'not_eligible');
 const monitored=[];let cursor=null;do{const page=(await db.query("select cms.list_delivery_monitor($1,$2,'all',20) value",[site,cursor])).rows[0].value;monitored.push(...page.items);cursor=page.nextCursor;}while(cursor);assert.equal(monitored.find(row=>row.id===target).canRetry,true);assert.equal(monitored.find(row=>row.id===group).canRetry,false);
 assert.equal((await retry()).status,'queued');assert.equal((await retry()).status,'not_eligible');await root();const job=(await db.query('select * from cms.delivery_jobs where id=$1',[target])).rows[0];assert.equal(job.status,'pending');assert.equal(job.attempts,0);assert.equal(job.last_error,null);assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[saved.recordId])).rows[0].published_revision_id,null);
 assert.equal((await db.query("select count(*)::int n from cms.audit_events where record_id=$1 and action='delivery.retry_requested'",[saved.recordId])).rows[0].n,1);
 // Seed a current published pointer to verify retry does not alter it.
 await db.exec('alter table cms.records disable trigger user');try{await db.query('update cms.records set published_revision_id=$1 where id=$2',[saved.revisionId,saved.recordId]);}finally{await db.exec('alter table cms.records enable trigger user');}
 const currentPublish=await add('failed',8,'publish'),oldWithdrawal=await add();await actor(publisher);assert.equal((await retry(currentPublish)).status,'queued');assert.equal((await retry(oldWithdrawal)).status,'not_eligible');await root();assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[saved.recordId])).rows[0].published_revision_id,saved.revisionId);
 await actor(publisher);await db.exec('savepoint wrong_site_retry');await assert.rejects(()=>retry(target,otherSite),/forbidden/);await db.exec('rollback to savepoint wrong_site_retry');
 await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,publisher]);await actor(publisher);await db.exec('savepoint revoked_retry');await assert.rejects(()=>retry(),/forbidden/);await db.exec('rollback to savepoint revoked_retry');
 await db.exec('savepoint anon_retry');await actor(null,'anon');await assert.rejects(()=>retry(),/permission denied/);await db.exec('rollback to savepoint anon_retry');
 }finally{await db.exec('rollback');await root();}
});

