 await actor(editor);const target=(await db.query("select cms.save_draft($1,null,null,'page','/approval-target','Approval target',$2::jsonb) value",[site,JSON.stringify({composition:{schemaVersion:1,title:'Approval target',sections:[]}})])).rows[0].value;
