 await db.exec("create function cms.test_redirect_import_failure() returns trigger language plpgsql as $$ begin if new.action='redirect_import.applied' then raise exception 'injected_import_failure';end if;return new;end $$; create trigger test_redirect_import_failure before insert on cms.audit_events for each row execute function cms.test_redirect_import_failure()");
 const counts=async()=>(await db.query('select (select count(*) from cms.page_redirects)::int aliases,(select count(*) from cms.page_redirect_states)::int states,(select count(*) from cms.delivery_jobs)::int jobs,(select count(*) from cms.redirect_import_applications)::int receipts')).rows[0];const before=await counts();await actor(publisher);await mfaReject(()=>apply(),/injected_import_failure/);await root();assert.deepEqual(await counts(),before);await db.exec('drop trigger test_redirect_import_failure on cms.audit_events; drop function cms.test_redirect_import_failure()');
 await actor(publisher);const applied=await apply();assert.equal(applied.status,'applied');assert.equal(applied.stale,false);assert.equal(applied.application.changes,2);assert.equal(applied.application.jobs.length,1);assert.equal(applied.application.jobs[0].recordId,target.recordId);assert.equal(applied.application.jobs[0].revisionId,target.revisionId);assert.deepEqual(await apply(),applied);
 await root();const after=await counts();assert.equal(after.aliases-before.aliases,2);assert.equal(after.jobs-before.jobs,1);assert.equal(after.receipts-before.receipts,1);assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[target.recordId])).rows[0].published_revision_id,target.revisionId);
