  await actor(editor);const changedPayload=structuredClone(guardPayload);changedPayload.composition.title='Private Tanzania change';
  const nextDraft=(await db.query("select cms.save_draft($1,$2,$3,'page','/destinations/tanzania','Private Tanzania change',$4::jsonb) value",[site,delivery.recordId,delivery.revisionId,JSON.stringify(changedPayload)])).rows[0].value;
  const restored=(await db.query('select cms.restore_draft($1,$2,$3,$4) value',[site,delivery.recordId,delivery.revisionId,nextDraft.revisionId])).rows[0].value;assert.notEqual(restored.revisionId,delivery.revisionId);
  await actor(null,'service_role');const restoredCheck=await runTrustedValidation(async(name,args)=>(await db.query(`select cms.${name}(${Object.keys(args).map((k,i)=>`${k}=>$${i+1}`).join(',')}) value`,Object.values(args).map(v=>v&&typeof v==='object'?JSON.stringify(v):v))).rows[0].value,{site,record:restored.recordId,revision:restored.revisionId});assert.equal(restoredCheck.contentChecksPass,true,JSON.stringify(restoredCheck.findings));
  await actor(editor);await review(restored,'submit');await actor(reviewer);await review(restored,'approve');await actor(publisher);await publish(restored);await actor(null,'anon');assert.equal((await readPublic()).revisionId,restored.revisionId);assert.doesNotMatch(JSON.stringify(await readPublic()),/Private Tanzania change/);await root();
