 await db.exec('savepoint later_project_draft');await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'project','/projects/signed-claims','Claims',$4::jsonb)",[site,project.recordId,project.revisionId,JSON.stringify({...projectPayload,summary:'New draft'})]);assert.equal(await trustedClaim(),true);await db.exec('rollback to savepoint later_project_draft');await actor(reviewer);
 await root();await db.query("update cms.document_files set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(publisher);await reject(()=>db.query('select cms.publish($1,$2,$3)',scope.slice(0,3)),/project_publication_evidence_changed/);await actor(reviewer);assert.equal(await trustedClaim(),false);assert.equal((await review()).snapshot,null);assert.equal((await review()).approvalId,null);await reject(()=>approve(r),/claim_approval_unavailable/);
 await root();await db.query("update cms.document_files set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await actor(reviewer);assert.equal((await review()).approvalId,null);await reject(()=>approve(r),/claim_evidence_changed/);r=await review();await approve(r);
 await actor(editor);const changedDoc=(await db.query("select cms.save_draft($1,$2,$3,'document',null,'Evidence',$4::jsonb) value",[site,doc.recordId,doc.revisionId,JSON.stringify({...docPayload,description:'Changed document description'})])).rows[0].value;
 await actor(reviewer);assert.equal((await review()).approvalId,null);await reject(()=>approve(r),/claim_evidence_changed/);r=await review();assert.equal(r.snapshot.evidence[0].revisionId,changedDoc.revisionId);
