 await db.exec('savepoint document_access');await root();await db.query("update cms.permissions set content_type='project' where role_id=$1 and action='view'",[reviewerRole]);await actor(editor);assert.equal((await review()).approvalId,null);await actor(reviewer);assert.equal((await review()).snapshot,null);await db.exec('rollback to savepoint document_access');
