test('project related cards validate cyclic project dependencies and remove transitive withdrawn or rights-revoked content',async()=>{
 const {newProject}=await import('../lib/cms/projects.ts');await root();await db.exec('begin');try{
 const projects=[];for(let i=0;i<3;i++){const asset=`related-project-${i}`;await root();await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,80,40,'ready','approved','Synthetic rights')",[site,asset,`private/${asset}`,'c'.repeat(64)]);await actor(editor);const payload={...newProject(),slug:`related-project-${i}`,title:`Published project ${i}`,summary:'Summary',body:[{kind:'paragraph',text:'Overview'}],image:{assetId:asset,alt:'Photo',decorative:false}};const saved=(await db.query("select cms.save_draft($1,null,null,'project',$2,$3,$4::jsonb) value",[site,`/projects/${payload.slug}`,payload.title,JSON.stringify(payload)])).rows[0].value;projects.push({...saved,payload});}
 for(let i=0;i<3;i++){const p=projects[i];p.payload.relationships.projects=[{recordId:projects[(i+1)%3].recordId}];const next=(await db.query("select cms.save_draft($1,$2,$3,'project',$4,$5,$6::jsonb) value",[site,p.recordId,p.revisionId,`/projects/${p.payload.slug}`,p.payload.title,JSON.stringify(p.payload)])).rows[0].value;p.revisionId=next.revisionId;}
 // Reader fixture only: simulate releases inside a rollback, preserving normal publish guards.
 await root();await db.exec('alter table cms.records disable trigger cms_project_release_pending');for(const p of projects)await db.query('update cms.records set published_revision_id=$1 where id=$2',[p.revisionId,p.recordId]);await db.exec('alter table cms.records enable trigger cms_project_release_pending');
 await actor(null,'service_role');for(const p of projects){const result=await runTrustedValidation(async(name,args)=>{if(name==='get_validation_input')return(await db.query('select cms.get_validation_input($1,$2,$3) value',[site,p.recordId,p.revisionId])).rows[0].value;await db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[site,p.recordId,p.revisionId,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]);},{site,record:p.recordId,revision:p.revisionId});assert.equal(result.contentChecksPass,true);}
 const read=async(i=0)=>(await db.query('select cms.get_public_project($1,$2) value',[site,`/projects/related-project-${i}`])).rows[0].value;
 await actor(null,'anon');assert.deepEqual((await read()).related,[{type:'project',title:'Published project 1',href:'/projects/related-project-1'}]);assert.equal((await read(2)).related[0].title,'Published project 0');
 await actor(editor);const p=projects[1];await db.query("select cms.save_draft($1,$2,$3,'project',$4,'PRIVATE DRAFT TITLE',$5::jsonb)",[site,p.recordId,p.revisionId,`/projects/${p.payload.slug}`,JSON.stringify({...p.payload,title:'PRIVATE DRAFT TITLE'})]);await actor(null,'anon');assert.equal((await read()).related[0].title,'Published project 1');
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id='related-project-2'",[site]);await actor(null,'anon');assert.equal(await read(),null);assert.equal((await db.query("select cms.get_public_media($1,'related-project-0') value",[site])).rows[0].value,null);
 await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id='related-project-2'",[site]);await db.query('update cms.records set published_revision_id=null where id=$1',[projects[2].recordId]);await actor(null,'anon');assert.equal(await read(),null);assert.equal((await db.query('select cms.list_published_projects($1) value',[site])).rows[0].value.some(r=>r.recordId===projects[0].recordId),false);
 }finally{await db.exec('rollback');await root();}
});
