 const payload={...newProject(),slug:'project-document-card',summary:'Summary',body:[{kind:'paragraph',text:'Overview'}],image:{assetId:'project-doc-card-image',alt:'Photo',decorative:false},relationships:{projects:[],products:[],destinations:[{recordId:destination.recordId}],documents:[{recordId:doc.recordId}]}};await actor(editor);const project=(await db.query("select cms.save_draft($1,null,null,'project','/projects/project-document-card','Project',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;await validate(project);
 await actor(editor);await db.query("select cms.review($1,$2,$3,'submit')",[site,project.recordId,project.revisionId]);await actor(reviewer);await db.query("select cms.review($1,$2,$3,'approve')",[site,project.recordId,project.revisionId]);await actor(publisher);await db.query('select cms.publish($1,$2,$3)',[site,project.recordId,project.revisionId]);
 const read=async()=>(await db.query("select cms.get_public_project($1,'/projects/project-document-card') value",[site])).rows[0].value;await actor(null,'anon');const value=await read();assert.deepEqual(value.related,[{type:'destination',title:'Published destination',href:'/destinations/project-card-destination'},{type:'document',title:'Public guide',href:`/api/documents/download?record=${doc.recordId}&revision=${doc.revisionId}`}]);assert.equal(JSON.stringify(value).includes('PRIVATE RIGHTS NOTE'),false);
 await actor(editor);const privateDraft=(await db.query("select cms.save_draft($1,$2,$3,'document',null,'PRIVATE TITLE',$4::jsonb) value",[site,doc.recordId,doc.revisionId,JSON.stringify({...docPayload,title:'PRIVATE TITLE',access:'authenticated'})])).rows[0].value;await actor(null,'anon');assert.equal((await read()).related.find(r=>r.type==='document').title,'Public guide');
