test('public FAQ readers expose only immutable published answers and recheck review dates and dependencies',async()=>{
 const {newFaq}=await import('../lib/cms/faqs.ts');await root();await db.exec('begin');
 try{
 await actor(editor);const payload={...newFaq(),question:'Published question',answer:[{kind:'paragraph',text:'Published answer'}],internalNotes:'Never public'},saved=(await db.query("select cms.save_draft($1,null,null,'faq',null,$2,$3::jsonb) value",[site,payload.question,JSON.stringify(payload)])).rows[0].value;
 const read=async(s=site,locale='en')=>(await db.query('select cms.get_public_faq($1,$2,$3) value',[s,saved.recordId,locale])).rows[0].value;
 await actor(null,'anon');assert.equal(await read(),null);
 await actor(null,'service_role');await receipt(saved,'faq-1');await root();
 // Reader fixture only: release is still blocked in the real workflow.
 await db.exec('alter table cms.records disable trigger cms_faq_draft_identity');await db.query('update cms.records set published_revision_id=$1 where id=$2',[saved.revisionId,saved.recordId]);await db.exec('alter table cms.records enable trigger cms_faq_draft_identity');
 await actor(null,'anon');const visible=await read();assert.deepEqual(Object.keys(visible).sort(),['answer','locale','question','recordId','revisionId']);assert.equal(visible.question,payload.question);assert.equal(await read(otherSite),null);assert.equal(await read(site,'fr'),null);
 // The temporary publication fence currently rejects even newer-draft saves on a
 // fixture-published FAQ, so disable only around this reader-specific fixture.
 await root();await db.exec('alter table cms.records disable trigger cms_faq_draft_identity');await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'faq',null,'Private new question',$4::jsonb)",[site,saved.recordId,saved.revisionId,JSON.stringify({...payload,question:'Private new question'})]);await root();await db.exec('alter table cms.records enable trigger cms_faq_draft_identity');await actor(null,'anon');assert.equal((await read()).question,'Published question');
 for(const bad of [{...payload,reviewOn:'2000-01-01'},{...payload,relationships:{...payload.relationships,pages:[{recordId:randomUUID()}]}}]){
 await actor(editor);const badRecord=(await db.query("select cms.save_draft($1,null,null,'faq',null,$2,$3::jsonb) value",[site,bad.question,JSON.stringify(bad)])).rows[0].value;await actor(null,'service_role');await receipt(badRecord,'faq-1');await root();await db.exec('alter table cms.records disable trigger cms_faq_draft_identity');await db.query('update cms.records set published_revision_id=$1 where id=$2',[badRecord.revisionId,badRecord.recordId]);await db.exec('alter table cms.records enable trigger cms_faq_draft_identity');await actor(null,'anon');assert.equal((await db.query('select cms.get_public_faq($1,$2) value',[site,badRecord.recordId])).rows[0].value,null);
 }
 await root();await db.query("update cms.validation_policy set validator_version='faq-2' where content_type='faq'");await actor(null,'anon');assert.equal(await read(),null);
 }finally{await db.exec('rollback');await root();}
});

