 const release={...newNews('pressRelease'),slug:'release-storage-test',title:'Example release'};const press=(await db.query("select cms.save_draft($1,null,null,'news','/news/release-storage-test',$2,$3::jsonb) value",[site,release.title,JSON.stringify(release)])).rows[0].value;
