 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 assert.equal((await runTrustedValidation(rpc,{site,record:saved.recordId,revision:saved.revisionId})).contentChecksPass,true);
 assert.equal((await db.query('select cms.get_leadership_validation_evidence($1,$2,$3) value',[otherSite,saved.recordId,saved.revisionId])).rows[0].value,null);
