test('leadership namespace rejects competing records and refuses migration over existing content',async()=>{
 await root();await db.exec('begin');try{
  for(const path of ['/leadership','/leadership/example','/leadership/example/nested'])assert.equal((await db.query('select cms.is_custom_page_path($1) value',[path])).rows[0].value,false);
  assert.equal((await db.query("select cms.is_custom_page_path('/leadershipletter') value")).rows[0].value,true);
  await actor(editor);
  for(const [type,path] of [['journey','/leadership'],['journey','/leadership/example'],['sharedSection','/leadership/example']]){
   await db.exec('savepoint collision');await assert.rejects(()=>db.query("select cms.save_draft($1,null,null,$2,$3,'Collision','{}'::jsonb)",[site,type,path]),/leadership_namespace_reserved/);await db.exec('rollback to savepoint collision');
  }
  const saved=(await db.query("select cms.save_draft($1,null,null,'page','/leadership-namespace-fixture','Fixture','{}'::jsonb) value",[site])).rows[0].value;
  const migration=await fs.readFile(new URL('../database/cms/346-leadership-route-ownership.sql',import.meta.url),'utf8');
  const guard=migration.slice(migration.indexOf('do $$'),migration.indexOf('create or replace function'));
  await root();await db.exec('alter table cms.records disable trigger user');await db.query("update cms.records set path='/leadership/existing-client-page' where id=$1",[saved.recordId]);await db.exec('alter table cms.records enable trigger user');
  await db.exec('savepoint migration_collision');await assert.rejects(()=>db.exec(guard),/leadership_namespace_occupied/);await db.exec('rollback to savepoint migration_collision');
  assert.equal((await db.query('select path from cms.records where id=$1',[saved.recordId])).rows[0].path,'/leadership/existing-client-page');
 }finally{await db.exec('rollback');await root();}
});

