 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:page.recordId,revision:page.revisionId})).contentChecksPass,false);
 assert.equal((await db.query('select cms.get_page_leadership_evidence($1,$2,$3) value',[otherSite,page.recordId,page.revisionId])).rows[0].value,null);
 await actor(editor);await review(profile,'submit');await review(page,'submit');await actor(reviewer);await review(profile,'approve');await review(page,'approve');
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:profile.recordId,revision:profile.revisionId})).contentChecksPass,true);
 // Even a receipt created by a faulty worker cannot bypass the publication dependency check.
 await root();const policy=(await db.query("select validator_version from cms.validation_policy where content_type='page'")).rows[0].validator_version;await actor(null,'service_role');await receipt(page,policy);
 await actor(publisher);await fail(()=>publish(page),/page_leadership_unavailable/);await publish(profile);
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:page.recordId,revision:page.revisionId})).contentChecksPass,true);
 await actor(publisher);await publish(page);await actor(null,'anon');assert.ok((await db.query("select cms.get_public_page($1,'/team-reference') value",[site])).rows[0].value);
