test('leadership import review checks scoped draft targets and references without writes or approval',async()=>{
 const {newLeadership}=await import('../lib/cms/leadership.ts');await root();await db.exec('begin');try{
 await actor(editor);const payload={...newLeadership(),slug:'import-review-leadership'};
 const saved=(await db.query("select cms.save_draft($1,null,null,'leadership',$2,$3,$4::jsonb) value",[site,`/leadership/${payload.slug}`,'Import review',JSON.stringify(payload)])).rows[0].value;
 const related=(await db.query("select cms.save_draft($1,null,null,'page','/leadership-import-related','Related','{}'::jsonb) value",[site])).rows[0].value;
 const references=[{recordId:related.recordId,type:'page'},{recordId:otherSite,type:'document'}];
 const check=async({create=false,records=[saved.recordId],refs=references,target=site,assets=['missing-image']}={})=>(await db.query('select cms.review_leadership_import_links($1,$2,$3,$4,$5::jsonb) value',[target,create,records,assets,JSON.stringify(refs)])).rows[0].value;
 const initial=await check();assert.deepEqual(initial.assets,[{assetId:'missing-image',available:false}]);assert.deepEqual(initial.references,[{...references[0],available:true,revision:related.revisionId},{...references[1],available:false,revision:null}]);
 assert.deepEqual((await check({refs:[{recordId:saved.recordId,type:'document'}]})).references,[{recordId:saved.recordId,type:'document',available:false,revision:null}]);
 const updated=(await db.query("select cms.save_draft($1,$2,$3,'leadership',$4,$5,$6::jsonb) value",[site,saved.recordId,saved.revisionId,`/leadership/${payload.slug}`,'Updated',JSON.stringify(payload)])).rows[0].value;
 assert.equal((await check()).references[0].revision,related.revisionId);assert.notEqual(updated.revisionId,saved.revisionId);
 for(const args of [{refs:[...references,references[0]]},{assets:['duplicate','duplicate']},{target:otherSite},{create:false,records:[]}]){await db.exec('savepoint rejected_project_import');await assert.rejects(()=>check(args));await db.exec('rollback to savepoint rejected_project_import');}
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='view'",[site,editorRole]);await actor(editor);
 // Create permission alone cannot reveal target metadata or permit updating hidden records.
 const hidden=await check({create:true,records:[]});assert.equal(hidden.references[0].available,false);assert.equal(hidden.references[0].revision,null);
 await db.exec('savepoint hidden_update');await assert.rejects(()=>check(),/forbidden/);await db.exec('rollback to savepoint hidden_update');
 await actor(outsider);await db.exec('savepoint outside_import');await assert.rejects(()=>check({create:true,records:[]}),/forbidden/);await db.exec('rollback to savepoint outside_import');
 await actor(null,'anon');await db.exec('savepoint anonymous_import');await assert.rejects(()=>check(),/permission denied/);await db.exec('rollback to savepoint anonymous_import');
 }finally{await db.exec('rollback');await root();}
});


test('leadership import cancellation fences delayed saves and recovers already completed requests',async()=>{
 const {newLeadership}=await import('../lib/cms/leadership.ts');await root();await db.exec('begin');try{
 await actor(editor);const key=randomUUID(),source='a'.repeat(64),review='b'.repeat(64);
 const item={sourceKey:`leadership_import_${'9'.repeat(64)}`,operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newLeadership(),slug:'cancel-import-fixture'}};
 const cancel=async(request=key,digest=source)=>(await db.query('select cms.cancel_leadership_import($1,$2,$3,$4) value',[site,request,digest,review])).rows[0].value;
 const apply=async(request=key)=>(await db.query('select cms.apply_leadership_import($1,$2,$3,$4,$5::jsonb,$6::jsonb) value',[site,request,source,review,JSON.stringify([item]),JSON.stringify({assets:[],references:[]})])).rows[0].value;
 const first=await cancel();assert.equal(first.status,'cancelled');assert.deepEqual(await cancel(),first);assert.deepEqual((await db.query('select cms.get_leadership_import_receipt($1,$2) value',[site,key])).rows[0].value,first);
 await db.exec('savepoint delayed_import');await assert.rejects(()=>apply(),/leadership_import_cancelled/);await db.exec('rollback to savepoint delayed_import');
 await db.exec('savepoint bypass_fence');await assert.rejects(()=>db.query('select cms.apply_leadership_import_before_cancellation($1,$2,$3,$4,$5::jsonb,$6::jsonb)',[site,key,source,review,JSON.stringify([item]),JSON.stringify({assets:[],references:[]})]),/permission denied/);await db.exec('rollback to savepoint bypass_fence');
 await db.exec('savepoint changed_identity');await assert.rejects(()=>cancel(key,'c'.repeat(64)),/idempotency_key_reused/);await db.exec('rollback to savepoint changed_identity');
 const completedKey=randomUUID(),saved=await apply(completedKey),completed=await cancel(completedKey);assert.deepEqual(completed.result,saved);assert.equal(completed.status,undefined);assert.deepEqual(await apply(completedKey),saved);
 await actor(reviewer);assert.equal((await db.query('select cms.get_leadership_import_receipt($1,$2) value',[site,key])).rows[0].value,null);
 await actor(outsider);await db.exec('savepoint outside_cancel');await assert.rejects(()=>cancel(),/forbidden/);await db.exec('rollback to savepoint outside_cancel');
 }finally{await db.exec('rollback');await root();}
});

test('leadership Office apply is atomic, revision-bound, actor-scoped and recoverable without publication',async()=>{
 const {newLeadership}=await import('../lib/cms/leadership.ts');await root();await db.exec('begin');try{
 await actor(editor);const request=randomUUID();
 const item={sourceKey:`leadership_import_${'a'.repeat(64)}`,operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newLeadership(),slug:'import-atomic-leadership'}};
 const empty={assets:[],references:[]};
 const apply=async(items=[item],key=request,evidence=empty)=>(await db.query('select cms.apply_leadership_import($1,$2,$3,$4,$5::jsonb,$6::jsonb) value',[site,key,'a'.repeat(64),'b'.repeat(64),JSON.stringify(items),JSON.stringify(evidence)])).rows[0].value;
 const receipt=async()=>(await db.query('select cms.get_leadership_import_receipt($1,$2) value',[site,request])).rows[0].value;
 const invalid={...item,sourceKey:`leadership_import_${'b'.repeat(64)}`,payload:{...item.payload,slug:'invalid slug'}};
 await db.exec('savepoint atomic_failure');await assert.rejects(()=>apply([item,invalid]),/invalid_import_item/);await db.exec('rollback to savepoint atomic_failure');
 assert.equal(await receipt(),null);assert.equal((await db.query('select count(*)::int n from cms.records where path=$1',['/leadership/import-atomic-leadership'])).rows[0].n,0);
 const result=await apply();assert.equal(result.length,1);assert.deepEqual(await apply(),result);assert.deepEqual((await receipt()).result,result);
 assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[result[0].recordId])).rows[0].published_revision_id,null);
 await db.exec('savepoint reused_key');await assert.rejects(()=>apply([{...item,payload:{...item.payload,title:'Different'}}]),/idempotency_key_reused/);await db.exec('rollback to savepoint reused_key');
 const update={...item,operation:'update',recordId:result[0].recordId,expectedRevision:result[0].revisionId,payload:{...item.payload,title:'Updated'}};
 const updated=await apply([update],randomUUID());assert.notEqual(updated[0].revisionId,result[0].revisionId);
 await db.exec('savepoint stale_import');await assert.rejects(()=>apply([update],randomUUID()),/revision_conflict/);await db.exec('rollback to savepoint stale_import');
 // Exact old receipt remains recoverable after later edits; it never reapplies them.
 assert.deepEqual(await apply(),result);
 const page=(await db.query("select cms.save_draft($1,null,null,'page','/leadership-import-atomic-related','Related','{}'::jsonb) value",[site])).rows[0].value;
 const related={...item,sourceKey:`leadership_import_${'c'.repeat(64)}`,payload:{...item.payload,slug:'import-related-leadership',relationships:{...item.payload.relationships,pages:[{recordId:page.recordId}]}}};
 const evidence={assets:[],references:[{recordId:page.recordId,type:'page',available:true,revision:page.revisionId}]};
 for(const e of [empty,{...evidence,references:[{...evidence.references[0],revision:result[0].revisionId}]}]){await db.exec('savepoint missing_evidence');await assert.rejects(()=>apply([related],randomUUID(),e),/import_evidence_changed/);await db.exec('rollback to savepoint missing_evidence');}
 assert.equal((await apply([related],randomUUID(),evidence)).length,1);
 await db.exec('savepoint duplicate_source');await assert.rejects(()=>apply([item],randomUUID()),/import_key_already_exists/);await db.exec('rollback to savepoint duplicate_source');
 await root();const asset='leadership-import-rights-check';await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'e'.repeat(64)]);await actor(editor);
 const pictured={...item,sourceKey:`leadership_import_${'d'.repeat(64)}`,payload:{...item.payload,slug:'import-pictured-leadership',image:{assetId:asset,alt:'Example',decorative:false}}};
 const mediaEvidence={assets:[{assetId:asset,available:true}],references:[]};
 await root();await db.query("update cms.media_objects set rights_status='pending' where website_id=$1 and id=$2",[site,asset]);await actor(editor);
 await db.exec('savepoint revoked_image');await assert.rejects(()=>apply([pictured],randomUUID(),mediaEvidence),/import_evidence_changed/);await db.exec('rollback to savepoint revoked_image');
 await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await actor(editor);assert.equal((await apply([pictured],randomUUID(),mediaEvidence)).length,1);
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='view'",[site,editorRole]);await actor(editor);
 await db.exec('savepoint revoked_reference');await assert.rejects(()=>apply([{...related,sourceKey:`leadership_import_${'e'.repeat(64)}`,payload:{...related.payload,slug:'import-hidden-reference'}}],randomUUID(),evidence),/import_evidence_changed/);await db.exec('rollback to savepoint revoked_reference');
 await actor(reviewer);assert.equal(await receipt(),null);await actor(outsider);assert.equal(await receipt(),null);
 await db.exec('savepoint outside_apply');await assert.rejects(()=>apply(),/forbidden/);await db.exec('rollback to savepoint outside_apply');
 }finally{await db.exec('rollback');await root();}
});

test('leadership Office HTTP review and lost-response recovery use the real database receipt',async()=>{
 const {handleLeadershipImportUpload}=await import('../lib/cms/leadership-import-api.ts');const {zip}=await import('./office-fixtures.mjs');
 await root();await db.exec('begin');try{await actor(editor);
 const row=cells=>'<w:tr>'+cells.map(v=>'<w:tc><w:p><w:r><w:t>'+v+'</w:t></w:r></w:p></w:tc>').join('')+'</w:tr>';
 const bytes=zip({'[Content_Types].xml':'<Types/>','word/document.xml':'<w:document xmlns:w="urn:w"><w:body><w:tbl>'+row(['CMSLeadership','1.0','leadership'])+'</w:tbl><w:tbl>'+row(['Pages'])+row(['recordId','operation','title','slug','locale'])+row(['http-leader','create','HTTP leader','http-import-leader','en'])+'</w:tbl></w:body></w:document>'});
 const request=randomUUID();let lose=true,writes=0;
 const call=async(token,name,args)=>{assert.equal(token,'a.b.c');const entries=Object.entries(args),value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>['p_items','p_evidence','p_references'].includes(key)?JSON.stringify(value):value))).rows[0].value;
 if(name==='apply_leadership_import'){writes++;if(lose){lose=false;throw Error('Synthetic response lost after commit');}}return value;};
 const upload=(action,review)=>new Request('https://cms.test/api/cms/import/leadership',{method:'POST',headers:{Authorization:'Bearer a.b.c','X-CMS-Site':site,'X-CMS-Format':'docx','X-CMS-Action':action,...(action!=='review'?{'Idempotency-Key':request,'X-CMS-Review':review}:{})},body:action==='status'?undefined:bytes});
 const response=await handleLeadershipImportUpload(upload('review'),call);assert.equal(response.status,200);const reviewed=await response.json();assert.equal(reviewed.applyAvailable,true);assert.equal(writes,0);
 const lost=await handleLeadershipImportUpload(upload('apply',reviewed.reviewDigest),call);assert.equal(lost.status,500);assert.equal(writes,1);
 const recovered=await(await handleLeadershipImportUpload(upload('status',reviewed.reviewDigest),call)).json();assert.equal(recovered.status,'complete');assert.equal(recovered.result.length,1);
 const replay=await(await handleLeadershipImportUpload(upload('apply',reviewed.reviewDigest),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,recovered.result);assert.equal(writes,1);
 const stored=(await db.query('select internal_title,published_revision_id from cms.records where id=$1',[recovered.result[0].recordId])).rows[0];assert.equal(stored.internal_title,'HTTP leader');assert.equal(stored.published_revision_id,null);
 }finally{await db.exec('rollback');await root();}
});

test('leadership schedules reject incomplete content, stale revisions and revoked publishers and support withdrawal',async()=>{
 const {newLeadership}=await import('../lib/cms/leadership.ts');const {createPublicationScheduleAdapter}=await import('../lib/cms/publication-schedule-database.ts');const {runPublicationScheduleBatch}=await import('../lib/cms/publication-schedule-worker.ts');
 await root();await db.exec('begin');try{
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) result`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].result;};
 const adapter=createPublicationScheduleAdapter(rpc,rpc);
 const enqueue=async(leadership,operation)=>{await actor(publisher);const id=(await db.query("select cms.schedule_publication($1,$2,$3,$4,now()+interval '1 hour') value",[site,leadership.recordId,leadership.revisionId,operation])).rows[0].value;await root();await db.query("update cms.publication_schedules set run_at=now()-interval '1 second',next_attempt_at=now()-interval '1 second' where id=$1",[id]);return id;};
 for(const mode of ['ready','incomplete','publisher','stale']){
  await db.exec('savepoint scheduled_leadership_case');await actor(editor);
  const payload={...newLeadership(),title:'Scheduled Leadership',slug:'scheduled-leadership',summary:'Scheduled update',role:mode==='incomplete'?'':'Director',department:'Operations',body:[{id:'intro',kind:'paragraph',text:'A scheduled update'}]};const leadership=(await db.query("select cms.save_draft($1,null,null,'leadership','/leadership/scheduled-leadership','Scheduled Leadership',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;
  await db.query("select cms.review($1,$2,$3,'submit')",[site,leadership.recordId,leadership.revisionId]);await actor(reviewer);await db.query("select cms.review($1,$2,$3,'approve')",[site,leadership.recordId,leadership.revisionId]);
  const schedule=await enqueue(leadership,'publish');
  if(mode==='stale'){await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'leadership','/leadership/scheduled-leadership','Changed answer',$4::jsonb)",[site,leadership.recordId,leadership.revisionId,JSON.stringify({...payload,title:'Changed answer'})]);await root();}
  if(mode==='publisher')await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,publisher]);
  await actor(null,'service_role');const outcomes=await runPublicationScheduleBatch(adapter);assert.deepEqual(outcomes.find(x=>x.id===schedule),{id:schedule,status:mode==='ready'?'published':'blocked'});
  await root();const state=(await db.query('select status,error_code from cms.publication_schedules where id=$1',[schedule])).rows[0];assert.equal(state.error_code,mode==='ready'?null:mode==='incomplete'?'validation_failed':'publication_guard_failed');
  assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[leadership.recordId])).rows[0].published_revision_id,mode==='ready'?leadership.revisionId:null);
  if(mode==='ready'){
   assert.equal((await db.query('select validator_version from cms.validations where revision_id=$1',[leadership.revisionId])).rows[0].validator_version,'leadership-1');
   const withdrawal=await enqueue(leadership,'unpublish');await actor(null,'service_role');assert.deepEqual((await runPublicationScheduleBatch(adapter)).find(x=>x.id===withdrawal),{id:withdrawal,status:'unpublished'});
   await root();assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[leadership.recordId])).rows[0].published_revision_id,null);
  }
  await db.exec('rollback to savepoint scheduled_leadership_case');
 }
 }finally{await db.exec('rollback');await root();}
});

test('leadership translations preserve draft content and route identity but require fresh independent review',async()=>{
 const {newLeadership,leadershipSchema}=await import('../lib/cms/leadership.ts');await root();await db.exec('begin');try{
 await actor(editor);const payload={...newLeadership(),title:'Source Leadership',slug:'translated-leadership',seo:{...newLeadership().seo,canonical:'https://example.test/source'}};
 const source=(await db.query("select cms.save_draft($1,null,null,'leadership','/leadership/translated-leadership','Source leadership',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value,key=randomUUID();
 const create=async()=>(await db.query("select cms.create_translation_draft($1,$2,$3,'fr','/leadership/translated-leadership',$4) value",[site,source.recordId,source.revisionId,key])).rows[0].value;
 const translated=await create();assert.deepEqual(await create(),translated);
 const detail=(await db.query('select cms.get_editor_record($1,$2) value',[site,translated.recordId])).rows[0].value;
 assert.equal(detail.locale,'fr');assert.equal(detail.path,'/leadership/translated-leadership');assert.deepEqual(detail.payload,{...payload,seo:{...payload.seo,canonical:''}});assert.equal(leadershipSchema.safeParse(detail.payload).success,true);assert.equal(detail.publishedRevision,null);
 const status=async()=>(await db.query('select cms.get_translation_status($1,$2) value',[site,translated.recordId])).rows[0].value;
 assert.equal((await status()).status,'unreviewed');
 await db.exec('savepoint own_translation');await assert.rejects(()=>db.query('select cms.review_translation($1,$2,$3,$4)',[site,translated.recordId,translated.revisionId,source.revisionId]),/separate_approver_required/);await db.exec('rollback to savepoint own_translation');
 await actor(reviewer);await db.query('select cms.review_translation($1,$2,$3,$4)',[site,translated.recordId,translated.revisionId,source.revisionId]);assert.equal((await status()).status,'current');
 await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'leadership','/leadership/translated-leadership','Updated source',$4::jsonb)",[site,source.recordId,source.revisionId,JSON.stringify({...payload,title:'Updated source'})]);assert.equal((await status()).status,'source_changed');assert.deepEqual(await create(),translated);
 const family=(await db.query('select cms.get_translation_family($1,$2,null) value',[site,translated.recordId])).rows[0].value;assert.equal(family.source.id,source.recordId);assert.equal(family.translations[0].type,'leadership');
 await actor(outsider);await db.exec('savepoint hidden_translation');await assert.rejects(()=>status(),/forbidden/);await db.exec('rollback to savepoint hidden_translation');
 }finally{await db.exec('rollback');await root();}
});

test('About leadership validation and publication require exact current public profiles',async()=>{
 const {newLeadership}=await import('../lib/cms/leadership.ts');await root();await db.exec('begin');
 const fail=async(fn,pattern)=>{await db.exec('savepoint page_leadership');try{await assert.rejects(fn,pattern);}finally{await db.exec('rollback to savepoint page_leadership');}};
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 try{
 await actor(editor);const profile=(await db.query("select cms.save_draft($1,null,null,'leadership','/leadership/page-reuse','Reusable profile',$2::jsonb) value",[site,JSON.stringify({...newLeadership(),slug:'page-reuse',role:'Director',summary:'Summary',body:[{id:'intro',kind:'paragraph',text:'Biography'}]})])).rows[0].value;
 const payload={composition:{schemaVersion:1,title:'Team',sections:[{id:'intro',kind:'text',controls:{label:'Intro',headingLevel:'h1'},data:{title:'Team',body:[{kind:'paragraph',text:'Introduction'}]}},{id:'leaders',kind:'reusableLeadership',controls:{label:'Leadership',headingLevel:'h2'},data:{title:'Leadership',records:[{recordId:profile.recordId}]}}]}};
 await root();const existing=(await db.query("select id,current_revision_id from cms.records where website_id=$1 and locale='en' and path='/about'",[site])).rows[0];await actor(editor);
 const page=(await db.query("select cms.save_draft($1,$2,$3,'page','/about','Team',$4::jsonb) value",[site,existing?.id??null,existing?.current_revision_id??null,JSON.stringify(payload)])).rows[0].value;
 await fail(()=>db.query('select cms.get_page_leadership_evidence($1,$2,$3)',[site,page.recordId,page.revisionId]),/permission denied/);
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:page.recordId,revision:page.revisionId})).contentChecksPass,false);
 assert.equal((await db.query('select cms.get_page_leadership_evidence($1,$2,$3) value',[otherSite,page.recordId,page.revisionId])).rows[0].value,null);
 await actor(editor);await review(profile,'submit');await review(page,'submit');await actor(reviewer);await review(profile,'approve');await review(page,'approve');
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:profile.recordId,revision:profile.revisionId})).contentChecksPass,true);
 // Even a receipt created by a faulty worker cannot bypass the publication dependency check.
 await root();const policy=(await db.query("select validator_version from cms.validation_policy where content_type='page'")).rows[0].validator_version;await actor(null,'service_role');await receipt(page,policy);
 await actor(publisher);await fail(()=>publish(page),/page_leadership_unavailable/);await publish(profile);
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:page.recordId,revision:page.revisionId})).contentChecksPass,true);
 await actor(publisher);await publish(page);await actor(null,'anon');assert.ok((await db.query("select cms.get_public_page($1,'/about') value",[site])).rows[0].value);
 await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,profile.recordId,profile.revisionId]);
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:page.recordId,revision:page.revisionId})).contentChecksPass,false);
 }finally{await db.exec('rollback');await root();}
});

