 assert.deepEqual((await get()).owners.map(o=>o.id),[reviewer]);assert.equal((await get()).claims[0].version,0);
 await reject(()=>assign(editor,0),/application_claim_owner_unavailable/);await reject(()=>assign(outsider,0),/application_claim_owner_unavailable/);
 assert.equal((await assign(reviewer,0)).claims[0].ownerId,reviewer);assert.equal((await assign(reviewer,0)).claims[0].version,1);
 await reject(()=>assign(null,0),/application_claim_assignment_changed/);assert.equal((await assign(null,1)).claims[0].version,2);await reject(()=>assign(reviewer,0),/application_claim_assignment_changed/);
 await assign(reviewer,2);await actor(reviewer);assert.equal((await get()).canAssign,false);assert.deepEqual((await get()).owners,[]);await reject(()=>assign(null,3),/forbidden/);
 await actor(outsider);await reject(get,/forbidden/);await actor(null,'anon');await reject(get,/permission denied/);
 await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,reviewer]);await actor(editor);assert.equal((await get()).claims[0].eligible,false);await reject(()=>assign(reviewer,3),/application_claim_owner_unavailable/);
