 await root();await db.query("update cms.permissions set record_id=$1 where role_id=$2 and action in ('view','approve')",[saved.recordId,reviewerRole]);await actor(editor);assert.deepEqual((await get()).owners.map(o=>o.id),[reviewer]);
 const unrelated=(await db.query("select cms.save_draft($1,null,null,'application','/applications/unrelated-claims','Other',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;
 assert.deepEqual((await db.query('select cms.get_application_claim_owners($1,$2,$3) value',[site,unrelated.recordId,unrelated.revisionId])).rows[0].value.owners,[]);
 await root();await db.query("update cms.memberships set expires_at=now()-interval '1 day' where website_id=$1 and user_id=$2",[site,reviewer]);await actor(editor);assert.equal((await get()).claims[0].eligible,false);assert.deepEqual((await get()).owners,[]);await root();await db.query('update cms.memberships set expires_at=null where website_id=$1 and user_id=$2',[site,reviewer]);await actor(editor);
 const next=(await db.query("select cms.save_draft($1,$2,$3,'application','/applications/claim-owners','Claims',$4::jsonb) value",[site,saved.recordId,saved.revisionId,JSON.stringify({...payload,summary:'Updated'})])).rows[0].value;
 await reject(get,/application_revision_changed/);await reject(()=>assign(null,3),/application_revision_changed/);assert.equal((await get(next.revisionId)).claims[0].version,0);
 await root();assert.equal((await db.query("select count(*)::int n from cms.audit_events where record_id=$1 and action='application.claim_owner_assigned'",[saved.recordId])).rows[0].n,3);
