test('application publication checks related delivery and permits repairing a published cycle with the candidate revision',async()=>{
 const {newApplication}=await import('../lib/cms/applications.ts');await root();await db.exec('begin');try{
 await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,'application-cycle-image','private/application-cycle',$2,'image/webp',100,80,40,'ready','approved','Synthetic permission')",[site,'d'.repeat(64)]);
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 const draft=slug=>({...newApplication(),title:slug,slug,summary:'Summary',body:[{id:'intro',kind:'paragraph',text:'Overview'}]});
 const prepare=async(payload,previous=null)=>{await actor(editor);const saved=(await db.query("select cms.save_draft($1,$2,$3,'application',$4,$5,$6::jsonb) value",[site,previous?.recordId??null,previous?.revisionId??null,'/applications/'+payload.slug,payload.title,JSON.stringify(payload)])).rows[0].value;await review(saved,'submit');await actor(reviewer);await review(saved,'approve');await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:saved.recordId,revision:saved.revisionId})).contentChecksPass,true);return saved;};
 const release=async(saved)=>{await actor(publisher);await publish(saved);};
 const a0={...draft('release-cycle-a'),image:{assetId:'application-cycle-image',alt:'Cycle',decorative:false}};let a=await prepare(a0);await release(a);
 const b0=draft('release-cycle-b');b0.relationships.applications=[{recordId:a.recordId}];const b=await prepare(b0);await release(b);
 const a1={...a0,relationships:{...a0.relationships,applications:[{recordId:b.recordId}]}};a=await prepare(a1,a);await release(a);
 const read=async()=>{await actor(null,'anon');return(await db.query("select cms.get_public_application($1,'/applications/release-cycle-a') value",[site])).rows[0].value;};assert.ok(await read());
 const c0=draft('release-cycle-c');c0.relationships.applications=[{recordId:b.recordId}];const c=await prepare(c0);
 await root();await db.exec('savepoint related_withdrawal');await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id='application-cycle-image'",[site]);await actor(publisher);
 await db.exec('savepoint rejected_related_release');await assert.rejects(()=>publish(c),/application_publication_relationship_unavailable/);await db.exec('rollback to savepoint rejected_related_release');await db.exec('rollback to savepoint related_withdrawal');
 await root();await db.query("update cms.media_objects set rights_status='revoked' where website_id=$1 and id='application-cycle-image'",[site]);assert.equal(await read(),null);
 const fixed={...a1};delete fixed.image;a=await prepare(fixed,a);await release(a);assert.equal((await read()).revisionId,a.revisionId);
 // A directly selected record still exists, but its own public dependencies fail.
 await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,b.recordId,b.revisionId]);assert.equal(await read(),null);
 await actor(null,'service_role');assert.equal((await runTrustedValidation(rpc,{site,record:a.recordId,revision:a.revisionId})).contentChecksPass,false);
 }finally{await db.exec('rollback');await root();}
});

test('application schedules reject incomplete content, stale revisions and revoked publishers and support withdrawal',async()=>{
 const {newApplication}=await import('../lib/cms/applications.ts');const {createPublicationScheduleAdapter}=await import('../lib/cms/publication-schedule-database.ts');const {runPublicationScheduleBatch}=await import('../lib/cms/publication-schedule-worker.ts');
 await root();await db.exec('begin');try{
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) result`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].result;};
 const adapter=createPublicationScheduleAdapter(rpc,rpc);
 const enqueue=async(application,operation)=>{await actor(publisher);const id=(await db.query("select cms.schedule_publication($1,$2,$3,$4,now()+interval '1 hour') value",[site,application.recordId,application.revisionId,operation])).rows[0].value;await root();await db.query("update cms.publication_schedules set run_at=now()-interval '1 second',next_attempt_at=now()-interval '1 second' where id=$1",[id]);return id;};
 for(const kind of ['application','industry'])for(const mode of ['ready','incomplete','publisher','stale']){
  await db.exec('savepoint scheduled_application_case');await actor(editor);
  const payload={...newApplication(kind),title:'Scheduled Application',slug:'scheduled-application',summary:mode==='incomplete'?'':'Scheduled update',body:[{id:'intro',kind:'paragraph',text:'A scheduled update'}]};const path=kind==='industry'?'/industries/scheduled-application':'/applications/scheduled-application';const application=(await db.query("select cms.save_draft($1,null,null,'application',$3,'Scheduled Application',$2::jsonb) value",[site,JSON.stringify(payload),path])).rows[0].value;
  await db.query("select cms.review($1,$2,$3,'submit')",[site,application.recordId,application.revisionId]);await actor(reviewer);await db.query("select cms.review($1,$2,$3,'approve')",[site,application.recordId,application.revisionId]);
  const schedule=await enqueue(application,'publish');
  if(mode==='stale'){await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'application',$5,'Changed answer',$4::jsonb)",[site,application.recordId,application.revisionId,JSON.stringify({...payload,title:'Changed answer'}),path]);await root();}
  if(mode==='publisher')await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,publisher]);
  await actor(null,'service_role');const outcomes=await runPublicationScheduleBatch(adapter);assert.deepEqual(outcomes.find(x=>x.id===schedule),{id:schedule,status:mode==='ready'?'published':'blocked'});
  await root();const state=(await db.query('select status,error_code from cms.publication_schedules where id=$1',[schedule])).rows[0];assert.equal(state.error_code,mode==='ready'?null:mode==='incomplete'?'validation_failed':'publication_guard_failed');
  assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[application.recordId])).rows[0].published_revision_id,mode==='ready'?application.revisionId:null);
  if(mode==='ready'){
   assert.equal((await db.query('select validator_version from cms.validations where revision_id=$1',[application.revisionId])).rows[0].validator_version,'application-1');
   const withdrawal=await enqueue(application,'unpublish');await actor(null,'service_role');assert.deepEqual((await runPublicationScheduleBatch(adapter)).find(x=>x.id===withdrawal),{id:withdrawal,status:'unpublished'});
   await root();assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[application.recordId])).rows[0].published_revision_id,null);
  }
  await db.exec('rollback to savepoint scheduled_application_case');
 }
 }finally{await db.exec('rollback');await root();}
});

test('application translations preserve draft content and route identity but require fresh independent review',async()=>{
 const {newApplication,applicationSchema}=await import('../lib/cms/applications.ts');await root();await db.exec('begin');try{
 for(const kind of ['application','industry']){await db.exec('savepoint application_translation_case');const path=kind==='industry'?'/industries/translated-application':'/applications/translated-application';await actor(editor);const payload={...newApplication(kind),title:'Source Application',slug:'translated-application',seo:{...newApplication().seo,canonical:'https://example.test/source'}};
 const source=(await db.query("select cms.save_draft($1,null,null,'application',$3,'Source application',$2::jsonb) value",[site,JSON.stringify(payload),path])).rows[0].value,key=randomUUID();
 const create=async()=>(await db.query("select cms.create_translation_draft($1,$2,$3,'fr',$5,$4) value",[site,source.recordId,source.revisionId,key,path])).rows[0].value;
 const translated=await create();assert.deepEqual(await create(),translated);
 const detail=(await db.query('select cms.get_editor_record($1,$2) value',[site,translated.recordId])).rows[0].value;
 assert.equal(detail.locale,'fr');assert.equal(detail.path,path);assert.deepEqual(detail.payload,{...payload,seo:{...payload.seo,canonical:''}});assert.equal(applicationSchema.safeParse(detail.payload).success,true);assert.equal(detail.publishedRevision,null);
 const status=async()=>(await db.query('select cms.get_translation_status($1,$2) value',[site,translated.recordId])).rows[0].value;
 assert.equal((await status()).status,'unreviewed');
 await db.exec('savepoint own_translation');await assert.rejects(()=>db.query('select cms.review_translation($1,$2,$3,$4)',[site,translated.recordId,translated.revisionId,source.revisionId]),/separate_approver_required/);await db.exec('rollback to savepoint own_translation');
 await actor(reviewer);await db.query('select cms.review_translation($1,$2,$3,$4)',[site,translated.recordId,translated.revisionId,source.revisionId]);assert.equal((await status()).status,'current');
 await actor(editor);await db.query("select cms.save_draft($1,$2,$3,'application',$5,'Updated source',$4::jsonb)",[site,source.recordId,source.revisionId,JSON.stringify({...payload,title:'Updated source'}),path]);assert.equal((await status()).status,'source_changed');assert.deepEqual(await create(),translated);
 const family=(await db.query('select cms.get_translation_family($1,$2,null) value',[site,translated.recordId])).rows[0].value;assert.equal(family.source.id,source.recordId);assert.equal(family.translations[0].type,'application');
 await actor(outsider);await db.exec('savepoint hidden_translation');await assert.rejects(()=>status(),/forbidden/);await db.exec('rollback to savepoint hidden_translation');
 await root();await db.exec('rollback to savepoint application_translation_case');}
 }finally{await db.exec('rollback');await root();}
});

test('application import review checks scoped draft targets and references without writes or approval',async()=>{
 const {newApplication}=await import('../lib/cms/applications.ts');await root();await db.exec('begin');try{
 await actor(editor);const payload={...newApplication(),slug:'import-review-application'};
 const saved=(await db.query("select cms.save_draft($1,null,null,'application',$2,$3,$4::jsonb) value",[site,`/applications/${payload.slug}`,'Import review',JSON.stringify(payload)])).rows[0].value;
 const related=(await db.query("select cms.save_draft($1,null,null,'project','/projects/application-import-related','Related','{}'::jsonb) value",[site])).rows[0].value;
 const references=[{recordId:related.recordId,type:'project'},{recordId:otherSite,type:'document'}];
 const check=async({create=false,records=[saved.recordId],refs=references,target=site,assets=['missing-image']}={})=>(await db.query('select cms.review_application_import_links($1,$2,$3,$4,$5::jsonb) value',[target,create,records,assets,JSON.stringify(refs)])).rows[0].value;
 const initial=await check();assert.deepEqual(initial.assets,[{assetId:'missing-image',available:false}]);assert.deepEqual(initial.references,[{...references[0],available:true,revision:related.revisionId},{...references[1],available:false,revision:null}]);
 assert.deepEqual((await check({refs:[{recordId:saved.recordId,type:'document'}]})).references,[{recordId:saved.recordId,type:'document',available:false,revision:null}]);
 const updated=(await db.query("select cms.save_draft($1,$2,$3,'application',$4,$5,$6::jsonb) value",[site,saved.recordId,saved.revisionId,`/applications/${payload.slug}`,'Updated',JSON.stringify(payload)])).rows[0].value;
 assert.equal((await check()).references[0].revision,related.revisionId);assert.notEqual(updated.revisionId,saved.revisionId);
 for(const args of [{refs:[...references,references[0]]},{assets:['duplicate','duplicate']},{target:otherSite},{create:false,records:[]}]){await db.exec('savepoint rejected_project_import');await assert.rejects(()=>check(args));await db.exec('rollback to savepoint rejected_project_import');}
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='view'",[site,editorRole]);await actor(editor);
 // Create permission alone cannot reveal target metadata or permit updating hidden records.
 const hidden=await check({create:true,records:[]});assert.equal(hidden.references[0].available,false);assert.equal(hidden.references[0].revision,null);
 await db.exec('savepoint hidden_update');await assert.rejects(()=>check(),/forbidden/);await db.exec('rollback to savepoint hidden_update');
 await actor(outsider);await db.exec('savepoint outside_import');await assert.rejects(()=>check({create:true,records:[]}),/forbidden/);await db.exec('rollback to savepoint outside_import');
 await actor(null,'anon');await db.exec('savepoint anonymous_import');await assert.rejects(()=>check(),/permission denied/);await db.exec('rollback to savepoint anonymous_import');
 }finally{await db.exec('rollback');await root();}
});


test('application import cancellation fences delayed saves and recovers already completed requests',async()=>{
 const {newApplication}=await import('../lib/cms/applications.ts');await root();await db.exec('begin');try{
 await actor(editor);const key=randomUUID(),source='a'.repeat(64),review='b'.repeat(64);
 const item={sourceKey:`application_import_${'9'.repeat(64)}`,operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newApplication(),slug:'cancel-import-fixture'}};
 const cancel=async(request=key,digest=source)=>(await db.query('select cms.cancel_application_import($1,$2,$3,$4) value',[site,request,digest,review])).rows[0].value;
 const apply=async(request=key)=>(await db.query('select cms.apply_application_import($1,$2,$3,$4,$5::jsonb,$6::jsonb) value',[site,request,source,review,JSON.stringify([item]),JSON.stringify({assets:[],references:[]})])).rows[0].value;
 const first=await cancel();assert.equal(first.status,'cancelled');assert.deepEqual(await cancel(),first);assert.deepEqual((await db.query('select cms.get_application_import_receipt($1,$2) value',[site,key])).rows[0].value,first);
 await db.exec('savepoint delayed_import');await assert.rejects(()=>apply(),/application_import_cancelled/);await db.exec('rollback to savepoint delayed_import');
 await db.exec('savepoint bypass_fence');await assert.rejects(()=>db.query('select cms.apply_application_import_before_cancellation($1,$2,$3,$4,$5::jsonb,$6::jsonb)',[site,key,source,review,JSON.stringify([item]),JSON.stringify({assets:[],references:[]})]),/permission denied/);await db.exec('rollback to savepoint bypass_fence');
 await db.exec('savepoint changed_identity');await assert.rejects(()=>cancel(key,'c'.repeat(64)),/idempotency_key_reused/);await db.exec('rollback to savepoint changed_identity');
 const completedKey=randomUUID(),saved=await apply(completedKey),completed=await cancel(completedKey);assert.deepEqual(completed.result,saved);assert.equal(completed.status,undefined);assert.deepEqual(await apply(completedKey),saved);
 await actor(reviewer);assert.equal((await db.query('select cms.get_application_import_receipt($1,$2) value',[site,key])).rows[0].value,null);
 await actor(outsider);await db.exec('savepoint outside_cancel');await assert.rejects(()=>cancel(),/forbidden/);await db.exec('rollback to savepoint outside_cancel');
 }finally{await db.exec('rollback');await root();}
});

test('application Office apply is atomic, revision-bound, actor-scoped and recoverable without publication',async()=>{
 const {newApplication}=await import('../lib/cms/applications.ts');await root();await db.exec('begin');try{
 await actor(editor);const request=randomUUID();
 const item={sourceKey:`application_import_${'a'.repeat(64)}`,operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newApplication(),slug:'import-atomic-application'}};
 const empty={assets:[],references:[]};
 const apply=async(items=[item],key=request,evidence=empty)=>(await db.query('select cms.apply_application_import($1,$2,$3,$4,$5::jsonb,$6::jsonb) value',[site,key,'a'.repeat(64),'b'.repeat(64),JSON.stringify(items),JSON.stringify(evidence)])).rows[0].value;
 const receipt=async()=>(await db.query('select cms.get_application_import_receipt($1,$2) value',[site,request])).rows[0].value;
 const invalid={...item,sourceKey:`application_import_${'b'.repeat(64)}`,payload:{...item.payload,slug:'invalid slug'}};
 await db.exec('savepoint atomic_failure');await assert.rejects(()=>apply([item,invalid]),/invalid_import_item/);await db.exec('rollback to savepoint atomic_failure');
 assert.equal(await receipt(),null);assert.equal((await db.query('select count(*)::int n from cms.records where path=$1',['/applications/import-atomic-application'])).rows[0].n,0);
 const result=await apply();assert.equal(result.length,1);assert.deepEqual(await apply(),result);assert.deepEqual((await receipt()).result,result);
 assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[result[0].recordId])).rows[0].published_revision_id,null);
 await db.exec('savepoint reused_key');await assert.rejects(()=>apply([{...item,payload:{...item.payload,title:'Different'}}]),/idempotency_key_reused/);await db.exec('rollback to savepoint reused_key');
 const update={...item,operation:'update',recordId:result[0].recordId,expectedRevision:result[0].revisionId,payload:{...item.payload,title:'Updated'}};
 const updated=await apply([update],randomUUID());assert.notEqual(updated[0].revisionId,result[0].revisionId);
 await db.exec('savepoint stale_import');await assert.rejects(()=>apply([update],randomUUID()),/revision_conflict/);await db.exec('rollback to savepoint stale_import');
 // Exact old receipt remains recoverable after later edits; it never reapplies them.
 assert.deepEqual(await apply(),result);
 const page=(await db.query("select cms.save_draft($1,null,null,'project','/projects/application-import-atomic-related','Related','{}'::jsonb) value",[site])).rows[0].value;
 const related={...item,sourceKey:`application_import_${'c'.repeat(64)}`,payload:{...item.payload,slug:'import-related-application',relationships:{...item.payload.relationships,projects:[{recordId:page.recordId}]}}};
 const evidence={assets:[],references:[{recordId:page.recordId,type:'project',available:true,revision:page.revisionId}]};
 for(const e of [empty,{...evidence,references:[{...evidence.references[0],revision:result[0].revisionId}]}]){await db.exec('savepoint missing_evidence');await assert.rejects(()=>apply([related],randomUUID(),e),/import_evidence_changed/);await db.exec('rollback to savepoint missing_evidence');}
 assert.equal((await apply([related],randomUUID(),evidence)).length,1);
 await db.exec('savepoint duplicate_source');await assert.rejects(()=>apply([item],randomUUID()),/import_key_already_exists/);await db.exec('rollback to savepoint duplicate_source');
 await root();const asset='application-import-rights-check';await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'e'.repeat(64)]);await actor(editor);
 const pictured={...item,sourceKey:`application_import_${'d'.repeat(64)}`,payload:{...item.payload,slug:'import-pictured-application',image:{assetId:asset,alt:'Example',decorative:false}}};
 const mediaEvidence={assets:[{assetId:asset,available:true}],references:[]};
 await root();await db.query("update cms.media_objects set rights_status='pending' where website_id=$1 and id=$2",[site,asset]);await actor(editor);
 await db.exec('savepoint revoked_image');await assert.rejects(()=>apply([pictured],randomUUID(),mediaEvidence),/import_evidence_changed/);await db.exec('rollback to savepoint revoked_image');
 await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await actor(editor);assert.equal((await apply([pictured],randomUUID(),mediaEvidence)).length,1);
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='view'",[site,editorRole]);await actor(editor);
 await db.exec('savepoint revoked_reference');await assert.rejects(()=>apply([{...related,sourceKey:`application_import_${'e'.repeat(64)}`,payload:{...related.payload,slug:'import-hidden-reference'}}],randomUUID(),evidence),/import_evidence_changed/);await db.exec('rollback to savepoint revoked_reference');
 await actor(reviewer);assert.equal(await receipt(),null);await actor(outsider);assert.equal(await receipt(),null);
 await db.exec('savepoint outside_apply');await assert.rejects(()=>apply(),/forbidden/);await db.exec('rollback to savepoint outside_apply');
 }finally{await db.exec('rollback');await root();}
});

test('application Office HTTP review and lost-response recovery use the real database receipt',async()=>{
 const {handleApplicationImportUpload}=await import('../lib/cms/application-import-api.ts');const {zip}=await import('./office-fixtures.mjs');
 await root();await db.exec('begin');try{await actor(editor);
 const row=cells=>'<w:tr>'+cells.map(v=>'<w:tc><w:p><w:r><w:t>'+v+'</w:t></w:r></w:p></w:tc>').join('')+'</w:tr>';
 const bytes=zip({'[Content_Types].xml':'<Types/>','word/document.xml':'<w:document xmlns:w="urn:w"><w:body><w:tbl>'+row(['CMSApplication','1.0','application'])+'</w:tbl><w:tbl>'+row(['Pages'])+row(['recordId','operation','title','slug','locale','kind'])+row(['http-leader','create','HTTP leader','http-import-leader','en','industry'])+'</w:tbl></w:body></w:document>'});
 const request=randomUUID();let lose=true,writes=0;
 const call=async(token,name,args)=>{assert.equal(token,'a.b.c');const entries=Object.entries(args),value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>['p_items','p_evidence','p_references'].includes(key)?JSON.stringify(value):value))).rows[0].value;
 if(name==='apply_application_import'){writes++;if(lose){lose=false;throw Error('Synthetic response lost after commit');}}return value;};
 const upload=(action,review)=>new Request('https://cms.test/api/cms/import/application',{method:'POST',headers:{Authorization:'Bearer a.b.c','X-CMS-Site':site,'X-CMS-Format':'docx','X-CMS-Action':action,...(action!=='review'?{'Idempotency-Key':request,'X-CMS-Review':review}:{})},body:action==='status'?undefined:bytes});
 const response=await handleApplicationImportUpload(upload('review'),call);assert.equal(response.status,200);const reviewed=await response.json();assert.equal(reviewed.applyAvailable,true);assert.equal(writes,0);
 const lost=await handleApplicationImportUpload(upload('apply',reviewed.reviewDigest),call);assert.equal(lost.status,500);assert.equal(writes,1);
 const recovered=await(await handleApplicationImportUpload(upload('status',reviewed.reviewDigest),call)).json();assert.equal(recovered.status,'complete');assert.equal(recovered.result.length,1);
 const replay=await(await handleApplicationImportUpload(upload('apply',reviewed.reviewDigest),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,recovered.result);assert.equal(writes,1);
 const stored=(await db.query('select internal_title,published_revision_id from cms.records where id=$1',[recovered.result[0].recordId])).rows[0];assert.equal(stored.internal_title,'HTTP leader');assert.equal(stored.published_revision_id,null);
 }finally{await db.exec('rollback');await root();}
});

