test('career form evidence tracks published definitions, withdrawal and unsupported submission fields',async()=>{
 const {newCareer}=await import('../lib/cms/careers.ts');const {runTrustedValidation}=await import('../lib/cms/validation-worker.ts');await root();await db.exec('begin');
 try{await actor(editor);const definition=newForm('name');const form=(await db.query("select cms.save_draft($1,null,null,'form',null,'Career application',$2::jsonb) value",[site,JSON.stringify(definition)])).rows[0].value;
 const payload={...newCareer(),slug:'form-evidence',organization:'Example',summary:'Example role',employment:'fullTime',workMode:'remote',remoteRegions:['India'],postedOn:'2026-10-30',application:{mode:'form',label:'Apply',formId:form.recordId},body:[{id:'intro',kind:'paragraph',text:'Job details'}]};
 const career=(await db.query("select cms.save_draft($1,null,null,'career','/careers/form-evidence','Job',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 const check=async()=>{await actor(null,'service_role');return runTrustedValidation(rpc,{site,record:career.recordId,revision:career.revisionId});};
 assert.equal((await check()).contentChecksPass,false);
 // Root pointers are rolled-back evidence fixtures, not publication-policy bypasses in application code.
 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[form.revisionId,form.recordId]);assert.equal((await check()).contentChecksPass,true);
 await root();await db.query('update cms.records set published_revision_id=null where id=$1',[form.recordId]);assert.equal((await check()).contentChecksPass,false);
 for(const changed of [{...definition,notificationRouteIds:[randomUUID()]},{...definition,fields:[]},{...definition,fields:[{id:'cv',type:'file',label:'CV',required:true,maxBytes:1000000,mimeTypes:['application/pdf']}]}]){
  await actor(editor);const saved=(await db.query("select cms.save_draft($1,null,null,'form',null,'Unsupported job form',$2::jsonb) value",[site,JSON.stringify(changed)])).rows[0].value;
  await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[saved.revisionId,saved.recordId]);
  await actor(editor);const next=(await db.query("select cms.save_draft($1,$2,$3,'career','/careers/form-evidence','Job',$4::jsonb) value",[site,career.recordId,career.revisionId,JSON.stringify({...payload,application:{...payload.application,formId:saved.recordId}})])).rows[0].value;career.revisionId=next.revisionId;
  assert.equal((await check()).contentChecksPass,false);
 }
 }finally{await db.exec('rollback');await root();}
});

