test('career namespace migration preserves existing aliases and prevents new reserved aliases',async()=>{
 await root();await db.exec('begin');try{
 await actor(editor);const target=(await db.query("select cms.save_draft($1,null,null,'page','/career-redirect-target','Target','{}'::jsonb) value",[site])).rows[0].value;
 await root();const migration=await fs.readFile(new URL('../database/cms/377-career-route-ownership.sql',import.meta.url),'utf8'),guard=migration.slice(migration.indexOf('do $$'),migration.indexOf('create or replace function'));
 const previous=await fs.readFile(new URL('../database/cms/368-location-route-ownership.sql',import.meta.url),'utf8');
 for(const source of ['/careers/old']){
 await db.exec('savepoint alias_case');const proposal=randomUUID();
 await db.query("insert into cms.page_url_proposals(id,website_id,record_id,revision_id,old_path,new_path,locale,impact_snapshot,redirect_choice,status,created_by,request_id,manifest) values($1,$2,$3,$4,$5,'/career-redirect-target','en',$6,'permanent','approved',$7,$8,'{}')",[proposal,site,target.recordId,target.revisionId,source,'a'.repeat(32),editor,randomUUID()]);
 const insert=()=>db.query("insert into cms.page_redirects(website_id,locale,source_path,record_id,proposal_id) values($1,'en',$2,$3,$4)",[site,source,target.recordId,proposal]);
 await db.exec('savepoint new_alias');await assert.rejects(insert,/check constraint/);await db.exec('rollback to savepoint new_alias');
 // Recreate the pre-migration eligibility rule to represent a genuine older alias.
 await db.exec(previous.slice(previous.indexOf('create or replace function'),previous.indexOf('create function cms.enforce')));await insert();
 await db.exec('savepoint old_alias');await assert.rejects(()=>db.exec(guard),/career_namespace_occupied/);await db.exec('rollback to savepoint old_alias');
 assert.equal((await db.query('select source_path from cms.page_redirects where proposal_id=$1',[proposal])).rows[0].source_path,source);
 await db.exec('rollback to savepoint alias_case');
 }
 }finally{await db.exec('rollback');await root();}
});

