 await fail(()=>db.query('select cms.get_career_validation_evidence($1,$2,$3)',[site,saved.recordId,saved.revisionId]),/permission denied/);
 await actor(null,'service_role');const input=(await db.query('select cms.get_validation_input($1,$2,$3) value',[site,saved.recordId,saved.revisionId])).rows[0].value;assert.deepEqual(input.careerEvidence,{websiteId:site,recordId:saved.recordId,revisionId:saved.revisionId,applicationForm:null,references:[],media:[{assetId:'career-release-image',available:true}],links:[]});
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 assert.equal((await runTrustedValidation(rpc,{site,record:saved.recordId,revision:saved.revisionId})).contentChecksPass,true);
 assert.equal((await db.query('select cms.get_career_validation_evidence($1,$2,$3) value',[otherSite,saved.recordId,saved.revisionId])).rows[0].value,null);
 await actor(editor);await review(saved,'submit');await actor(reviewer);await review(saved,'approve');
