 await actor(editor);const payload={...newCareer(),slug:'related-job',title:'Advisor',summary:'Guest support',organization:'Example',employment:'fullTime',workMode:'onSite',postedOn:'2026-10-30',relationships:{locations:[{recordId:related.recordId}],documents:[],pages:[]},application:{mode:'external',label:'Apply',url:'https://example.test/apply'},body:[{id:'intro',kind:'paragraph',text:'Job details'}]};
 const job=(await db.query("select cms.save_draft($1,null,null,'career','/careers/related-job','Advisor',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;assert.equal((await check(job)).contentChecksPass,true);await approve(job);
 await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,related.recordId,related.revisionId]);await fail(()=>publish(job),/career_publication_evidence_changed|career_publication_relationship_unavailable/);await publish(related);await publish(job);
 await actor(null,'anon');const read=async()=>(await db.query("select cms.get_public_career($1,'/careers/related-job') value",[site])).rows[0].value;assert.deepEqual((await read()).related,[{type:'location',recordId:related.recordId,title:'Workplace',href:'/locations/job-workplace'}]);
 await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,related.recordId,related.revisionId]);await actor(null,'anon');assert.equal(await read(),null);
 await actor(editor);const form=(await db.query("select cms.save_draft($1,null,null,'form',null,'Job form',$2::jsonb) value",[site,JSON.stringify({...newForm('name'),notificationRouteIds:[site]})])).rows[0].value;await installNotificationFixture(form);assert.equal((await check(form)).contentChecksPass,true);await approve(form);await actor(publisher);await publish(form);await actor(editor);
 const formJob=(await db.query("select cms.save_draft($1,null,null,'career','/careers/form-release','Job form',$2::jsonb) value",[site,JSON.stringify({...payload,slug:'form-release',workMode:'remote',remoteRegions:['India'],relationships:{locations:[],documents:[],pages:[]},application:{mode:'form',label:'Apply',formId:form.recordId}})])).rows[0].value;assert.equal((await check(formJob)).contentChecksPass,true);await approve(formJob);
 // Withdrawal after validation must block release, then restored eligibility permits it.
