 await root();await db.query('update cms.records set published_revision_id=$1 where id=$2',[form.revisionId,form.recordId]);await actor(publisher);await publish(formJob);
 await actor(null,'anon');const publicJob=(await db.query("select cms.get_public_career($1,'/careers/form-release') value",[site])).rows[0].value;assert.equal(publicJob.revisionId,formJob.revisionId);assert.equal(publicJob.applicationForm.formId,form.recordId);
 await actor(null,'service_role');const application=(await db.query('select cms.get_career_application_form($1,$2,$3,$4,$5) value',[site,formJob.recordId,formJob.revisionId,form.recordId,form.revisionId])).rows[0].value;assert.equal(application.form.revisionId,form.revisionId);
 const {acceptFormEnquiry}=await import('../lib/cms/enquiry-intake.ts');const requestKey=randomUUID();const request={formId:form.recordId,revisionId:form.revisionId,requestKey,answers:{name:'Applicant'},sourcePath:'/careers/form-release',career:{recordId:formJob.recordId,revisionId:formJob.revisionId,slug:'form-release'},challengeToken:'synthetic-verified'};
 const intake={consumeRate:async()=>({allowed:true,retryAfter:1}),verifyChallenge:async()=>true,files:async()=>[],read:async()=>{const v=application.form;return {websiteId:site,formId:v.formId,revisionId:v.revisionId,definition:v.definition};},persist:async input=>(await db.query('select cms.accept_career_enquiry($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7,$8::jsonb) value',[site,input.form,input.revision,input.request,JSON.stringify(input.answers),JSON.stringify(input.consents),input.attribution.sourcePath,JSON.stringify(input.career)])).rows[0].value};
 const accepted=await acceptFormEnquiry(request,site,intake);assert.equal(accepted.status,200);
