test('private enquiry storage denies every public operation despite unrelated permissive policies',async()=>{
 await root();const key=`${site}/enquiries/${randomUUID()}/${randomUUID()}/original`;
 const bucket=(await db.query("select * from storage.buckets where id='cms-enquiry-files'")).rows[0];assert.equal(bucket.public,false);assert.equal(Number(bucket.file_size_limit),25000000);assert.deepEqual(bucket.allowed_mime_types,['application/pdf','image/jpeg','image/png','image/webp']);
 await db.query("insert into storage.objects(bucket_id,name) values('cms-enquiry-files',$1)",[key]);
 for(const role of ['anon','authenticated']){
  await actor(editor,role);assert.equal((await db.query("select * from storage.objects where bucket_id='cms-enquiry-files'")).rows.length,0);
  await assert.rejects(()=>db.query("insert into storage.objects(bucket_id,name) values('cms-enquiry-files',$1)",[key+'-new']),/row-level security/);
  assert.equal((await db.query("update storage.objects set name=$1 where bucket_id='cms-enquiry-files' returning id",[key+'-changed'])).rows.length,0);
  assert.equal((await db.query("delete from storage.objects where bucket_id='cms-enquiry-files' returning id")).rows.length,0);
 }
 await root();assert.equal((await db.query("select name from storage.objects where bucket_id='cms-enquiry-files' and name=$1",[key])).rows.length,1);
});

test('certification storage supports scoped searches, recovery, revision restoration and publication prerequisites',async()=>{
 const {newCertification}=await import('../lib/cms/certifications.ts');await root();await db.exec('begin');
 const rejected=async(fn,pattern)=>{await db.exec('savepoint certification_rejected');await assert.rejects(fn,pattern);await db.exec('rollback to savepoint certification_rejected');};
 try{await actor(editor);const payload={...newCertification(),slug:'certification-storage',title:'Example certificate',status:'active',issuer:'Operations 100%_literal'},key=randomUUID();
 const create=async(request=key)=>(await db.query("select cms.create_draft_once($1,$2,'certification','/certifications/certification-storage',$3,$4::jsonb,'en') value",[site,request,payload.title,JSON.stringify(payload)])).rows[0].value;
 const saved=await create();assert.deepEqual(await create(),saved);
 const other={...newCertification(),slug:'revoked-certificate',title:'Revoked certificate',status:'revoked'};const second=(await db.query("select cms.save_draft($1,null,null,'certification','/certifications/revoked-certificate',$2,$3::jsonb) value",[site,other.title,JSON.stringify(other)])).rows[0].value;
 const find=async(lifecycle='',search='',target=site)=>(await db.query("select cms.search_certification_library($1,$2,'',false,'',null,50,$3) value",[target,search,lifecycle])).rows[0].value;
 assert.deepEqual((await find('active')).records.map(r=>r.id),[saved.recordId]);assert.deepEqual((await find('revoked')).records.map(r=>r.id),[second.recordId]);assert.deepEqual((await find('','100%_literal')).records.map(r=>r.id),[saved.recordId]);assert.deepEqual((await find('','',otherSite)).records,[]);
 const updated=(await db.query("select cms.save_draft($1,$2,$3,'certification','/certifications/certification-storage','New title',$4::jsonb) value",[site,saved.recordId,saved.revisionId,JSON.stringify({...payload,title:'New title'})])).rows[0].value;
 await rejected(()=>db.query("select cms.save_draft($1,$2,$3,'certification','/certifications/certification-storage',$4,$5::jsonb)",[site,saved.recordId,saved.revisionId,payload.title,JSON.stringify(payload)]),/revision|conflict/);
 const restored=(await db.query('select cms.restore_draft($1,$2,$3,$4) value',[site,saved.recordId,saved.revisionId,updated.revisionId])).rows[0].value;const detail=(await db.query('select cms.get_editor_record($1,$2) value',[site,saved.recordId])).rows[0].value;assert.equal(detail.title,payload.title);assert.deepEqual(detail.payload,payload);assert.notEqual(restored.revisionId,saved.revisionId);
 const cancelled=randomUUID();assert.equal((await db.query("select cms.cancel_draft_creation($1,$2,'certification') value",[site,cancelled])).rows[0].value.status,'cancelled');await rejected(()=>create(cancelled),/cancelled/);
 await root();await rejected(()=>db.query("update cms.records set path='/locations/not-a-certificate' where id=$1",[saved.recordId]),/certification_route_invalid/);await rejected(()=>db.query('update cms.records set published_revision_id=$1 where id=$2',[restored.revisionId,saved.recordId]),/approved_revision_required/);
 await db.query("update cms.records set approved_revision_id=$1,review_status='approved' where id=$2",[restored.revisionId,saved.recordId]);
 await rejected(()=>db.query('update cms.records set published_revision_id=$1 where id=$2',[restored.revisionId,saved.recordId]),/validated_revision_required/);
 await actor(outsider);assert.deepEqual((await find()).records,[]);await rejected(()=>create(randomUUID()),/forbidden/);
 }finally{await db.exec('rollback');await root();}
});


