 await reject(()=>assign(editor,0),/certification_claim_owner_unavailable/);await reject(()=>assign(outsider,0),/certification_claim_owner_unavailable/);
 assert.equal((await assign(reviewer,0)).claims[0].ownerId,reviewer);assert.equal((await assign(reviewer,0)).claims[0].version,1);
 await reject(()=>assign(null,0),/certification_claim_assignment_changed/);assert.equal((await assign(null,1)).claims[0].version,2);await reject(()=>assign(reviewer,0),/certification_claim_assignment_changed/);
 await assign(reviewer,2);await actor(reviewer);assert.equal((await get()).canAssign,false);assert.deepEqual((await get()).owners,[]);await reject(()=>assign(null,3),/forbidden/);
 await actor(outsider);await reject(get,/forbidden/);await actor(null,'anon');await reject(get,/permission denied/);
 await root();await db.query('update cms.memberships set revoked_at=now() where website_id=$1 and user_id=$2',[site,reviewer]);await actor(editor);assert.equal((await get()).claims[0].eligible,false);await reject(()=>assign(reviewer,3),/certification_claim_owner_unavailable/);
 await root();await db.query('update cms.memberships set revoked_at=null where website_id=$1 and user_id=$2',[site,reviewer]);await actor(editor);
 await root();await db.query("update cms.permissions set record_id=$1 where role_id=$2 and action in ('view','approve')",[saved.recordId,reviewerRole]);await actor(editor);assert.deepEqual((await get()).owners.map(o=>o.id),[reviewer]);
 const unrelated=(await db.query("select cms.save_draft($1,null,null,'certification','/certifications/unrelated-claims','Other',$2::jsonb) value",[site,JSON.stringify(payload)])).rows[0].value;
 assert.deepEqual((await db.query('select cms.get_certification_claim_owners($1,$2,$3) value',[site,unrelated.recordId,unrelated.revisionId])).rows[0].value.owners,[]);
 await root();await db.query("update cms.memberships set expires_at=now()-interval '1 day' where website_id=$1 and user_id=$2",[site,reviewer]);await actor(editor);assert.equal((await get()).claims[0].eligible,false);assert.deepEqual((await get()).owners,[]);await root();await db.query('update cms.memberships set expires_at=null where website_id=$1 and user_id=$2',[site,reviewer]);await actor(editor);
 const next=(await db.query("select cms.save_draft($1,$2,$3,'certification','/certifications/claim-owners','Claims',$4::jsonb) value",[site,saved.recordId,saved.revisionId,JSON.stringify({...payload,summary:'Updated'})])).rows[0].value;
 await reject(get,/certification_revision_changed/);await reject(()=>assign(null,3),/certification_revision_changed/);assert.equal((await get(next.revisionId)).claims[0].version,0);
 await root();assert.equal((await db.query("select count(*)::int n from cms.audit_events where record_id=$1 and action='certification.claim_owner_assigned'",[saved.recordId])).rows[0].n,3);
 await actor(editor);await reject(()=>db.query('select * from cms.certification_claim_owners'),/permission denied/);
