 await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,'claim-certification-image','private/claim-certification',$2,'image/webp',100,80,40,'ready','approved','Synthetic permission')",[site,'c'.repeat(64)]);
 await actor(editor);const docPayload={...newDocument(),access:'authenticated',file:{assetId:asset,downloadName:'certificate.pdf'}},doc=(await db.query("select cms.save_draft($1,null,null,'document',null,'Evidence',$2::jsonb) value",[site,JSON.stringify(docPayload)])).rows[0].value;
 const certificationPayload={...newCertification(),slug:'signed-claims',seo:{...newCertification().seo,socialImage:{assetId:'claim-certification-image',alt:'Certificate mark',decorative:false}},summary:'Synthetic certificate',issuer:'Example issuer',scope:'Example site',statement:'Synthetic performance claim',evidence:[{recordId:doc.recordId}],issuedOn:'2020-01-01',validFrom:'2020-01-01',validity:'dated',expiresOn:'2099-01-01',reviewOn:'2099-01-01'},certification=(await db.query("select cms.save_draft($1,null,null,'certification','/certifications/signed-claims','Claims',$2::jsonb) value",[site,JSON.stringify(certificationPayload)])).rows[0].value;const claim=certification.recordId;
 const scope=[site,certification.recordId,certification.revisionId,claim],review=async()=>(await db.query('select cms.review_certification_claim($1,$2,$3,$4) value',scope)).rows[0].value;
