 const approve=async(r)=>(await db.query('select cms.approve_certification_claim($1,$2,$3,$4,$5,$6::jsonb) value',[...scope,r.assignmentVersion,JSON.stringify(r.snapshot)])).rows[0].value;
 await assign(reviewer,0);let r=await review();assert.equal(r.canApprove,false);assert.ok(r.snapshot);await reject(()=>approve(r),/claim_approval_unavailable/);
 await actor(reviewer);r=await review();assert.equal(r.canApprove,true);const signed=await approve(r);assert.ok(signed.approvalId);assert.equal((await approve(r)).approvalId,signed.approvalId);
 const trustedClaim=async()=>{await actor(null,'service_role');const value=(await db.query('select cms.certification_claim_approval_current($1,$2,$3,$4) value',scope)).rows[0].value;await actor(reviewer);return value;};assert.equal(await trustedClaim(),true);
 const validate=async()=>{await actor(null,'service_role');const result=await runTrustedValidation(async(name,args)=>{if(name==='get_validation_input')return (await db.query('select cms.get_validation_input($1,$2,$3) value',[args.p_site,args.p_record,args.p_revision])).rows[0].value;await db.query('select cms.record_validation($1,$2,$3,$4,$5,$6::jsonb)',[args.p_site,args.p_record,args.p_revision,args.p_version,args.p_valid,JSON.stringify(args.p_findings)]);},{site,record:certification.recordId,revision:certification.revisionId});await actor(reviewer);return result;};
 assert.equal((await validate()).contentChecksPass,true);
 await root();assert.equal((await db.query('select validator_version from cms.validations where revision_id=$1',[certification.revisionId])).rows[0].validator_version,'certification-1');await actor(reviewer);
 await reject(()=>db.query('select cms.get_certification_validation_evidence($1,$2,$3)',scope.slice(0,3)),/permission denied/);
 await db.exec('savepoint certification_public_read');await root();
 await root();await db.exec('savepoint certification_translation_authority');await actor(editor);
 const translatedClaim=(await db.query("select cms.create_translation_draft($1,$2,$3,'fr','/certifications/signed-claims',$4) value",[site,certification.recordId,certification.revisionId,randomUUID()])).rows[0].value;
 await root();assert.equal((await db.query('select count(*)::int n from cms.certification_claim_owners where website_id=$1 and record_id=$2',[site,translatedClaim.recordId])).rows[0].n,0);
 await actor(null,'service_role');assert.equal((await db.query('select cms.certification_claim_approval_current($1,$2,$3,$2) value',[site,translatedClaim.recordId,translatedClaim.revisionId])).rows[0].value,false);
 await root();await db.exec('rollback to savepoint certification_translation_authority');
 await actor(editor);await db.query("select cms.review($1,$2,$3,'submit')",scope.slice(0,3));await actor(reviewer);await db.query("select cms.review($1,$2,$3,'approve')",scope.slice(0,3));
 await db.exec('savepoint certification_revoked_before_release');await root();await db.query("update cms.document_files set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);await actor(publisher);await reject(()=>db.query('select cms.publish($1,$2,$3)',scope.slice(0,3)),/certification_publication_evidence_changed/);await root();await db.exec('rollback to savepoint certification_revoked_before_release');
 // Exercise the same evidence gate through the real scheduling worker.
 await root();await db.query("update cms.publication_schedules set next_attempt_at=now()+interval '2 days',run_at=now()+interval '2 days' where status in ('pending','running')");
 const {runPublicationScheduleBatch}=await import('../lib/cms/publication-schedule-worker.ts');
 const {createPublicationScheduleAdapter}=await import('../lib/cms/publication-schedule-database.ts');
 const scheduleRpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 const runScheduled=async(operation)=>{
  await actor(publisher);const job=(await db.query("select cms.schedule_publication($1,$2,$3,$4,clock_timestamp()+interval '1 hour') value",[...scope.slice(0,3),operation])).rows[0].value;
  await root();await db.query("update cms.publication_schedules set run_at=now()-interval '1 second',next_attempt_at=now()-interval '1 second' where id=$1",[job]);await actor(null,'service_role');
  return runPublicationScheduleBatch(createPublicationScheduleAdapter(scheduleRpc,scheduleRpc));
 };
 assert.equal((await runScheduled('publish'))[0].status,'published');
 assert.equal((await runScheduled('unpublish'))[0].status,'unpublished');
 // Revoked private evidence blocks execution even after the revision was approved.
 await root();await db.exec('savepoint certification_schedule_revoked');await db.query("update cms.document_files set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);
 assert.equal((await runScheduled('publish'))[0].status,'blocked');await root();await db.exec('rollback to savepoint certification_schedule_revoked');
 assert.equal((await runScheduled('publish'))[0].status,'published');

 const publicRead=async(target=site)=>{await actor(null,'anon');return (await db.query("select cms.get_public_certification($1,'/certifications/signed-claims') value",[target])).rows[0].value;};
 const delivered=await publicRead();assert.ok(delivered);assert.equal((await db.query("select cms.get_public_media($1,'claim-certification-image') value",[site])).rows[0].value.id,'claim-certification-image');assert.equal(delivered.revisionId,certification.revisionId);
 const {projectPublishedCertification}=await import('../lib/cms/published-certification.ts');assert.equal(projectPublishedCertification(delivered,'/certifications/signed-claims').content.statement,certificationPayload.statement);
