 assert.equal(JSON.stringify(delivered).includes(asset),false);assert.equal(JSON.stringify(delivered).includes(doc.recordId),false);assert.equal(await publicRead(otherSite),null);
 assert.equal((await db.query('select cms.list_published_certifications($1) value',[site])).rows[0].value.length,1);
