 await root();await db.query("update cms.document_files set rights_status='revoked' where website_id=$1 and id=$2",[site,asset]);assert.equal(await publicRead(),null);assert.deepEqual((await db.query('select cms.list_published_certifications($1) value',[site])).rows[0].value,[]);
 await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',scope.slice(0,3));assert.equal(await publicRead(),null);assert.equal((await db.query("select cms.get_public_media($1,'claim-certification-image') value",[site])).rows[0].value,null);
 await root();await db.exec('rollback to savepoint certification_public_read');await actor(reviewer);


