 await actor(editor);const changedDoc=(await db.query("select cms.save_draft($1,$2,$3,'document',null,'Evidence',$4::jsonb) value",[site,doc.recordId,doc.revisionId,JSON.stringify({...docPayload,description:'Changed document description'})])).rows[0].value;
