 await db.exec('savepoint evidence_expiry');await root();await db.query('update cms.document_files set rights_expires_at=now() where website_id=$1 and id=$2',[site,asset]);await actor(reviewer);assert.equal((await review()).snapshot,null);await db.exec('rollback to savepoint evidence_expiry');
