test('category release preserves reviewed historical definitions and withdrawal revokes their eligibility',async()=>{
 const {newProductCategory,newProduct}=await import('../lib/cms/products.ts');await root();await db.exec('begin');
 const rejected=async(fn,pattern)=>{await db.exec('savepoint category_release_rejected');await assert.rejects(fn,pattern);await db.exec('rollback to savepoint category_release_rejected');};
 const rpc=async(name,args)=>{const entries=Object.entries(args);return(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>key==='p_findings'?JSON.stringify(value):value))).rows[0].value;};
 const check=async(record)=>{await actor(null,'service_role');const result=await runTrustedValidation(rpc,{site,record:record.recordId,revision:record.revisionId});assert.equal(result.contentChecksPass,true,JSON.stringify(result.findings));};
 const approve=async(record)=>{await actor(editor);await review(record,'submit');await actor(reviewer);await review(record,'approve');};
 const release=async(record)=>{await approve(record);await check(record);await actor(publisher);assert.ok(await publish(record));};
 const read=async(path)=>{await actor(null,'anon');return(await db.query('select cms.get_public_product_category($1,$2) value',[site,path])).rows[0].value;};
 const eligible=async(record)=>{await root();return(await db.query('select cms.product_category_definition_eligible($1,$2,$3) value',[site,record.recordId,record.revisionId])).rows[0].value;};
 try{
 const path='/product-categories/released-category',payload={...newProductCategory(),title:'Released category',slug:'released-category',summary:'Reviewed summary',internalNotes:'PRIVATE CATEGORY NOTE'};
 await actor(editor);const first=(await db.query("select cms.save_draft($1,null,null,'productCategory',$2,$3,$4::jsonb) value",[site,path,payload.title,JSON.stringify(payload)])).rows[0].value;
 assert.equal(await read(path),null);await actor(publisher);await rejected(()=>publish(first),/approved_revision_required/);
 await approve(first);await actor(publisher);await rejected(()=>publish(first),/validated_revision_required/);await check(first);await actor(publisher);await publish(first);
 const publicPage=await read(path);const {projectPublishedProductCategory}=await import('../lib/cms/published-product-category.ts');assert.equal(projectPublishedProductCategory(publicPage,path).content.title,payload.title);const listed=(await db.query('select cms.list_published_product_categories($1) value',[site])).rows[0].value;assert.equal(listed.length,1);assert.equal(listed[0].revisionId,first.revisionId);assert.equal(JSON.stringify(listed).includes('PRIVATE CATEGORY NOTE'),false);assert.equal((await db.query('select cms.list_published_product_categories($1) value',[otherSite])).rows[0].value.length,0);assert.equal(publicPage.payload.title,payload.title);assert.equal(JSON.stringify(publicPage).includes('PRIVATE CATEGORY NOTE'),false);assert.equal('attributeGroups' in publicPage.payload,false);assert.equal(await eligible(first),true);
 await actor(editor);const secondPayload={...payload,title:'New definition title'};const second=(await db.query("select cms.save_draft($1,$2,$3,'productCategory',$4,$5,$6::jsonb) value",[site,first.recordId,first.revisionId,path,secondPayload.title,JSON.stringify(secondPayload)])).rows[0].value;
 assert.equal((await read(path)).revisionId,first.revisionId);assert.equal(await eligible(second),false);await release(second);assert.equal((await read(path)).revisionId,second.revisionId);assert.equal(await eligible(first),true);
 // A product pinned to the reviewed earlier revision remains valid after a newer release.
 await actor(editor);const productPayload={...newProduct(),slug:'historical-pin',code:'001',summary:'Summary',body:[{id:'intro',kind:'paragraph',text:'Details'}],category:{recordId:first.recordId,revisionId:first.revisionId},enquiry:{label:'Ask',href:'https://example.test/contact'}};
 const product=(await db.query("select cms.save_draft($1,null,null,'product','/products/historical-pin','Pinned',$2::jsonb) value",[site,JSON.stringify(productPayload)])).rows[0].value;await check(product);
 await actor(editor);const childPayload={...newProductCategory(),slug:'released-child',summary:'Child summary',parent:{recordId:first.recordId}};
 const child=(await db.query("select cms.save_draft($1,null,null,'productCategory','/product-categories/released-child','Child',$2::jsonb) value",[site,JSON.stringify(childPayload)])).rows[0].value;await release(child);assert.equal((await read('/product-categories/released-child')).parent.title,secondPayload.title);
 await actor(editor);await rejected(()=>db.query('select * from cms.product_category_releases'),/permission denied/);await rejected(()=>db.query('select cms.product_category_definition_eligible($1,$2,$3)',[site,first.recordId,first.revisionId]),/permission denied/);
 await rejected(()=>db.query("select cms.save_draft($1,null,null,'journey','/product-categories/occupied','Wrong','{}')",[site]),/product_category_namespace_reserved/);
 await root();assert.equal((await db.query('select cms.product_category_definition_eligible($1,$2,$3) value',[otherSite,first.recordId,first.revisionId])).rows[0].value,false);
 await actor(publisher);await db.query('select cms.unpublish($1,$2,$3)',[site,first.recordId,second.revisionId]);assert.equal(await eligible(first),false);assert.equal(await eligible(second),false);assert.equal(await eligible(child),false);assert.equal(await read(path),null);assert.equal(await read('/product-categories/released-child'),null);assert.deepEqual((await db.query('select cms.list_published_product_categories($1) value',[site])).rows[0].value,[]);
 await actor(null,'service_role');const rejectedProduct=await runTrustedValidation(rpc,{site,record:product.recordId,revision:product.revisionId});assert.equal(rejectedProduct.contentChecksPass,false);
 // Releasing the latest revision again does not resurrect older withdrawn definitions.
 await check(second);await actor(publisher);await publish(second);assert.equal(await eligible(second),true);assert.equal(await eligible(first),false);
 }finally{await db.exec('rollback');await root();}
});

