test('product_category import cancellation fences delayed saves and recovers already completed requests',async()=>{
 const {newProductCategory}=await import('../lib/cms/products.ts');await root();await db.exec('begin');try{
 await actor(editor);const key=randomUUID(),source='a'.repeat(64),review='b'.repeat(64);
 const item={sourceKey:`product_category_import_${'9'.repeat(64)}`,operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newProductCategory(),slug:'cancel-import-fixture'}};
 const cancel=async(request=key,digest=source)=>(await db.query('select cms.cancel_product_category_import($1,$2,$3,$4) value',[site,request,digest,review])).rows[0].value;
 const apply=async(request=key)=>(await db.query('select cms.apply_product_category_import($1,$2,$3,$4,$5::jsonb,$6::jsonb) value',[site,request,source,review,JSON.stringify([item]),JSON.stringify({assets:[],references:[]})])).rows[0].value;
 const first=await cancel();assert.equal(first.status,'cancelled');assert.deepEqual(await cancel(),first);assert.deepEqual((await db.query('select cms.get_product_category_import_receipt($1,$2) value',[site,key])).rows[0].value,first);
 await db.exec('savepoint delayed_import');await assert.rejects(()=>apply(),/product_category_import_cancelled/);await db.exec('rollback to savepoint delayed_import');
 await db.exec('savepoint bypass_fence');await assert.rejects(()=>db.query('select cms.apply_product_category_import_before_cancellation($1,$2,$3,$4,$5::jsonb,$6::jsonb)',[site,key,source,review,JSON.stringify([item]),JSON.stringify({assets:[],references:[]})]),/permission denied/);await db.exec('rollback to savepoint bypass_fence');
 await db.exec('savepoint changed_identity');await assert.rejects(()=>cancel(key,'c'.repeat(64)),/idempotency_key_reused/);await db.exec('rollback to savepoint changed_identity');
 const completedKey=randomUUID(),saved=await apply(completedKey),completed=await cancel(completedKey);assert.deepEqual(completed.result,saved);assert.equal(completed.status,undefined);assert.deepEqual(await apply(completedKey),saved);
 await actor(reviewer);assert.equal((await db.query('select cms.get_product_category_import_receipt($1,$2) value',[site,key])).rows[0].value,null);
 await actor(outsider);await db.exec('savepoint outside_cancel');await assert.rejects(()=>cancel(),/forbidden/);await db.exec('rollback to savepoint outside_cancel');
 }finally{await db.exec('rollback');await root();}
});

test('product_category Office apply is atomic, revision-bound, actor-scoped and recoverable without publication',async()=>{
 const {newProductCategory}=await import('../lib/cms/products.ts');await root();await db.exec('begin');try{
 await actor(editor);const request=randomUUID();
 const item={sourceKey:`product_category_import_${'a'.repeat(64)}`,operation:'create',recordId:null,expectedRevision:null,locale:'en',payload:{...newProductCategory(),slug:'import-atomic-category'}};
 const empty={assets:[],references:[]};
 const apply=async(items=[item],key=request,evidence=empty)=>(await db.query('select cms.apply_product_category_import($1,$2,$3,$4,$5::jsonb,$6::jsonb) value',[site,key,'a'.repeat(64),'b'.repeat(64),JSON.stringify(items),JSON.stringify(evidence)])).rows[0].value;
 const receipt=async()=>(await db.query('select cms.get_product_category_import_receipt($1,$2) value',[site,request])).rows[0].value;
 const invalid={...item,sourceKey:`product_category_import_${'b'.repeat(64)}`,payload:{...item.payload,slug:'invalid slug'}};
 await db.exec('savepoint atomic_failure');await assert.rejects(()=>apply([item,invalid]),/invalid_import_item/);await db.exec('rollback to savepoint atomic_failure');
 assert.equal(await receipt(),null);assert.equal((await db.query('select count(*)::int n from cms.records where path=$1',['/product-categories/import-atomic-category'])).rows[0].n,0);
 await db.exec('savepoint forged_authority');await assert.rejects(()=>apply([{...item,payload:{...item.payload,approved:true}}],randomUUID()),/invalid_import_item/);await db.exec('rollback to savepoint forged_authority');
 const result=await apply();assert.equal(result.length,1);assert.deepEqual(await apply(),result);assert.deepEqual((await receipt()).result,result);
 assert.equal((await db.query('select published_revision_id from cms.records where id=$1',[result[0].recordId])).rows[0].published_revision_id,null);
 await db.exec('savepoint reused_key');await assert.rejects(()=>apply([{...item,payload:{...item.payload,title:'Different'}}]),/idempotency_key_reused/);await db.exec('rollback to savepoint reused_key');
 const update={...item,operation:'update',recordId:result[0].recordId,expectedRevision:result[0].revisionId,payload:{...item.payload,title:'Updated'}};
 const updated=await apply([update],randomUUID());assert.notEqual(updated[0].revisionId,result[0].revisionId);
 await db.exec('savepoint stale_import');await assert.rejects(()=>apply([update],randomUUID()),/revision_conflict/);await db.exec('rollback to savepoint stale_import');
 // Exact old receipt remains recoverable after later edits; it never reapplies them.
 assert.deepEqual(await apply(),result);
 const page=(await db.query("select cms.save_draft($1,null,null,'productCategory','/product-categories/import-parent','Related',$2::jsonb) value",[site,JSON.stringify({...newProductCategory(),slug:'import-parent'})])).rows[0].value;
 const related={...item,sourceKey:`product_category_import_${'c'.repeat(64)}`,payload:{...item.payload,slug:'import-related-category',parent:{recordId:page.recordId}}};
 const evidence={assets:[],references:[{recordId:page.recordId,type:'productCategory',available:true,revision:page.revisionId,locale:'en',parent:null,attributeGroups:[]}]};
 for(const e of [empty,{...evidence,references:[{...evidence.references[0],revision:result[0].revisionId}]}]){await db.exec('savepoint missing_evidence');await assert.rejects(()=>apply([related],randomUUID(),e),/import_evidence_changed/);await db.exec('rollback to savepoint missing_evidence');}
 assert.equal((await apply([related],randomUUID(),evidence)).length,1);
 await db.exec('savepoint duplicate_source');await assert.rejects(()=>apply([item],randomUUID()),/import_key_already_exists/);await db.exec('rollback to savepoint duplicate_source');
 await root();const asset='product_category-import-rights-check';await db.query("insert into cms.media_objects(website_id,id,storage_key,sha256,mime_type,byte_size,width,height,inspection_status,rights_status,rights_evidence) values($1,$2,$3,$4,'image/webp',100,100,100,'ready','approved','Synthetic permission')",[site,asset,`${site}/${asset}/delivery.webp`,'e'.repeat(64)]);await actor(editor);
 const pictured={...item,sourceKey:`product_category_import_${'d'.repeat(64)}`,payload:{...item.payload,slug:'import-pictured-category',seo:{...item.payload.seo,socialImage:{assetId:asset,alt:'Example',decorative:false}}}};
 const mediaEvidence={assets:[{assetId:asset,available:true}],references:[]};
 await root();await db.query("update cms.media_objects set rights_status='pending' where website_id=$1 and id=$2",[site,asset]);await actor(editor);
 await db.exec('savepoint revoked_image');await assert.rejects(()=>apply([pictured],randomUUID(),mediaEvidence),/import_evidence_changed/);await db.exec('rollback to savepoint revoked_image');
 await root();await db.query("update cms.media_objects set rights_status='approved' where website_id=$1 and id=$2",[site,asset]);await actor(editor);assert.equal((await apply([pictured],randomUUID(),mediaEvidence)).length,1);
 await root();await db.query("delete from cms.permissions where website_id=$1 and role_id=$2 and action='view'",[site,editorRole]);await actor(editor);
 await db.exec('savepoint revoked_reference');await assert.rejects(()=>apply([{...related,sourceKey:`product_category_import_${'e'.repeat(64)}`,payload:{...related.payload,slug:'import-hidden-reference'}}],randomUUID(),evidence),/import_evidence_changed/);await db.exec('rollback to savepoint revoked_reference');
 await actor(reviewer);assert.equal(await receipt(),null);await actor(outsider);assert.equal(await receipt(),null);
 await db.exec('savepoint outside_apply');await assert.rejects(()=>apply(),/forbidden/);await db.exec('rollback to savepoint outside_apply');
 }finally{await db.exec('rollback');await root();}
});


test('productCategory Office HTTP review and lost-response recovery use the real database receipt',async()=>{
 const {handleProductCategoryImportUpload}=await import('../lib/cms/product-category-import-api.ts');const {zip}=await import('./office-fixtures.mjs');
 await root();await db.exec('begin');try{await actor(editor);
 const row=cells=>'<w:tr>'+cells.map(v=>'<w:tc><w:p><w:r><w:t>'+v+'</w:t></w:r></w:p></w:tc>').join('')+'</w:tr>';
 const bytes=zip({'[Content_Types].xml':'<Types/>','word/document.xml':'<w:document xmlns:w="urn:w"><w:body><w:tbl>'+row(['CMSProductCategory','1.0','productCategory'])+'</w:tbl><w:tbl>'+row(['Pages'])+row(['recordId','operation','title','slug','locale'])+row(['http-leader','create','HTTP leader','http-import-leader','en'])+'</w:tbl></w:body></w:document>'});
 const request=randomUUID();let lose=true,writes=0;
 const call=async(token,name,args)=>{assert.equal(token,'a.b.c');const entries=Object.entries(args),value=(await db.query(`select cms.${name}(${entries.map(([key],i)=>`${key} => $${i+1}`).join(',')}) value`,entries.map(([key,value])=>['p_items','p_evidence','p_references'].includes(key)?JSON.stringify(value):value))).rows[0].value;
 if(name==='apply_product_category_import'){writes++;if(lose){lose=false;throw Error('Synthetic response lost after commit');}}return value;};
 const upload=(action,review)=>new Request('https://cms.test/api/cms/import/productCategory',{method:'POST',headers:{Authorization:'Bearer a.b.c','X-CMS-Site':site,'X-CMS-Format':'docx','X-CMS-Action':action,...(action!=='review'?{'Idempotency-Key':request,'X-CMS-Review':review}:{})},body:action==='status'?undefined:bytes});
 const response=await handleProductCategoryImportUpload(upload('review'),call);assert.equal(response.status,200);const reviewed=await response.json();assert.equal(reviewed.applyAvailable,true);assert.equal(writes,0);
 const lost=await handleProductCategoryImportUpload(upload('apply',reviewed.reviewDigest),call);assert.equal(lost.status,500);assert.equal(writes,1);
 const recovered=await(await handleProductCategoryImportUpload(upload('status',reviewed.reviewDigest),call)).json();assert.equal(recovered.status,'complete');assert.equal(recovered.result.length,1);
 const replay=await(await handleProductCategoryImportUpload(upload('apply',reviewed.reviewDigest),call)).json();assert.equal(replay.replayed,true);assert.deepEqual(replay.result,recovered.result);assert.equal(writes,1);
 const stored=(await db.query('select internal_title,published_revision_id from cms.records where id=$1',[recovered.result[0].recordId])).rows[0];assert.equal(stored.internal_title,'HTTP leader');assert.equal(stored.published_revision_id,null);
 }finally{await db.exec('rollback');await root();}
});



